CREATE OR REPLACE VIEW `V_Auction` AS
SELECT *, DATE_ADD(`BeginDate`, INTERVAL `ValidDate` HOUR) AS `dd` FROM `Auction`$$

CREATE OR REPLACE VIEW `V_Auction_Scan` AS
SELECT `Auction`.*, DATE_ADD(`BeginDate`, INTERVAL `ValidDate` HOUR) AS `dd` FROM `Auction` WHERE (DATE_ADD(`BeginDate`, INTERVAL `Random` MINUTE) < NOW(3))$$

