DROP FUNCTION IF EXISTS `fn_hex_to_char`$$
CREATE FUNCTION `fn_hex_to_char`(p_x VARBINARY(100), p_l INT) RETURNS VARCHAR(200)
NOT DETERMINISTIC READS SQL DATA
fn: BEGIN
  DECLARE v_i VARBINARY(10) DEFAULT NULL;
  DECLARE v_digits CHAR(16) DEFAULT NULL;
  DECLARE v_s VARCHAR(100) DEFAULT NULL;
  DECLARE v_h VARCHAR(100) DEFAULT NULL;
  DECLARE v_j INT DEFAULT NULL;
  SET v_digits = '0123456789ABCDEF';
  SET v_j = 0;
  SET v_h = '';
  w1: WHILE v_j < p_l DO
    SET v_j = v_j + 1;
    SET v_i = SUBSTRING(CAST(p_x AS BINARY), v_j, 1);
    SET v_s = CAST(SUBSTRING(v_digits, v_i % 16 + 1, 1) AS CHAR(1));
    SET v_i = v_i / 16;
    SET v_s = CONCAT(CAST(SUBSTRING(v_digits, v_i % 16 + 1, 1) AS CHAR(1)), v_s);
    SET v_h = CONCAT(v_h, v_s);
  END WHILE w1;
  RETURN (v_h);
END$$

