CREATE PROCEDURE `SP_ASSInfo_Add`(IN p_UserID INT, IN p_Name VARCHAR(20), IN p_IDNumber VARCHAR(20), IN p_State INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_Count FROM `AASInfo` WHERE `UserID` = p_UserID LIMIT 1;
  IF v_Count <> 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `AASInfo` (`UserID`, `Name`, `IDNumber`, `State`) VALUES (p_UserID, p_Name, p_IDNumber, p_State);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

