DROP PROCEDURE IF EXISTS `SP_Achievement_Data_Add`$$
CREATE PROCEDURE `SP_Achievement_Data_Add`(IN p_UserID INT, IN p_AchievementID INT, IN p_IsComplete TINYINT(1), IN p_CompletedDate DATETIME(3), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT COUNT(`UserID`) INTO v_count FROM `AchievementData` WHERE `UserID` = p_UserID AND `AchievementID` = p_AchievementID LIMIT 1;
  IF v_count <> 0 THEN
    UPDATE `AchievementData` SET `IsComplete` = p_IsComplete, `CompletedDate` = p_CompletedDate WHERE `UserID` = p_UserID AND `AchievementID` = p_AchievementID;
  ELSE
    INSERT INTO `AchievementData` (`UserID`, `AchievementID`, `IsComplete`, `CompletedDate`) VALUES (p_UserID, p_AchievementID, p_IsComplete, p_CompletedDate);
  END IF;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

