DROP PROCEDURE IF EXISTS `SP_ActiveSystem_Add`$$
CREATE PROCEDURE `SP_ActiveSystem_Add`(INOUT p_ID INT, IN p_UserID INT, IN p_canEagleEyeCounts INT, IN p_canOpenCounts INT, IN p_isShowAll TINYINT(1), IN p_lastFlushTime DATETIME(3), IN p_ChickActiveData LONGTEXT, IN p_LuckystarCoins INT, IN p_ActiveMoney INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_exitCount INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_exitCount FROM `Sys_Active_System_Data` WHERE `UserID` = p_UserID LIMIT 1;
  IF (v_exitCount = 0) THEN
    INSERT INTO `Sys_Active_System_Data` (`canEagleEyeCounts`, `canOpenCounts`, `isShowAll`, `lastFlushTime`, `ChickActiveData`, `LuckystarCoins`, `ActiveMoney`) VALUES (p_canEagleEyeCounts, p_canOpenCounts, p_isShowAll, p_lastFlushTime, p_ChickActiveData, p_LuckystarCoins, p_ActiveMoney);
    SELECT LAST_INSERT_ID() AS `IDENTITY`;
    SET p_ID = LAST_INSERT_ID();
    IF (0 <> 0) THEN
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
  ELSE
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
END$$

