  IF (v_count <> 0) THEN
    SELECT COUNT(`ActiveCode`) INTO v_count FROM `ChickActive_Number` WHERE `UserID` = p_UserID LIMIT 1;
    IF (v_count2 <> 0) THEN
      SET p_ReturnValue = 2;
