DROP PROCEDURE IF EXISTS `SP_Active_PullDown`$$
CREATE PROCEDURE `SP_Active_PullDown`(IN p_ActiveID INT, IN p_AwardID VARCHAR(200), IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_StartDate DATETIME(3) DEFAULT NULL;
  DECLARE v_EndDate DATETIME(3) DEFAULT NULL;
  DECLARE v_HasKey INT DEFAULT NULL;
  DECLARE v_PullDown TINYINT(1) DEFAULT NULL;
  DECLARE v_Mark INT DEFAULT NULL;
  DECLARE v_CanGet TINYINT(1) DEFAULT NULL;
  DECLARE v_temp INT DEFAULT NULL;
  DECLARE v_maxCount INT DEFAULT NULL;
  DECLARE v_NickName VARCHAR(50) DEFAULT NULL;
  DECLARE v_sex INT DEFAULT NULL;
  DECLARE v_Index INT DEFAULT NULL;
  DECLARE v_ItemCount INT DEFAULT NULL;
  DECLARE v_ItemID INT DEFAULT NULL;
  DECLARE v_TemplateID INT DEFAULT NULL;
  DECLARE v_Place INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_IsJudge TINYINT(1) DEFAULT NULL;
  DECLARE v_Color VARCHAR(100) DEFAULT NULL;
  DECLARE v_IsExist TINYINT(1) DEFAULT NULL;
  DECLARE v_StrengthenLevel INT DEFAULT NULL;
  DECLARE v_AttackCompose INT DEFAULT NULL;
  DECLARE v_DefendCompose INT DEFAULT NULL;
  DECLARE v_LuckCompose INT DEFAULT NULL;
  DECLARE v_AgilityCompose INT DEFAULT NULL;
  DECLARE v_IsBinds TINYINT(1) DEFAULT NULL;
  DECLARE v_BeginDate DATETIME(3) DEFAULT NULL;
  DECLARE v_ValidDate INT DEFAULT NULL;
  DECLARE v_BagType INT DEFAULT NULL;
  DECLARE v_SenderID INT DEFAULT NULL;
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(1000) DEFAULT NULL;
  DECLARE v_Content VARCHAR(4000) DEFAULT NULL;
  DECLARE v_SendTime DATETIME(3) DEFAULT NULL;
  DECLARE v_IsRead TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelR TINYINT(1) DEFAULT NULL;
  DECLARE v_IfDelS TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelete TINYINT(1) DEFAULT NULL;
  DECLARE v_Annex1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Gold INT DEFAULT NULL;
  DECLARE v_Money INT DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE v_Annex3 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex4 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex5 VARCHAR(100) DEFAULT NULL;
  DECLARE v_AnnexIndex INT DEFAULT NULL;
  DECLARE v_getCount INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `StartDate`, `EndDate`, `HasKey` INTO v_StartDate, v_EndDate, v_HasKey FROM `Project_Game34`.`Active` WHERE `ActiveID` = p_ActiveID LIMIT 1;
  IF TIMESTAMPDIFF(SECOND, DATE_FORMAT(v_StartDate, '%Y-%m-%d %H:%i:%s'), DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s')) < 0 THEN
    SET p_ReturnValue = 7;
    LEAVE proc;
  END IF;
  IF TIMESTAMPDIFF(SECOND, DATE_FORMAT(v_EndDate, '%Y-%m-%d %H:%i:%s'), DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s')) > 0 THEN
    SET p_ReturnValue = 8;
    LEAVE proc;
  END IF;
  SET v_Mark = 0;
  IF v_HasKey = 1 THEN
    SELECT IFNULL(`ActiveID`, 0), IFNULL(`PullDown`, 0), `Mark` INTO p_ActiveID, v_PullDown, v_Mark FROM `Active_Number` WHERE `ActiveID` = p_ActiveID AND `AwardID` = p_AwardID LIMIT 1;
    IF p_ActiveID = 0 OR v_PullDown IS NULL THEN
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
    IF v_PullDown = 1 THEN
      SET p_ReturnValue = 5;
      LEAVE proc;
    END IF;
    SELECT IFNULL(`IsOnly`, 0) INTO v_CanGet FROM `Project_Game34`.`Active` WHERE `IsOnly` = 1 AND `ActiveID` IN (SELECT `ActiveID` FROM `Active_Number` WHERE `UserID` = p_UserID AND `ActiveID` = p_ActiveID) LIMIT 1;
    IF v_CanGet = 1 THEN
      SET p_ReturnValue = 6;
      LEAVE proc;
    END IF;
  ELSEIF v_HasKey = 2 THEN
    SET p_AwardID = CONCAT(CAST(p_ActiveID AS CHAR(20)), '-2-', CAST(p_UserID AS CHAR(20)));
    SELECT IFNULL(`ActiveID`, 0), IFNULL(`PullDown`, 0), `Mark` INTO p_ActiveID, v_PullDown, v_Mark FROM `Active_Number` WHERE `ActiveID` = p_ActiveID AND `AwardID` = p_AwardID LIMIT 1;
    IF p_ActiveID = 0 OR v_PullDown IS NULL THEN
      SET p_ReturnValue = 10;
      LEAVE proc;
    END IF;
    IF v_PullDown = 1 THEN
      SET p_ReturnValue = 6;
      LEAVE proc;
    END IF;
  ELSEIF v_HasKey = 3 THEN
    SET p_AwardID = CONCAT(CAST(p_ActiveID AS CHAR(20)), '-3-', CAST(p_UserID AS CHAR(20)));
    SELECT IFNULL(`PullDown`, 0), IFNULL(`Mark`, 0) INTO v_PullDown, v_Mark FROM `Active_Number` WHERE `ActiveID` = p_ActiveID AND `AwardID` = p_AwardID LIMIT 1;
    IF v_PullDown <> 0 OR v_PullDown IS NOT NULL THEN
      SET p_ReturnValue = 6;
      LEAVE proc;
    END IF;
  ELSEIF v_HasKey = 4 THEN
    SELECT IFNULL(`ActiveID`, 0), IFNULL(`PullDown`, 0), `Mark` INTO p_ActiveID, v_PullDown, v_Mark FROM `Active_Number` WHERE `ActiveID` = p_ActiveID AND `AwardID` = p_AwardID LIMIT 1;
    IF p_ActiveID = 0 OR v_PullDown IS NULL THEN
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
    IF v_PullDown = 1 THEN
      SET p_ReturnValue = 5;
      LEAVE proc;
    END IF;
  ELSE
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SET v_NickName = '';
  SELECT `NickName`, (CASE `sex` WHEN 0 THEN 2 ELSE 1 END) INTO v_NickName, v_sex FROM `Sys_Users_Detail` WHERE `UserID` = p_UserID LIMIT 1;
  IF v_NickName = '' OR v_NickName IS NULL THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF 1 IS NOT NULL THEN
    DROP TEMPORARY TABLE IF EXISTS `tmp_Award`;
  END IF;
  CREATE TEMPORARY TABLE `tmp_Award` (`id` INT NULL AUTO_INCREMENT PRIMARY KEY, `TemplateID` INT NOT NULL, `Count` INT NOT NULL, `ValidDate` INT NOT NULL, `StrengthenLevel` INT NOT NULL, `AttackCompose` INT NOT NULL, `DefendCompose` INT NOT NULL, `LuckCompose` INT NOT NULL, `AgilityCompose` INT NOT NULL, `Gold` INT NOT NULL, `Money` INT NOT NULL);
  INSERT INTO `tmp_Award` (`TemplateID`, `Count`, `ValidDate`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `Gold`, `Money`) SELECT `ItemID`, `Count`, `ValidDate`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `Gold`, `Money` FROM `Project_Game34`.`Active_Award` WHERE `ActiveID` = p_ActiveID AND (`Sex` = v_sex OR `Sex` = 0) AND `Mark` = v_Mark;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 7;
    LEAVE proc;
  END IF;
  SET v_Index = 1;
  SELECT COUNT(*) INTO v_ItemCount FROM `tmp_Award` LIMIT 1;
  SET v_ItemID = 0;
  SET v_TemplateID = 0;
  SET v_Place = -1;
  SET v_Count = 1;
  SET v_IsJudge = 1;
  SET v_Color = '';
  SET v_IsExist = 1;
  SET v_StrengthenLevel = 0;
  SET v_AttackCompose = 0;
  SET v_DefendCompose = 0;
  SET v_LuckCompose = 0;
  SET v_AgilityCompose = 0;
  SET v_IsBinds = 1;
  SET v_BeginDate = NOW(3);
  SET v_ValidDate = 0;
  SET v_BagType = 0;
  SET v_SenderID = 0;
  SET v_Sender = `GetTranslation`('SP_Active_PullDown.Sender');
  SET v_ReceiverID = p_UserID;
  SET v_Receiver = v_NickName;
  SET v_Title = `GetTranslation`('SP_Active_PullDown.Title');
  SET v_Content = `GetTranslation`('SP_Active_PullDown.Content');
  SET v_SendTime = NOW(3);
  SET v_IsRead = 0;
  SET v_IsDelR = 0;
  SET v_IfDelS = 0;
  SET v_IsDelete = 0;
  SET v_Annex1 = '';
  SET v_Annex2 = '';
  SET v_Gold = 0;
  SET v_Money = 0;
  SET v_Annex3 = '';
  SET v_Annex4 = '';
  SET v_Annex5 = '';
  SET v_AnnexIndex = 0;
  START TRANSACTION;
  w1: WHILE v_Index <= v_ItemCount DO
    SELECT `TemplateID`, `Count`, `ValidDate`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, v_Gold + `Gold`, v_Money + `Money` INTO v_TemplateID, v_Count, v_ValidDate, v_StrengthenLevel, v_AttackCompose, v_DefendCompose, v_LuckCompose, v_AgilityCompose, v_Gold, v_Money FROM `tmp_Award` WHERE `id` = v_Index LIMIT 1;
    SET v_temp = 0;
    SELECT IFNULL(`TemplateID`, 0), IFNULL(`MaxCount`, 1) INTO v_temp, v_maxCount FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_TemplateID LIMIT 1;
    IF v_temp = 0 AND v_TemplateID <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 3;
      LEAVE proc;
    END IF;
    IF v_TemplateID <> 0 THEN
      w2: WHILE v_Count > 0 DO
        SET v_AnnexIndex = v_AnnexIndex + 1;
        IF v_Count > v_maxCount THEN
          SET v_getCount = v_maxCount;
        ELSE
          SET v_getCount = v_Count;
        END IF;
        SET v_Count = v_Count - v_getCount;
        INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `IsUsed`) VALUES (0, v_BagType, v_TemplateID, v_Place, v_getCount, v_IsJudge, v_Color, v_IsExist, v_StrengthenLevel, v_AttackCompose, v_DefendCompose, v_LuckCompose, v_AgilityCompose, v_IsBinds, v_BeginDate, v_ValidDate, 0);
        SELECT LAST_INSERT_ID() AS `identity`;
        SET v_ItemID = LAST_INSERT_ID();
        IF 0 <> 0 THEN
          ROLLBACK;
          SET p_ReturnValue = 0;
          LEAVE proc;
        END IF;
        IF v_AnnexIndex = 1 THEN
          SET v_Annex1 = CAST(v_ItemID AS CHAR(20));
        END IF;
        IF v_AnnexIndex = 2 THEN
          SET v_Annex2 = CAST(v_ItemID AS CHAR(20));
        END IF;
        IF v_AnnexIndex = 3 THEN
          SET v_Annex3 = CAST(v_ItemID AS CHAR(20));
        END IF;
        IF v_AnnexIndex = 4 THEN
          SET v_Annex4 = CAST(v_ItemID AS CHAR(20));
        END IF;
        IF v_AnnexIndex = 5 THEN
          SET v_Annex5 = CAST(v_ItemID AS CHAR(20));
          SET v_Remark = CONCAT('GiftToken:0,Money:0,Annex1:', v_Annex1, ',Annex2:', v_Annex2, ',Annex3:', v_Annex3, ',Annex4:', v_Annex4, ',Annex5:', v_Annex5);
          INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `GiftToken`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, 0, 0, v_IsExist, 52, v_Remark, v_Annex3, v_Annex4, v_Annex5);
          IF 0 <> 0 THEN
            ROLLBACK;
            SET p_ReturnValue = 0;
            LEAVE proc;
          END IF;
          SET v_AnnexIndex = 0;
          SET v_Annex1 = '';
          SET v_Annex2 = '';
          SET v_Annex3 = '';
          SET v_Annex4 = '';
          SET v_Annex5 = '';
        END IF;
      END WHILE w2;
    END IF;
    SET v_Index = v_Index + 1;
  END WHILE w1;
  IF v_AnnexIndex <> 0 OR v_Gold > 0 OR v_Money > 0 THEN
    IF v_AnnexIndex = 4 THEN
      SET v_Remark = CONCAT('GiftToken:0,Money:', CAST(v_Money AS CHAR(20)), ',Annex1:,Annex2:,Annex3:,Annex4:,Annex5:');
      INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `GiftToken`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, '', '', '', v_Money, v_IsExist, 52, v_Remark, '', '', '');
      IF 0 <> 0 THEN
        ROLLBACK;
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
      SET v_Money = 0;
    END IF;
    SET v_Remark = CONCAT('GiftToken:', CAST(v_Gold AS CHAR(20)), ',Money:', CAST(v_Money AS CHAR(20)), ',Annex1:', v_Annex1, ',Annex2:', v_Annex2, ',Annex3:', v_Annex3, ',Annex4:', v_Annex4, ',Annex5:', v_Annex5);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `GiftToken`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, v_Gold, v_Money, v_IsExist, 52, v_Remark, v_Annex3, v_Annex4, v_Annex5);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  IF v_HasKey <> 3 THEN
    UPDATE `Active_Number` SET `PullDown` = 1, `GetDate` = NOW(3), `UserID` = p_UserID WHERE `AwardID` = p_AwardID;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    INSERT INTO `Active_Number` (`AwardID`, `ActiveID`, `PullDown`, `GetDate`, `UserID`, `Mark`) VALUES (p_AwardID, p_ActiveID, 1, NOW(3), p_UserID, 0);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Active_System_Data_Update`$$
CREATE PROCEDURE `SP_Active_System_Data_Update`(IN p_ID INT, IN p_UserID INT, IN p_canOpenCounts INT, IN p_canEagleEyeCounts INT, IN p_lastFlushTime DATETIME(3), IN p_isShowAll TINYINT(1), IN p_ChickActiveData LONGTEXT, IN p_LuckystarCoins INT, IN p_ActiveMoney INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  UPDATE `Sys_Active_System_Data` SET `UserID` = p_UserID, `canOpenCounts` = p_canOpenCounts, `canEagleEyeCounts` = p_canEagleEyeCounts, `lastFlushTime` = p_lastFlushTime, `isShowAll` = p_isShowAll, `ChickActiveData` = p_ChickActiveData, `LuckystarCoins` = p_LuckystarCoins, `ActiveMoney` = p_ActiveMoney WHERE `ID` = p_ID;
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_Admin_ForbidUser`$$
CREATE PROCEDURE `SP_Admin_ForbidUser`(IN p_UserName VARCHAR(50), IN p_NickName VARCHAR(50), INOUT p_UserID INT, IN p_ForbidDate DATETIME(3), IN p_IsExist TINYINT(1), IN p_ForbidReason VARCHAR(1000), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  IF p_UserName <> '' THEN
    SELECT IFNULL(`UserID`, 0) INTO p_UserID FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  END IF;
  IF p_NickName <> '' THEN
    SELECT IFNULL(`UserID`, 0) INTO p_UserID FROM `Sys_Users_Detail` WHERE `NickName` = p_NickName LIMIT 1;
  END IF;
  IF p_UserID <> 0 THEN
    SELECT IFNULL(`UserID`, 0) INTO p_UserID FROM `Sys_Users_Detail` WHERE `UserID` = p_UserID LIMIT 1;
  END IF;
  UPDATE `Sys_Users_Detail` SET `IsExist` = p_IsExist, `ForbidDate` = p_ForbidDate, `ForbidReason` = p_ForbidReason WHERE `UserID` = p_UserID;
END$$

DROP PROCEDURE IF EXISTS `SP_Admin_Redeem`$$
CREATE PROCEDURE `SP_Admin_Redeem`(OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  START TRANSACTION;
  INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) SELECT `UserID`, 0, CASE WHEN `sex` = 1 THEN 7001 ELSE 7002 END, 11, 1, 1, '', 1, 0, 0, 0, 0, 0, 1, NOW(3), 0 FROM `Sys_Users_Detail` WHERE `IsFirst` = 0;
  IF 0 <> 0 THEN
    ROLLBACK;
    SELECT 0;
  END IF;
