    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  IF (p_Gold > 0 OR p_Money > 0 OR p_GiftToken > 0) THEN
    SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:,Annex2:,Annex3:,Annex4:,Annex5:,GiftToken:', CAST(p_GiftToken AS CHAR(20)));
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`, `GiftToken`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, '', '', p_Gold, p_Money, v_IsExist, 8, v_Remark, '', '', '', p_GiftToken);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
END$$

