CREATE PROCEDURE `SP_Admin_SendAllItem_UserName_MultiSupport`(IN p_Title VARCHAR(1000), IN p_Content VARCHAR(2000), IN p_UserName VARCHAR(1000), IN p_Gold INT, IN p_Money INT, IN p_GiftToken INT, IN p_Param VARCHAR(2000), OUT p_ReturnValue INT)
