  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET v_NickName = '';
  SET v_UserID = 0;
  SELECT `NickName`, `UserID` INTO v_NickName, v_UserID FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  IF v_NickName = '' THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SET v_BeginDate = NOW(3);
  SET v_Place = -1;
  SET v_IsJudge = 1;
  SET v_Color = '';
  SET v_IsExist = 1;
  SET v_BagType = -1;
  SET v_SenderID = 0;
  SET v_Sender = 'Hệ thống';
