  SET p_Param = LTRIM(RTRIM(p_Param));
  SET v_startItem = 1;
  START TRANSACTION;
  IF CHAR_LENGTH(RTRIM(p_Param)) > 0 THEN
    SET p_Param = CONCAT(p_Param, ';');
    SET v_locationItem = LOCATE(';', p_Param);
    w1: WHILE v_locationItem <> 0 DO
      SET v_values = SUBSTRING(p_Param, v_startItem, v_locationItem - v_startItem);
      SET v_startItem = v_locationItem + 1;
      SET v_indexValue = 0;
      SET v_values = LTRIM(RTRIM(v_values));
      SET v_values = CONCAT(v_values, ',');
      SET v_locationValue = LOCATE(',', v_values);
      SET v_ItemID = 0;
      SET v_TemplateID = 0;
      SET v_Count = 0;
      SET v_StrengthenLevel = 0;
      SET v_AttackCompose = 0;
      SET v_DefendCompose = 0;
      SET v_LuckCompose = 0;
      SET v_AgilityCompose = 0;
      SET v_IsBinds = 1;
      SET v_ValidDate = 1;
      SET v_startValue = 1;
      w2: WHILE v_locationValue <> 0 DO
        SET v_indexValue = v_indexValue + 1;
        SET v_value = SUBSTRING(v_values, v_startValue, v_locationValue - v_startValue);
        SET v_startValue = v_locationValue + 1;
        IF v_indexValue = 1 THEN
          SET v_TemplateID = v_value;
        ELSEIF v_indexValue = 2 THEN
          SET v_Count = v_value;
        ELSEIF v_indexValue = 3 THEN
          SET v_ValidDate = v_value;
        ELSEIF v_indexValue = 4 THEN
          SET v_StrengthenLevel = v_value;
        ELSEIF v_indexValue = 5 THEN
          SET v_AttackCompose = v_value;
        ELSEIF v_indexValue = 6 THEN
          SET v_DefendCompose = v_value;
        ELSEIF v_indexValue = 7 THEN
          SET v_AgilityCompose = v_value;
        ELSEIF v_indexValue = 8 THEN
          SET v_LuckCompose = v_value;
        ELSEIF v_indexValue = 9 THEN
          SET v_IsBinds = v_value;
        END IF;
        SET v_locationValue = LOCATE(',', v_values, v_startValue);
      END WHILE w2;
      SET v_temp = 0;
      SELECT IFNULL(`TemplateID`, 0), IFNULL(`MaxCount`, 1) INTO v_temp, v_maxCount FROM `Shop_Goods` WHERE `TemplateID` = v_TemplateID LIMIT 1;
      IF v_temp = 0 THEN
        SET v_TemplateID = 0;
      END IF;
      IF v_TemplateID <> 0 THEN
        w3: WHILE v_Count > 0 DO
          IF v_Count > v_maxCount THEN
            SET v_getCount = v_maxCount;
          ELSE
            SET v_getCount = v_Count;
          END IF;
          SET v_Count = v_Count - v_getCount;
          SET v_AnnexIndex = v_AnnexIndex + 1;
          SET v_Hole1 = -1;
          SET v_Hole2 = -1;
          SET v_Hole3 = -1;
          SET v_Hole4 = -1;
          SET v_Hole5 = -1;
          SET v_Hole6 = -1;
          SELECT IFNULL(`CategoryID`, 0) INTO v_Categ FROM `Shop_Goods` WHERE `TemplateID` = v_TemplateID LIMIT 1;
          IF v_Categ = 1 OR v_Categ = 5 OR v_Categ = 7 THEN
            SET v_Hole1 = 0;
            SET v_Hole2 = 0;
            SET v_Hole3 = 0;
            SET v_Hole4 = 0;
            SET v_Hole5 = 0;
            SET v_Hole6 = 0;
          END IF;
          INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `Hole1`, `Hole2`, `Hole3`, `Hole4`, `Hole5`, `Hole6`) VALUES (0, v_BagType, v_TemplateID, v_Place, v_getCount, v_IsJudge, v_Color, v_IsExist, v_StrengthenLevel, v_AttackCompose, v_DefendCompose, v_LuckCompose, v_AgilityCompose, v_IsBinds, v_BeginDate, v_ValidDate, v_Hole1, v_Hole2, v_Hole3, v_Hole4, v_Hole5, v_Hole6);
          SELECT LAST_INSERT_ID() AS `identity`;
          SET v_ItemID = LAST_INSERT_ID();
          IF 0 <> 0 THEN
            ROLLBACK;
            SET p_ReturnValue = 0;
            LEAVE proc;
          END IF;
          IF v_AnnexIndex = 1 THEN
            SET v_Annex1 = CAST(v_ItemID AS CHAR(20));
          END IF;
          IF v_AnnexIndex = 2 THEN
            SET v_Annex2 = CAST(v_ItemID AS CHAR(20));
          END IF;
          IF v_AnnexIndex = 3 THEN
            SET v_Annex3 = CAST(v_ItemID AS CHAR(20));
          END IF;
          IF v_AnnexIndex = 4 THEN
            SET v_Annex4 = CAST(v_ItemID AS CHAR(20));
          END IF;
          IF v_AnnexIndex = 5 THEN
            SET v_Annex5 = CAST(v_ItemID AS CHAR(20));
            SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', v_Annex1, ',Annex2:', v_Annex2, ',Annex3:', v_Annex3, ',Annex4:', v_Annex4, ',Annex5:', v_Annex5, ',GiftToken:0');
            INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`, `GiftToken`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, 0, 0, v_IsExist, 51, v_Remark, v_Annex3, v_Annex4, v_Annex5, 0);
            IF 0 <> 0 THEN
              ROLLBACK;
              SET p_ReturnValue = 0;
              LEAVE proc;
            END IF;
            SET v_AnnexIndex = 0;
            SET v_Annex1 = '';
            SET v_Annex2 = '';
            SET v_Annex3 = '';
            SET v_Annex4 = '';
            SET v_Annex5 = '';
          END IF;
        END WHILE w3;
      END IF;
      SET v_locationItem = LOCATE(';', p_Param, v_startItem);
    END WHILE w1;
  END IF;
  IF (v_AnnexIndex <> 0) AND (CHAR_LENGTH(RTRIM(p_Param)) <> 0) THEN
    SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', v_Annex1, ',Annex2:', v_Annex2, ',Annex3:', v_Annex3, ',Annex4:', v_Annex4, ',Annex5:', v_Annex5, ',GiftToken:0');
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`, `GiftToken`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, 0, 0, v_IsExist, 51, v_Remark, v_Annex3, v_Annex4, v_Annex5, 0);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  IF (p_Gold > 0 OR p_Money > 0 OR p_GiftToken > 0) THEN
    SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:,Annex2:,Annex3:,Annex4:,Annex5:,GiftToken:', CAST(p_GiftToken AS CHAR(20)));
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`, `GiftToken`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, '', '', p_Gold, p_Money, v_IsExist, 51, v_Remark, '', '', '', p_GiftToken);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
  IF v_AnnexIndex <> 0 OR p_Gold > 0 OR p_Money > 0 OR p_GiftToken > 0 THEN
    IF v_AnnexIndex = 4 AND p_Gold > 0 AND p_Money > 0 AND p_GiftToken > 0 THEN
      LEAVE proc;
      SET v_Remark = CONCAT('Gold:0,Money:', CAST(p_Money AS CHAR(20)), ',Annex1:,Annex2:,Annex3:,Annex4:,Annex5:');
      INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, '', '', 0, p_Money, v_IsExist, 51, v_Remark, '', '', '');
      IF 0 <> 0 THEN
        ROLLBACK;
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
      SET p_Money = 0;
      SET p_GiftToken = 0;
    END IF;
    SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:', v_Annex1, ',Annex2:', v_Annex2, ',Annex3:', v_Annex3, ',Annex4:', v_Annex4, ',Annex5:', v_Annex5, ',GiftToken', p_GiftToken);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`, `GiftToken`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, p_Gold, p_Money, v_IsExist, 51, v_Remark, v_Annex3, v_Annex4, v_Annex5, p_GiftToken);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSEIF CHAR_LENGTH(RTRIM(p_Param)) = 0 THEN
    SET v_Remark = 'Gold:0,Money:0,Annex1:,Annex2:,Annex3:,Annex4:,Annex5:,GiftToken:0';
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_SenderID, v_Sender, v_ReceiverID, v_NickName, p_Title, p_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, 0, 0, v_IsExist, 51, v_Remark, v_Annex3, v_Annex4, v_Annex5);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

