DROP PROCEDURE IF EXISTS `SP_Admin_SendUserItem`$$
CREATE PROCEDURE `SP_Admin_SendUserItem`(IN p_ItemID INT, IN p_UserID INT, IN p_TemplateID INT, IN p_Place INT, IN p_Count INT, IN p_IsJudge TINYINT(1), IN p_Color VARCHAR(100), IN p_IsExist TINYINT(1), IN p_StrengthenLevel INT, IN p_AttackCompose INT, IN p_DefendCompose INT, IN p_LuckCompose INT, IN p_AgilityCompose INT, IN p_IsBinds TINYINT(1), IN p_BeginDate DATETIME(3), IN p_ValidDate INT, IN p_BagType INT, INOUT p_ID INT, IN p_SenderID INT, IN p_Sender VARCHAR(100), IN p_ReceiverID INT, IN p_Receiver VARCHAR(100), IN p_Title VARCHAR(1000), IN p_Content VARCHAR(4000), IN p_SendTime DATETIME(3), IN p_IsRead TINYINT(1), IN p_IsDelR TINYINT(1), IN p_IfDelS TINYINT(1), IN p_IsDelete TINYINT(1), IN p_Annex1 VARCHAR(100), IN p_Annex2 VARCHAR(100), IN p_Gold INT, IN p_Money INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_temp INT DEFAULT NULL;
  DECLARE v_maxCount INT DEFAULT NULL;
  DECLARE v_NickName VARCHAR(50) DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE v_getCount INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET v_NickName = '';
  SELECT `NickName` INTO v_NickName FROM `Sys_Users_Detail` WHERE `UserID` = p_ReceiverID LIMIT 1;
  IF v_NickName = '' THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SET v_temp = 0;
  SELECT IFNULL(`TemplateID`, 0), IFNULL(`MaxCount`, 1) INTO v_temp, v_maxCount FROM `Shop_Goods` WHERE `TemplateID` = p_TemplateID LIMIT 1;
  IF v_temp = 0 THEN
    SET p_TemplateID = 0;
  END IF;
  START TRANSACTION;
  IF p_TemplateID <> 0 THEN
    w1: WHILE p_Count > 0 DO
      IF p_Count > v_maxCount THEN
        SET v_getCount = v_maxCount;
      ELSE
        SET v_getCount = p_Count;
      END IF;
      SET p_Count = p_Count - v_getCount;
      INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) VALUES (0, p_BagType, p_TemplateID, -1, v_getCount, p_IsJudge, p_Color, p_IsExist, p_StrengthenLevel, p_AttackCompose, p_DefendCompose, p_LuckCompose, p_AgilityCompose, p_IsBinds, p_BeginDate, p_ValidDate);
      SELECT LAST_INSERT_ID() AS `identity`;
      SET p_ItemID = LAST_INSERT_ID();
      IF 0 <> 0 THEN
        ROLLBACK;
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
      SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', CAST(p_ItemID AS CHAR(20)), ',Annex2:', p_Annex2);
      INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (p_SenderID, p_Sender, p_ReceiverID, v_NickName, p_Title, p_Content, p_SendTime, p_IsRead, p_IsDelR, p_IfDelS, p_IsDelete, p_ItemID, p_Annex2, 0, 0, p_IsExist, 51, v_Remark);
      IF 0 <> 0 THEN
        ROLLBACK;
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
    END WHILE w1;
  END IF;
  IF p_Gold <> 0 OR p_Money <> 0 THEN
    SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:', p_Annex1, ',Annex2:', p_Annex2);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (p_SenderID, p_Sender, p_ReceiverID, v_NickName, p_Title, p_Content, p_SendTime, p_IsRead, p_IsDelR, p_IfDelS, p_IsDelete, p_Annex1, p_Annex2, p_Gold, p_Money, p_IsExist, 51, v_Remark);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  IF p_TemplateID = 0 AND p_Gold = 0 AND p_Money = 0 THEN
    SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:', p_Annex1, ',Annex2:', p_Annex2);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (p_SenderID, p_Sender, p_ReceiverID, v_NickName, p_Title, p_Content, p_SendTime, p_IsRead, p_IsDelR, p_IfDelS, p_IsDelete, p_Annex1, p_Annex2, p_Gold, p_Money, p_IsExist, 51, v_Remark);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Admin_SendUserMoney`$$
CREATE PROCEDURE `SP_Admin_SendUserMoney`(INOUT p_ID INT, IN p_SenderID INT, IN p_Sender VARCHAR(100), IN p_ReceiverID INT, IN p_Receiver VARCHAR(100), IN p_Title VARCHAR(1000), IN p_Content VARCHAR(4000), IN p_SendTime DATETIME(3), IN p_IsRead TINYINT(1), IN p_IsDelR TINYINT(1), IN p_IfDelS TINYINT(1), IN p_IsDelete TINYINT(1), IN p_Annex1 VARCHAR(100), IN p_Annex2 VARCHAR(100), IN p_Gold INT, IN p_Money INT, IN p_IsExist TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_NickName VARCHAR(50) DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET v_NickName = '';
  SELECT `NickName` INTO v_NickName FROM `Sys_Users_Detail` WHERE `UserID` = p_ReceiverID LIMIT 1;
  IF v_NickName = '' THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:', p_Annex1, 'Annex2:', p_Annex2);
  INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (p_SenderID, p_Sender, p_ReceiverID, v_NickName, p_Title, p_Content, p_SendTime, p_IsRead, p_IsDelR, p_IfDelS, p_IsDelete, p_Annex1, p_Annex2, p_Gold, p_Money, p_IsExist, 51, v_Remark);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

