DROP PROCEDURE IF EXISTS `SP_Auction_Add`$$
CREATE PROCEDURE `SP_Auction_Add`(INOUT p_AuctionID INT, IN p_AuctioneerID INT, IN p_AuctioneerName VARCHAR(100), IN p_BeginDate DATETIME(3), IN p_BuyerID INT, IN p_BuyerName VARCHAR(100), IN p_IsExist TINYINT(1), IN p_ItemID INT, IN p_Mouthful INT, IN p_PayType INT, IN p_Price INT, IN p_Rise INT, IN p_ValidDate INT, IN p_TemplateID INT, IN p_Name VARCHAR(200), IN p_Category INT, IN p_Random INT, IN p_goodsCount INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SET p_ValidDate = 1 + p_ValidDate;
  INSERT INTO `Auction` (`AuctioneerID`, `Name`, `Category`, `AuctioneerName`, `BeginDate`, `BuyerID`, `BuyerName`, `IsExist`, `ItemID`, `Mouthful`, `PayType`, `Price`, `Rise`, `ValidDate`, `TemplateID`, `Random`, `goodsCount`) VALUES (p_AuctioneerID, p_Name, p_Category, p_AuctioneerName, p_BeginDate, p_BuyerID, p_BuyerName, p_IsExist, p_ItemID, p_Mouthful, p_PayType, p_Price, p_Rise, p_ValidDate, p_TemplateID, 0, p_goodsCount);
  SELECT LAST_INSERT_ID() AS `identity`;
  SET p_AuctionID = LAST_INSERT_ID();
END$$

DROP PROCEDURE IF EXISTS `SP_Auction_Delete`$$
CREATE PROCEDURE `SP_Auction_Delete`(IN p_AuctionID INT, IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_AuctioneerID INT DEFAULT NULL;
  DECLARE v_AuctioneerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_BuyerID INT DEFAULT NULL;
  DECLARE v_BuyerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_ItemID INT DEFAULT NULL;
  DECLARE v_PayType INT DEFAULT NULL;
  DECLARE v_Price INT DEFAULT NULL;
  DECLARE v_SenderID INT DEFAULT NULL;
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(1000) DEFAULT NULL;
  DECLARE v_Content VARCHAR(4000) DEFAULT NULL;
  DECLARE v_SendTime DATETIME(3) DEFAULT NULL;
  DECLARE v_IsRead TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelR TINYINT(1) DEFAULT NULL;
  DECLARE v_IfDelS TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelete TINYINT(1) DEFAULT NULL;
  DECLARE v_Annex1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Gold INT DEFAULT NULL;
  DECLARE v_Money INT DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET v_SenderID = 0;
  SET v_Sender = `GetTranslation`('SP_Auction_Delete.Sender');
  SET v_ReceiverID = 0;
  SET v_Receiver = '';
  SET v_Title = `GetTranslation`('SP_Auction_Delete.Title');
  SET v_Content = `GetTranslation`('SP_Auction_Delete.Content');
  SET v_SendTime = NOW(3);
  SET v_IsRead = 0;
  SET v_IsDelR = 0;
  SET v_IfDelS = 0;
  SET v_IsDelete = 0;
  SET v_Annex1 = '';
  SET v_Annex2 = '';
  SET v_Gold = 0;
  SET v_Money = 0;
  SELECT `AuctionID`, `AuctioneerID`, `AuctioneerName`, `BuyerID`, `BuyerName`, `ItemID`, `Price`, `PayType` INTO p_AuctionID, v_AuctioneerID, v_AuctioneerName, v_BuyerID, v_BuyerName, v_ItemID, v_Price, v_PayType FROM `Auction` WHERE `AuctionID` = p_AuctionID AND `IsExist` = 1 AND `AuctioneerID` = p_UserID LIMIT 1;
  IF v_AuctioneerID IS NULL THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  IF v_BuyerID <> 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Auction` SET `IsExist` = 0 WHERE `AuctionID` = p_AuctionID;
  IF 0 <> 0 OR ROW_COUNT() = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', CAST(v_ItemID AS CHAR(20)), ',Annex2:', v_Annex2);
  INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (v_SenderID, v_Sender, v_AuctioneerID, v_AuctioneerName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_ItemID, v_Annex2, 0, 0, 1, 3, v_Remark);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Auction_Scan`$$
CREATE PROCEDURE `SP_Auction_Scan`(INOUT p_NoticeUserID VARCHAR(4000), IN p_Cess DOUBLE, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_AuctionID INT DEFAULT NULL;
  DECLARE v_AuctioneerID INT DEFAULT NULL;
  DECLARE v_AuctioneerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_BuyerID INT DEFAULT NULL;
  DECLARE v_BuyerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_ItemID INT DEFAULT NULL;
  DECLARE v_PayType INT DEFAULT NULL;
  DECLARE v_Price INT DEFAULT NULL;
  DECLARE v_Name VARCHAR(200) DEFAULT NULL;
  DECLARE v_SenderID INT DEFAULT NULL;
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(1000) DEFAULT NULL;
  DECLARE v_Content VARCHAR(4000) DEFAULT NULL;
  DECLARE v_SendTime DATETIME(3) DEFAULT NULL;
  DECLARE v_IsRead TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelR TINYINT(1) DEFAULT NULL;
  DECLARE v_IfDelS TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelete TINYINT(1) DEFAULT NULL;
  DECLARE v_Annex1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Gold INT DEFAULT NULL;
  DECLARE v_Money INT DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE v_Type INT DEFAULT NULL;
  DECLARE v_flat DECIMAL(18,2) DEFAULT NULL;
  DECLARE v_NewPrice INT DEFAULT NULL;
  DECLARE v_Index INT DEFAULT NULL;
  DECLARE v_ItemCount INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET p_NoticeUserID = '';
  SET v_SenderID = 0;
  SET v_Sender = `GetTranslation`('SP_Auction_Scan.Sender');
  SET v_ReceiverID = 0;
  SET v_Receiver = '';
  SET v_Title = `GetTranslation`('SP_Auction_Scan.Title');
  SET v_Content = `GetTranslation`('SP_Auction_Scan.Content');
  SET v_SendTime = NOW(3);
  SET v_IsRead = 0;
  SET v_IsDelR = 0;
  SET v_IfDelS = 0;
  SET v_IsDelete = 0;
  SET v_Annex1 = '';
  SET v_Annex2 = '';
  SET v_Gold = 0;
  SET v_Money = 0;
  SET v_flat = 0.00;
  IF 1 IS NOT NULL THEN
    DROP TEMPORARY TABLE IF EXISTS `tmp_Auction`;
  END IF;
  CREATE TEMPORARY TABLE `tmp_Auction` (`id` INT NULL AUTO_INCREMENT PRIMARY KEY, `AuctionID` INT NOT NULL, `AuctioneerID` INT NOT NULL, `AuctioneerName` VARCHAR(200) NOT NULL, `BuyerID` INT NOT NULL, `BuyerName` VARCHAR(200) NOT NULL, `ItemID` INT NOT NULL, `Price` INT NOT NULL, `PayType` INT NOT NULL, `Name` VARCHAR(200) NULL);
  INSERT INTO `tmp_Auction` (`AuctionID`, `AuctioneerID`, `AuctioneerName`, `BuyerID`, `BuyerName`, `ItemID`, `Price`, `PayType`, `Name`) SELECT `AuctionID`, `AuctioneerID`, `AuctioneerName`, `BuyerID`, `BuyerName`, `ItemID`, `Price`, `PayType`, `Name` FROM `Auction` WHERE `IsExist` = 1 AND TIMESTAMPDIFF(HOUR, DATE_FORMAT(`BeginDate`, '%Y-%m-%d %H:00:00'), DATE_FORMAT(NOW(3), '%Y-%m-%d %H:00:00')) > `ValidDate`;
  SET v_Index = 1;
  SELECT COUNT(*) INTO v_ItemCount FROM `tmp_Auction` LIMIT 1;
  w1: WHILE v_Index <= v_ItemCount DO
    SELECT `AuctionID`, `AuctioneerID`, `AuctioneerName`, `BuyerID`, `BuyerName`, `ItemID`, `Price`, `PayType`, `Name` INTO v_AuctionID, v_AuctioneerID, v_AuctioneerName, v_BuyerID, v_BuyerName, v_ItemID, v_Price, v_PayType, v_Name FROM `tmp_Auction` WHERE `id` = v_Index LIMIT 1;
    SET v_Index = v_Index + 1;
    START TRANSACTION;
    UPDATE `Auction` SET `IsExist` = 0 WHERE `AuctionID` = v_AuctionID;
    IF 0 <> 0 OR ROW_COUNT() = 0 THEN
      ROLLBACK;
      ITERATE w1;
    END IF;
    IF v_BuyerID = 0 THEN
      SET v_BuyerID = v_AuctioneerID;
      SET v_BuyerName = v_AuctioneerName;
      SET v_Title = CONCAT(`GetTranslation`('SP_Auction_Scan.Msg1'), v_Name, '!!');
      SET v_Content = `GetTranslation`('SP_Auction_Scan.Msg2');
      SET v_Content = REPLACE(v_Content, '{0}', v_Name);
      SET v_Type = 3;
    ELSE
      SET v_Title = CONCAT(`GetTranslation`('SP_Auction_Scan.Msg3'), v_Name, '!!');
      SET v_Content = `GetTranslation`('SP_Auction_Scan.Msg4');
      SET v_Content = REPLACE(v_Content, '{0}', v_AuctioneerName);
      SET v_Content = REPLACE(v_Content, '{1}', v_Name);
      SET v_Content = REPLACE(v_Content, '{2}', CAST(v_Price AS CHAR(20)));
      SET v_Type = 4;
    END IF;
    SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', CAST(v_ItemID AS CHAR(20)), ',Annex2:', v_Annex2);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (v_SenderID, v_Sender, v_BuyerID, v_BuyerName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_ItemID, v_Annex2, 0, 0, 1, v_Type, v_Remark);
    IF 0 <> 0 THEN
      ROLLBACK;
      ITERATE w1;
    END IF;
    SET p_NoticeUserID = CONCAT(p_NoticeUserID, CAST(v_BuyerID AS CHAR(50)), ',');
    IF v_AuctioneerID <> v_BuyerID THEN
      IF v_PayType = 0 THEN
        SET v_Money = 0;
        SET v_Gold = v_Price;
      ELSE
        SET v_Money = v_Price;
        SET v_Gold = 0;
      END IF;
      SET v_NewPrice = v_Money - ROUND(v_flat * v_Money, 0);
      SET v_Title = CONCAT(`GetTranslation`('SP_Auction_Scan.Msg5'), v_Name, '!!');
      IF v_flat > 0 THEN
        SET v_Content = `GetTranslation`('SP_Auction_Scan.Msg6');
        SET v_Content = REPLACE(v_Content, '{3}', CAST(v_Money - v_NewPrice AS CHAR(20)));
      ELSE
        SET v_Content = `GetTranslation`('SP_Auction_Scan.Msg7');
      END IF;
      SET v_Content = REPLACE(v_Content, '{0}', v_Name);
      SET v_Content = REPLACE(v_Content, '{1}', v_BuyerName);
      SET v_Content = REPLACE(v_Content, '{2}', CAST(v_Money AS CHAR(20)));
      SET v_Content = REPLACE(v_Content, '{4}', CAST(v_NewPrice AS CHAR(20)));
      SET v_Remark = CONCAT('Gold:', CAST(v_Gold AS CHAR(20)), ',Money:', CAST(v_NewPrice AS CHAR(20)), ',Annex1:', v_Annex1, ',Annex2:', v_Annex2);
      SET v_Type = 2;
      INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (v_SenderID, v_Sender, v_AuctioneerID, v_AuctioneerName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, v_Gold, v_NewPrice, 1, v_Type, v_Remark);
      IF 0 <> 0 THEN
        ROLLBACK;
        ITERATE w1;
      END IF;
      SET p_NoticeUserID = CONCAT(p_NoticeUserID, CAST(v_AuctioneerID AS CHAR(50)), ',');
    END IF;
    COMMIT;
  END WHILE w1;
  IF CHAR_LENGTH(RTRIM(p_NoticeUserID)) > 0 THEN
    SET p_NoticeUserID = SUBSTRING(p_NoticeUserID, 1, CHAR_LENGTH(RTRIM(p_NoticeUserID)) - 1);
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Auction_Single`$$
CREATE PROCEDURE `SP_Auction_Single`(IN p_AuctionID INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT * FROM `Auction` WHERE `AuctionID` = p_AuctionID AND `IsExist` = 1;
END$$

DROP PROCEDURE IF EXISTS `SP_Auction_Update`$$
CREATE PROCEDURE `SP_Auction_Update`(IN p_AuctionID INT, IN p_AuctioneerID INT, IN p_AuctioneerName VARCHAR(100), IN p_BeginDate DATETIME(3), IN p_BuyerID INT, IN p_BuyerName VARCHAR(100), IN p_IsExist TINYINT(1), IN p_ItemID INT, IN p_Mouthful INT, IN p_PayType INT, IN p_Price INT, IN p_Rise INT, IN p_ValidDate INT, IN p_Name VARCHAR(200), IN p_Category INT, IN p_Cess DOUBLE, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_OldBuyerID INT DEFAULT NULL;
  DECLARE v_OldBuyerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_OldPrice INT DEFAULT NULL;
  DECLARE v_flat DECIMAL(18,2) DEFAULT NULL;
  DECLARE v_NewPrice INT DEFAULT NULL;
  DECLARE v_SenderID INT DEFAULT NULL;
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(1000) DEFAULT NULL;
  DECLARE v_Content VARCHAR(4000) DEFAULT NULL;
  DECLARE v_SendTime DATETIME(3) DEFAULT NULL;
  DECLARE v_IsRead TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelR TINYINT(1) DEFAULT NULL;
  DECLARE v_IfDelS TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelete TINYINT(1) DEFAULT NULL;
  DECLARE v_Annex1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Gold INT DEFAULT NULL;
  DECLARE v_Money INT DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET v_flat = 0.00;
  SELECT IFNULL(`Value`, CAST(0.10 AS CHAR)) INTO v_flat FROM `Server_Config` WHERE `Name` = 'Cess' LIMIT 1;
  SET v_SenderID = 0;
  SET v_Sender = `GetTranslation`('SP_Auction_Update.Sender');
  SET v_ReceiverID = v_OldBuyerID;
  SET v_Receiver = v_OldBuyerName;
  SET v_Title = `GetTranslation`('SP_Auction_Update.Title');
  SET v_Content = `GetTranslation`('SP_Auction_Update.Content');
  SET v_SendTime = NOW(3);
  SET v_IsRead = 0;
  SET v_IsDelR = 0;
  SET v_IfDelS = 0;
  SET v_IsDelete = 0;
  SET v_Annex1 = '';
  SET v_Annex2 = '';
  SET v_Gold = 0;
  SET v_Money = 0;
  SELECT `BuyerID`, `BuyerName`, `Price` INTO v_OldBuyerID, v_OldBuyerName, v_OldPrice FROM `Auction` WHERE `AuctionID` = p_AuctionID AND `IsExist` = 1 AND (DATE_ADD(`BeginDate`, INTERVAL `Random` MINUTE) < NOW(3)) LIMIT 1;
  IF v_OldBuyerID IS NULL THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  IF p_PayType = 0 THEN
    SET v_Gold = v_OldPrice;
  ELSE
    SET v_Money = v_OldPrice;
  END IF;
  START TRANSACTION;
  UPDATE `Auction` SET `BuyerID` = p_BuyerID, `BuyerName` = p_BuyerName, `IsExist` = p_IsExist, `Price` = p_Price WHERE `AuctionID` = p_AuctionID AND `IsExist` = 1;
  IF 0 <> 0 OR ROW_COUNT() = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF v_OldBuyerID <> 0 THEN
    SET v_Title = CONCAT(`GetTranslation`('SP_Auction_Update.Msg1'), p_Name, '!');
    SET v_Content = `GetTranslation`('SP_Auction_Update.Msg2');
    SET v_Content = REPLACE(v_Content, '{0}', p_Name);
    SET v_Content = REPLACE(v_Content, '{1}', p_BuyerName);
    SET v_Content = REPLACE(v_Content, '{2}', CAST(v_Money AS CHAR(20)));
    SET v_Remark = CONCAT('Gold:', CAST(v_Gold AS CHAR(20)), ',Money:', CAST(v_Money AS CHAR(20)), ',Annex1:', v_Annex1, ',Annex2:', v_Annex2);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (v_SenderID, v_Sender, v_OldBuyerID, v_OldBuyerName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, v_Gold, v_Money, 1, 5, v_Remark);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 3;
      LEAVE proc;
    END IF;
  END IF;
  IF p_Price >= p_Mouthful AND p_Mouthful <> 0 THEN
    SET v_Title = CONCAT(`GetTranslation`('SP_Auction_Update.Msg3'), p_Name, '!');
    SET v_Content = `GetTranslation`('SP_Auction_Update.Msg4');
    SET v_Content = REPLACE(v_Content, '{0}', p_AuctioneerName);
    SET v_Content = REPLACE(v_Content, '{1}', p_Name);
    SET v_Content = REPLACE(v_Content, '{2}', CAST(p_Price AS CHAR(20)));
    SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', CAST(p_ItemID AS CHAR(20)), ',Annex2:', v_Annex2);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (v_SenderID, v_Sender, p_BuyerID, p_BuyerName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, p_ItemID, v_Annex2, 0, 0, 1, 4, v_Remark);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
    IF p_PayType = 0 THEN
      SET v_Money = 0;
      SET v_Gold = p_Price;
    ELSE
      SET v_Money = p_Price;
      SET v_Gold = 0;
    END IF;
    SET v_NewPrice = p_Price - ROUND(v_flat * p_Price, 0);
    SET v_Title = CONCAT(`GetTranslation`('SP_Auction_Update.Msg5'), p_Name, '!');
    IF v_flat > 0 THEN
      SET v_Content = `GetTranslation`('SP_Auction_Update.Msg6');
      SET v_Content = REPLACE(v_Content, '{3}', CAST(p_Price - v_NewPrice AS CHAR(20)));
    ELSE
      SET v_Content = `GetTranslation`('SP_Auction_Update.Msg7');
    END IF;
    SET v_Content = REPLACE(v_Content, '{0}', p_Name);
    SET v_Content = REPLACE(v_Content, '{1}', p_BuyerName);
    SET v_Content = REPLACE(v_Content, '{2}', CAST(p_Price AS CHAR(20)));
    SET v_Content = REPLACE(v_Content, '{4}', CAST(v_NewPrice * 0.9 AS CHAR(20)));
    SET v_Remark = CONCAT('Gold:', CAST(v_Gold AS CHAR(20)), ',Money:', CAST(v_NewPrice * 0.9 AS CHAR(20)), ',Annex1:', v_Annex1, ',Annex2:', v_Annex2);
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`) VALUES (v_SenderID, v_Sender, p_AuctioneerID, p_AuctioneerName, v_Title, v_Content, v_SendTime, v_IsRead, v_IsDelR, v_IfDelS, v_IsDelete, v_Annex1, v_Annex2, v_Gold, v_NewPrice * 0.9, 1, 2, v_Remark);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 5;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_AvatarCollect_Add`$$
CREATE PROCEDURE `SP_AvatarCollect_Add`(INOUT p_ID INT, IN p_UserID INT, IN p_AvatarID INT, IN p_Sex INT, IN p_IsActive TINYINT(1), IN p_Data VARCHAR(500), IN p_TimeStart DATETIME(3), IN p_TimeEnd DATETIME(3), IN p_IsExit TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  DELETE FROM `Sys_Users_AvatarCollection` WHERE `UserID` = p_UserID AND `AvatarID` = p_AvatarID;
  INSERT INTO `Sys_Users_AvatarCollection` (`UserID`, `AvatarID`, `Sex`, `IsActive`, `Data`, `TimeStart`, `TimeEnd`, `IsExit`) VALUES (p_UserID, p_AvatarID, p_Sex, p_IsActive, p_Data, p_TimeStart, p_TimeEnd, p_IsExit);
  SELECT LAST_INSERT_ID() AS `identity`;
  SET p_ID = LAST_INSERT_ID();
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_AvatarCollect_Update`$$
CREATE PROCEDURE `SP_AvatarCollect_Update`(IN p_ID INT, IN p_UserID INT, IN p_AvatarID INT, IN p_Sex INT, IN p_IsActive TINYINT(1), IN p_Data VARCHAR(500), IN p_TimeStart DATETIME(3), IN p_TimeEnd DATETIME(3), IN p_IsExit TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  UPDATE `Sys_Users_AvatarCollection` SET `UserID` = p_UserID, `AvatarID` = p_AvatarID, `Sex` = p_Sex, `IsActive` = p_IsActive, `Data` = p_Data, `TimeStart` = p_TimeStart, `TimeEnd` = p_TimeEnd, `IsExit` = p_IsExit WHERE `ID` = p_ID;
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_Charge_Money_Add`$$
CREATE PROCEDURE `SP_Charge_Money_Add`(IN p_ChargeID VARCHAR(50), IN p_UserName VARCHAR(200), IN p_Money INT, IN p_Date VARCHAR(50), IN p_PayWay VARCHAR(200), IN p_NeedMoney DECIMAL(9,2), INOUT p_UserID INT, IN p_IP VARCHAR(50), IN p_NickName VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  IF p_NickName IS NULL OR p_NickName = '' THEN
    SELECT IFNULL(`UserID`, 0), `NickName` INTO p_UserID, p_NickName FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  ELSE
    SELECT IFNULL(`UserID`, 0) INTO p_UserID FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName AND `NickName` = p_NickName LIMIT 1;
    IF (p_UserID = 0) THEN
      SELECT IFNULL(`userID`, 0) INTO p_UserID FROM `Rename_Nick` WHERE `UserName` = p_UserName AND `NickName` = p_NickName LIMIT 1;
    END IF;
  END IF;
  IF p_UserID = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_count FROM `Charge_Money` WHERE `ChargeID` = p_ChargeID LIMIT 1;
  IF v_count > 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Charge_Money` (`ChargeID`, `UserName`, `Money`, `Date`, `CanUse`, `PayWay`, `NeedMoney`, `IP`, `NickName`) VALUES (p_ChargeID, p_UserName, p_Money, p_Date, 1, p_PayWay, p_NeedMoney, p_IP, p_NickName);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `ChargeDate` = NOW(3) WHERE `UserID` = p_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Charge_Money_UserId_Add`$$
CREATE PROCEDURE `SP_Charge_Money_UserId_Add`(IN p_ChargeID VARCHAR(50), IN p_UserName VARCHAR(200), IN p_Money INT, IN p_Date VARCHAR(50), IN p_PayWay VARCHAR(200), IN p_NeedMoney DECIMAL(9,2), INOUT p_UserID INT, IN p_IP VARCHAR(50), IN p_SourceUserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_NickName VARCHAR(200) DEFAULT NULL;
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT IFNULL(`UserID`, 0), `NickName` INTO p_UserID, v_NickName FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName AND `Userid` = p_SourceUserID LIMIT 1;
  IF p_UserID = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_count FROM `Charge_Money` WHERE `ChargeID` = p_ChargeID LIMIT 1;
  IF v_count > 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Charge_Money` (`ChargeID`, `UserName`, `Money`, `Date`, `CanUse`, `PayWay`, `NeedMoney`, `IP`, `NickName`) VALUES (p_ChargeID, p_UserName, p_Money, p_Date, 1, p_PayWay, p_NeedMoney, p_IP, v_NickName);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `ChargeDate` = NOW(3) WHERE `UserID` = p_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Charge_Record`$$
CREATE PROCEDURE `SP_Charge_Record`(IN p_Date DATETIME(3), IN p_Second INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT `PayWay` AS `PayWay`, SUM(`money`) AS `money`, SUM(CASE WHEN `sex` = 1 THEN 1 ELSE 0 END) AS `TotalBoy`, SUM(CASE WHEN `sex` = 1 THEN 0 ELSE 1 END) AS `TotalGirl`, SUM(CASE WHEN `sex` = 1 THEN `money` ELSE 0 END) AS `BoyTotalPay`, SUM(CASE WHEN `sex` = 1 THEN 0 ELSE `money` END) AS `GirlTotalPay` FROM `V_Charge_Money` WHERE TIMESTAMPDIFF(SECOND, DATE_FORMAT(`Date`, '%Y-%m-%d %H:%i:%s'), DATE_FORMAT(p_Date, '%Y-%m-%d %H:%i:%s')) < p_Second AND `Date` <= p_Date GROUP BY `PayWay`;
END$$

DROP PROCEDURE IF EXISTS `SP_Charge_To_User`$$
CREATE PROCEDURE `SP_Charge_To_User`(IN p_UserName VARCHAR(200), INOUT p_money INT, IN p_NickName VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT IFNULL(SUM(`Money`), 0) INTO p_money FROM `Charge_Money` WHERE `UserName` = p_UserName AND `CanUse` = 1 AND (`NickName` = p_NickName OR `NickName` IS NULL OR `NickName` = '') LIMIT 1;
  IF p_money = 0 THEN
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Charge_Money` SET `CanUse` = 0 WHERE `UserName` = p_UserName AND `CanUse` = 1 AND (`NickName` = p_NickName OR `NickName` IS NULL OR `NickName` = '');
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `Money` = `Money` + p_money WHERE `UserName` = p_UserName AND `NickName` = p_NickName;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ClearAllMarryInfo`$$
CREATE PROCEDURE `SP_ClearAllMarryInfo`(OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  DELETE FROM `Marry_Room_Info`;
  DELETE FROM `Marry_Info`;
  UPDATE `sys_users_detail` SET `IsCreatedMarryRoom` = 0, `SpouseID` = 0, `SpouseName` = '', `IsMarried` = 0, `MarryInfoID` = 0, `SelfMarryRoomID` = 0, `IsGotRing` = 0;
END$$

DROP PROCEDURE IF EXISTS `SP_ClearMarryInfo`$$
