proc: BEGIN
  SET p_ReturnValue = 0;
  DELETE FROM `Marry_Room_Info` WHERE `GroomName` = p_name OR `BrideName` = p_name;
  UPDATE `sys_users_detail` SET `IsCreatedMarryRoom` = 0, `SpouseID` = 0, `SpouseName` = '', `IsMarried` = 0, `SelfMarryRoomID` = 0, `IsGotRing` = 0 WHERE `nickname` = p_name;
END$$

DROP PROCEDURE IF EXISTS `SP_Clear_AdoptPet`$$
CREATE PROCEDURE `SP_Clear_AdoptPet`(IN p_ID INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  UPDATE `AdoptPetList` SET `IsExit` = 0, `Place` = -1 WHERE `ID` = p_ID AND `PetID` = 0;
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaAlly_Add`$$
CREATE PROCEDURE `SP_ConsortiaAlly_Add`(INOUT p_ID INT, IN p_Consortia1ID INT, IN p_Consortia2ID INT, IN p_State INT, IN p_Date DATETIME(3), IN p_ValidDate INT, IN p_IsExist TINYINT(1), IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Right INT DEFAULT NULL;
  DECLARE v_AllyID INT DEFAULT NULL;
  DECLARE v_OldState INT DEFAULT NULL;
  DECLARE v_Consortia1Name VARCHAR(200) DEFAULT NULL;
  DECLARE v_Consortia2Name VARCHAR(200) DEFAULT NULL;
  DECLARE v_Remark1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Remark2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Remark3 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Remark4 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Type INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_Right FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_Consortia1ID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_Right IS NULL OR (v_Right & 64) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `ID`, `State` INTO v_AllyID, v_OldState FROM `Consortia_Ally` WHERE (`Consortia2ID` = p_Consortia1ID AND `Consortia1ID` = p_Consortia2ID) OR (`Consortia2ID` = p_Consortia2ID AND `Consortia1ID` = p_Consortia1ID) LIMIT 1;
  IF p_State = 1 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  IF p_State = 0 AND v_OldState = 2 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT `ConsortiaName` INTO v_Consortia1Name FROM `Consortia` WHERE `ConsortiaID` = p_Consortia1ID AND `IsExist` = 1 LIMIT 1;
  IF v_Consortia1Name IS NULL OR v_Consortia1Name = '' THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `ConsortiaName` INTO v_Consortia2Name FROM `Consortia` WHERE `ConsortiaID` = p_Consortia2ID AND `IsExist` = 1 LIMIT 1;
  IF v_Consortia2Name IS NULL OR v_Consortia2Name = '' THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE `Consortia2ID` = p_Consortia1ID AND `Consortia1ID` = p_Consortia2ID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE `Consortia2ID` = p_Consortia2ID AND `Consortia1ID` = p_Consortia1ID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF v_AllyID IS NULL OR v_AllyID = 0 THEN
    INSERT INTO `Consortia_Ally` (`Consortia1ID`, `Consortia2ID`, `State`, `Date`, `ValidDate`, `IsExist`) VALUES (p_Consortia1ID, p_Consortia2ID, p_State, p_Date, p_ValidDate, p_IsExist);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    UPDATE `Consortia_Ally` SET `IsExist` = p_IsExist, `State` = p_State, `Date` = p_Date, `ValidDate` = p_ValidDate WHERE `ID` = v_AllyID;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  IF p_State = 2 THEN
    SET v_Remark1 = `GetTranslation`('SP_ConsortiaAlly_Add.Msg1');
    SET v_Remark3 = `GetTranslation`('SP_ConsortiaAlly_Add.Msg2');
    SET v_Type = 1;
  ELSE
    SET v_Remark1 = `GetTranslation`('SP_ConsortiaAlly_Add.Msg3');
    SET v_Remark3 = `GetTranslation`('SP_ConsortiaAlly_Add.Msg4');
    SET v_Type = 4;
  END IF;
  SET v_Remark3 = REPLACE(v_Remark3, '{0}', v_Consortia2Name);
  INSERT INTO `Consortia_Event` (`ConsortiaID`, `Remark`, `Date`, `IsExist`, `Type`) VALUES (p_Consortia1ID, v_Remark3, NOW(3), 1, v_Type);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET v_Remark1 = REPLACE(v_Remark1, '{0}', v_Consortia1Name);
  INSERT INTO `Consortia_Event` (`ConsortiaID`, `Remark`, `Date`, `IsExist`, `Type`) VALUES (p_Consortia2ID, v_Remark1, NOW(3), 1, v_Type);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

