DROP PROCEDURE IF EXISTS `SP_ConsortiaApplyAlly_Add`$$
CREATE PROCEDURE `SP_ConsortiaApplyAlly_Add`(INOUT p_ID INT, IN p_Consortia1ID INT, IN p_Consortia2ID INT, IN p_Date DATETIME(3), IN p_Remark VARCHAR(100), IN p_IsExist TINYINT(1), IN p_UserID INT, IN p_State INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_Consortia1ID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 64) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_Count FROM `Consortia` WHERE `ConsortiaID` = p_Consortia2ID LIMIT 1;
  IF v_Count IS NULL OR v_Count = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_Count FROM `Consortia_Ally` WHERE ((`Consortia2ID` = p_Consortia1ID AND `Consortia1ID` = p_Consortia2ID) OR (`Consortia2ID` = p_Consortia2ID AND `Consortia1ID` = p_Consortia1ID)) AND `State` = p_State AND `IsExist` = 1 LIMIT 1;
  IF v_Count = 1 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT `ID` INTO p_ID FROM `Consortia_Apply_Ally` WHERE `Consortia1ID` = p_Consortia1ID AND `Consortia2ID` = p_Consortia2ID LIMIT 1;
  IF p_ID IS NULL OR p_ID = 0 THEN
    INSERT INTO `Consortia_Apply_Ally` (`Consortia1ID`, `Consortia2ID`, `Date`, `Remark`, `IsExist`, `State`) VALUES (p_Consortia1ID, p_Consortia2ID, p_Date, p_Remark, p_IsExist, p_State);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ID = LAST_INSERT_ID();
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    UPDATE `Consortia_Apply_Ally` SET `Date` = p_Date, `Remark` = p_Remark, `IsExist` = 1, `State` = p_State WHERE `Consortia1ID` = p_Consortia1ID AND `Consortia2ID` = p_Consortia2ID;
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

