DROP PROCEDURE IF EXISTS `SP_ConsortiaApplyAlly_Pass`$$
CREATE PROCEDURE `SP_ConsortiaApplyAlly_Pass`(IN p_ID INT, IN p_UserID INT, IN p_ConsortiaID INT, INOUT p_tempID INT, INOUT p_State INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_AllyID INT DEFAULT NULL;
  DECLARE v_Consortia1Name VARCHAR(200) DEFAULT NULL;
  DECLARE v_Consortia2Name VARCHAR(200) DEFAULT NULL;
  DECLARE v_Remark1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Remark2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Remark3 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Remark4 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Type INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 64) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `Consortia1ID`, `State` INTO p_tempID, p_State FROM `Consortia_Apply_Ally` WHERE `ID` = p_ID AND `Consortia2ID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF p_tempID IS NULL OR p_tempID = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `ID` INTO v_AllyID FROM `Consortia_Ally` WHERE ((`Consortia2ID` = p_ConsortiaID AND `Consortia1ID` = p_tempID) OR (`Consortia2ID` = p_tempID AND `Consortia1ID` = p_ConsortiaID)) LIMIT 1;
  SELECT `ConsortiaName` INTO v_Consortia1Name FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_Consortia1Name IS NULL OR v_Consortia1Name = '' THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  SELECT `ConsortiaName` INTO v_Consortia2Name FROM `Consortia` WHERE `ConsortiaID` = p_tempID AND `IsExist` = 1 LIMIT 1;
  IF v_Consortia2Name IS NULL OR v_Consortia2Name = '' THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE `Consortia2ID` = p_ConsortiaID AND `Consortia1ID` = p_tempID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE `Consortia2ID` = p_tempID AND `Consortia1ID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF v_AllyID IS NULL OR v_AllyID = 0 THEN
    INSERT INTO `Consortia_Ally` (`Consortia1ID`, `Consortia2ID`, `State`, `Date`, `ValidDate`, `IsExist`) VALUES (p_ConsortiaID, p_tempID, p_State, NOW(3), 0, 1);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    UPDATE `Consortia_Ally` SET `IsExist` = 1, `State` = p_State, `Date` = NOW(3) WHERE `ID` = v_AllyID;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  IF p_State = 1 THEN
    SET v_Remark1 = `GetTranslation`('SP_ConsortiaApplyAlly_Pass.Msg1');
    SET v_Remark3 = `GetTranslation`('SP_ConsortiaApplyAlly_Pass.Msg2');
    SET v_Type = 3;
  ELSE
    SET v_Remark1 = `GetTranslation`('SP_ConsortiaApplyAlly_Pass.Msg3');
    SET v_Remark3 = `GetTranslation`('SP_ConsortiaApplyAlly_Pass.Msg4');
    SET v_Type = 2;
  END IF;
  SET v_Remark3 = REPLACE(v_Remark3, '{0}', v_Consortia2Name);
  INSERT INTO `Consortia_Event` (`ConsortiaID`, `Remark`, `Date`, `IsExist`, `Type`) VALUES (p_ConsortiaID, v_Remark3, NOW(3), 1, v_Type);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET v_Remark1 = REPLACE(v_Remark1, '{0}', v_Consortia1Name);
  INSERT INTO `Consortia_Event` (`ConsortiaID`, `Remark`, `Date`, `IsExist`, `Type`) VALUES (p_tempID, v_Remark1, NOW(3), 1, v_Type);
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaApplyUser_Add`$$
CREATE PROCEDURE `SP_ConsortiaApplyUser_Add`(INOUT p_ID INT, IN p_ApplyDate DATETIME(3), IN p_ConsortiaID INT, IN p_ConsortiaName VARCHAR(100), IN p_IsExist TINYINT(1), IN p_Remark VARCHAR(100), IN p_UserID INT, IN p_UserName VARCHAR(100), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_MaxCount INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `ConsortiaName`, `Count`, `MaxCount` INTO p_ConsortiaName, v_Count, v_MaxCount FROM `Consortia` WHERE p_ConsortiaID = `ConsortiaID` AND `IsExist` = 1 LIMIT 1;
  IF p_ConsortiaName IS NULL OR p_ConsortiaName = '' THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF v_Count IS NULL OR v_Count + 1 > v_MaxCount THEN
    SET p_ReturnValue = 6;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_Count FROM `Consortia_Apply_Users` WHERE `UserID` = p_UserID AND p_ConsortiaID = `ConsortiaID` LIMIT 1;
  IF v_Count = 0 THEN
    INSERT INTO `Consortia_Apply_Users` (`ConsortiaID`, `ConsortiaName`, `UserID`, `UserName`, `ApplyDate`, `Remark`, `IsExist`) VALUES (p_ConsortiaID, p_ConsortiaName, p_UserID, p_UserName, p_ApplyDate, p_Remark, p_IsExist);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ID = LAST_INSERT_ID();
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    UPDATE `Consortia_Apply_Users` SET `ConsortiaID` = p_ConsortiaID, `ConsortiaName` = p_ConsortiaName, `ApplyDate` = p_ApplyDate, `Remark` = p_Remark, `IsExist` = 1 WHERE `UserID` = p_UserID AND p_ConsortiaID = `ConsortiaID`;
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaApplyUser_Delete`$$
CREATE PROCEDURE `SP_ConsortiaApplyUser_Delete`(IN p_ID INT, IN p_UserID INT, IN p_ConsortiaID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_tempID INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  IF p_ConsortiaID <> 0 THEN
    SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
    IF v_tempRight IS NULL OR (v_tempRight & 1) = 0 THEN
      SET p_ReturnValue = 2;
      LEAVE proc;
    END IF;
    UPDATE `Consortia_Apply_Users` SET `IsExist` = 0 WHERE `ID` = p_ID AND `ConsortiaID` = p_ConsortiaID;
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    SELECT `UserID` INTO v_tempID FROM `Consortia_Apply_Users` WHERE `ID` = p_ID AND `IsExist` = 1 LIMIT 1;
    IF v_tempID IS NULL OR v_tempID <> p_UserID THEN
      SET p_ReturnValue = 3;
      LEAVE proc;
    END IF;
    UPDATE `Consortia_Apply_Users` SET `IsExist` = 0 WHERE `ID` = p_ID;
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaApplyUser_Pass`$$
CREATE PROCEDURE `SP_ConsortiaApplyUser_Pass`(IN p_ID INT, IN p_UserID INT, IN p_UserName VARCHAR(100), IN p_ConsortiaID INT, INOUT p_tempID INT, INOUT p_tempName VARCHAR(100), INOUT p_tempDutyID INT, INOUT p_tempDutyName VARCHAR(100), INOUT p_tempOffer INT, INOUT p_tempRichesOffer INT, INOUT p_tempRichesRob INT, INOUT p_tempLastDate DATETIME(3), INOUT p_tempWin INT, INOUT p_tempTotal INT, INOUT p_tempEscape INT, INOUT p_tempGrade INT, INOUT p_tempLevel INT, INOUT p_tempCUID INT, INOUT p_tempState INT, INOUT p_tempSex INT, INOUT p_tempDutyRight INT, INOUT p_tempConsortiaRepute INT, INOUT p_tempLoginName VARCHAR(100), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_DutyID INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_MaxCount INT DEFAULT NULL;
  DECLARE v_orderID INT DEFAULT NULL;
  DECLARE v_temp TINYINT(1) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 1) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `UserID`, `UserName` INTO p_tempID, p_tempName FROM `Consortia_Apply_Users` WHERE `ID` = p_ID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF p_tempID IS NULL OR p_tempID = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `Count`, `MaxCount`, `Repute` INTO v_Count, v_MaxCount, p_tempConsortiaRepute FROM `Consortia` WHERE p_ConsortiaID = `ConsortiaID` AND `IsExist` = 1 LIMIT 1;
  IF v_Count IS NULL OR v_Count + 1 > v_MaxCount THEN
    SET p_ReturnValue = 6;
    LEAVE proc;
  END IF;
  SELECT `DutyID`, `DutyID`, `DutyName`, `Level`, `Right` INTO v_DutyID, p_tempDutyID, p_tempDutyName, p_tempLevel, p_tempDutyRight FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 AND `Level` IN (SELECT MAX(`Level`) FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1) LIMIT 1;
  IF v_DutyID IS NULL OR v_DutyID = 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT `ID`, `IsExist` INTO v_orderID, v_temp FROM `Consortia_Users` WHERE `UserID` = p_tempID LIMIT 1;
  IF v_temp = 1 THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Apply_Users` SET `IsExist` = 0 WHERE `UserID` = p_tempID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Invite_Users` SET `IsExist` = 0 WHERE `UserID` = p_tempID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia` SET `Count` = `Count` + 1 WHERE `ConsortiaID` = p_ConsortiaID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF v_orderID IS NULL OR v_orderID = 0 THEN
    INSERT INTO `Consortia_Users` (`ConsortiaID`, `UserID`, `UserName`, `RatifierID`, `RatifierName`, `DutyID`, `Remark`, `IsExist`, `IsBanChat`) VALUES (p_ConsortiaID, p_tempID, p_tempName, p_UserID, p_UserName, v_DutyID, '', 1, 0);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_tempCUID = LAST_INSERT_ID();
  ELSE
    UPDATE `Consortia_Users` SET `ConsortiaID` = p_ConsortiaID, `RatifierID` = p_UserID, `RatifierName` = p_UserName, `DutyID` = v_DutyID, `Remark` = '', `IsExist` = 1, `IsBanChat` = 0 WHERE `ID` = v_orderID;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    SET p_tempCUID = v_orderID;
  END IF;
  SELECT `Offer`, `RichesOffer`, `RichesRob`, `LastDate`, `Win`, `Total`, `Escape`, `Grade`, `State`, `Sex`, `UserName` INTO p_tempOffer, p_tempRichesOffer, p_tempRichesRob, p_tempLastDate, p_tempWin, p_tempTotal, p_tempEscape, p_tempGrade, p_tempState, p_tempSex, p_tempLoginName FROM `Sys_Users_Detail` WHERE `UserID` = p_tempID LIMIT 1;
UPDATE `Sys_Users_Detail` SET `ConsortiaID` = p_ConsortiaID, `IsConsortia` = 1 WHERE `UserID` = p_tempID;
  INSERT INTO `Consortia_Event` (`ConsortiaID`, `Date`, `Type`, `NickName`, `EventValue`, `ManagerName`, `IsExist`, `Remark`) VALUES (p_ConsortiaID, NOW(3), 6, p_tempName, 0, p_UserName, 1, '');
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

