DROP PROCEDURE IF EXISTS `SP_ConsortiaChangeChairman`$$
CREATE PROCEDURE `SP_ConsortiaChangeChairman`(IN p_NickName VARCHAR(200), IN p_ConsortiaID INT, IN p_UserID INT, INOUT p_tempUserID INT, INOUT p_tempUserName VARCHAR(200), INOUT p_tempDutyLevel INT, INOUT p_tempDutyName VARCHAR(200), INOUT p_tempRight INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_ID INT DEFAULT NULL;
  DECLARE v_IsExist TINYINT(1) DEFAULT NULL;
  DECLARE v_Grade INT DEFAULT NULL;
  DECLARE v_CurrentLevel INT DEFAULT NULL;
  DECLARE v_CurrentID INT DEFAULT NULL;
  DECLARE v_CurrentName VARCHAR(200) DEFAULT NULL;
  DECLARE v_Duty INT DEFAULT NULL;
  DECLARE v_MaxDuty INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_Count FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `ChairmanID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_Count IS NULL OR v_Count = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `IsExist` INTO v_IsExist FROM `Sys_Users_Detail` WHERE `NickName` = p_NickName LIMIT 1;
  IF v_IsExist IS NULL OR v_IsExist = 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SELECT IFNULL(`Grade`, 0) INTO v_Grade FROM `Sys_Users_Detail` WHERE `NickName` = p_NickName AND `IsExist` = 1 LIMIT 1;
  IF v_Grade IS NULL OR v_Grade < 5 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `Level`, `UserID`, `UserName`, `ID`, `UserID`, `UserName` INTO v_CurrentLevel, v_CurrentID, v_CurrentName, v_ID, p_tempUserID, p_tempUserName FROM `V_Consortia_Users` WHERE `UserName` = p_NickName AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_CurrentLevel IS NULL OR v_CurrentLevel = 1 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `DutyID` INTO v_Duty FROM `Consortia_Duty` WHERE `Level` = 1 AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_Duty IS NULL THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT `DutyID`, `Level`, `DutyName`, `Right` INTO v_MaxDuty, p_tempDutyLevel, p_tempDutyName, p_tempRight FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 AND `Level` IN (SELECT MAX(`Level`) FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1) LIMIT 1;
  IF v_MaxDuty IS NULL THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia` SET `ChairmanID` = v_CurrentID, `ChairmanName` = v_CurrentName WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `DutyID` = v_MaxDuty WHERE `DutyID` = v_Duty AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `DutyID` = v_Duty WHERE `ID` = v_ID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

