DROP PROCEDURE IF EXISTS `SP_ConsortiaDuty_Add`$$
CREATE PROCEDURE `SP_ConsortiaDuty_Add`(INOUT p_DutyID INT, IN p_ConsortiaID INT, IN p_DutyName VARCHAR(100), IN p_Level INT, IN p_UserID INT, IN p_Right INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 128) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT IFNULL(MAX(`Level`), 0) INTO p_Level FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF p_Level > 9 OR p_Level IS NULL OR p_Level = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Duty` SET `Level` = `Level` + 1 WHERE `Level` = p_Level AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Consortia_Duty` (`ConsortiaID`, `DutyName`, `Right`, `Level`) VALUES (p_ConsortiaID, p_DutyName, p_Right, p_Level);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaDuty_Delete`$$
CREATE PROCEDURE `SP_ConsortiaDuty_Delete`(IN p_UserID INT, IN p_ConsortiaID INT, IN p_DutyID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_CurrentLevel INT DEFAULT NULL;
  DECLARE v_MaxLevel INT DEFAULT NULL;
  DECLARE v_MaxDuty INT DEFAULT NULL;
  DECLARE v_tempIsManageDuty TINYINT(1) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Level` INTO v_CurrentLevel FROM `Consortia_Duty` WHERE `DutyID` = p_DutyID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_CurrentLevel IS NULL OR v_CurrentLevel = 1 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `DutyID`, `Level` INTO v_MaxDuty, v_MaxLevel FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 AND `Level` IN (SELECT MAX(`Level`) FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1) LIMIT 1;
  IF v_MaxLevel IS NULL OR v_MaxLevel = v_CurrentLevel THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Duty` SET `IsExist` = 0 WHERE `DutyID` = p_DutyID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Duty` SET `Level` = `Level` - 1 WHERE `ConsortiaID` = p_ConsortiaID AND `Level` > v_CurrentLevel AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `DutyID` = v_MaxDuty WHERE `DutyID` = p_DutyID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaDuty_Update`$$
CREATE PROCEDURE `SP_ConsortiaDuty_Update`(INOUT p_DutyID INT, IN p_ConsortiaID INT, INOUT p_DutyName VARCHAR(100), INOUT p_Level INT, IN p_UserID INT, IN p_UpdateType INT, INOUT p_Right INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_CurrentLevel INT DEFAULT NULL;
  DECLARE v_MaxLevel INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 64) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_UpdateType = 1 THEN
    SELECT IFNULL(MAX(`Level`), 0) INTO p_Level FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
    IF p_Level > 9 OR p_Level IS NULL OR p_Level = 0 THEN
      SET p_ReturnValue = 5;
      LEAVE proc;
    END IF;
    START TRANSACTION;
    UPDATE `Consortia_Duty` SET `Level` = `Level` + 1 WHERE `Level` = p_Level AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    INSERT INTO `Consortia_Duty` (`ConsortiaID`, `DutyName`, `Level`, `Right`) VALUES (p_ConsortiaID, p_DutyName, p_Level, p_Right);
    SET p_DutyID = LAST_INSERT_ID();
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    COMMIT;
  END IF;
  IF p_UpdateType = 2 THEN
    SELECT IFNULL(`Level`, 0) INTO p_Level FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1 LIMIT 1;
    IF p_Level = 1 THEN
      SELECT `Right`, `Level` INTO p_Right, p_Level FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1 LIMIT 1;
UPDATE `Consortia_Duty` SET `DutyName` = p_DutyName WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1;
      IF 0 <> 0 THEN
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
    ELSE
      SELECT `Right`, `Level` INTO p_Right, p_Level FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1 LIMIT 1;
UPDATE `Consortia_Duty` SET `DutyName` = p_DutyName WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1;
      IF 0 <> 0 THEN
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
    END IF;
  END IF;
  IF p_UpdateType = 3 THEN
    SELECT `Level` INTO v_CurrentLevel FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1 LIMIT 1;
    IF v_CurrentLevel IS NULL OR v_CurrentLevel < 3 THEN
      SET p_ReturnValue = 3;
      LEAVE proc;
    END IF;
    SELECT MAX(`Level`) INTO v_MaxLevel FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
    IF v_MaxLevel IS NULL OR v_MaxLevel = v_CurrentLevel THEN
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
    START TRANSACTION;
    UPDATE `Consortia_Duty` SET `Level` = v_CurrentLevel WHERE `ConsortiaID` = p_ConsortiaID AND `Level` = v_CurrentLevel - 1 AND `IsExist` = 1;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    UPDATE `Consortia_Duty` SET `Level` = `Level` - 1 WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    COMMIT;
  END IF;
  IF p_UpdateType = 4 THEN
    SELECT `Level` INTO v_CurrentLevel FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1 LIMIT 1;
    IF v_CurrentLevel IS NULL OR v_CurrentLevel = 1 THEN
      SET p_ReturnValue = 3;
      LEAVE proc;
    END IF;
    SELECT MAX(`Level`) INTO v_MaxLevel FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
    IF v_MaxLevel IS NULL OR v_MaxLevel < v_CurrentLevel + 2 THEN
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
    START TRANSACTION;
    UPDATE `Consortia_Duty` SET `Level` = v_CurrentLevel WHERE `ConsortiaID` = p_ConsortiaID AND `Level` = v_CurrentLevel + 1 AND `IsExist` = 1;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    UPDATE `Consortia_Duty` SET `Level` = `Level` + 1 WHERE `ConsortiaID` = p_ConsortiaID AND `DutyID` = p_DutyID AND `IsExist` = 1;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    COMMIT;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaInviteUser_Add`$$
CREATE PROCEDURE `SP_ConsortiaInviteUser_Add`(INOUT p_ID INT, IN p_ConsortiaID INT, IN p_ConsortiaName VARCHAR(100), IN p_InviteDate DATETIME(3), IN p_InviteID INT, IN p_InviteName VARCHAR(100), IN p_IsExist TINYINT(1), IN p_Remark VARCHAR(100), INOUT p_UserID INT, IN p_UserName VARCHAR(100), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempID INT DEFAULT NULL;
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_tempConsortiaID INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_MaxCount INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_InviteID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 2) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `UserID`, `ConsortiaID` INTO p_UserID, v_tempConsortiaID FROM `Sys_Users_Detail` WHERE `NickName` = p_UserName AND `IsExist` = 1 LIMIT 1;
  IF p_UserID IS NULL OR p_UserID = 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  IF v_tempConsortiaID <> 0 THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  SELECT `ConsortiaName` INTO p_ConsortiaName FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF p_ConsortiaName IS NULL OR p_ConsortiaName = '' THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `Count`, `MaxCount` INTO v_Count, v_MaxCount FROM `Consortia` WHERE p_ConsortiaID = `ConsortiaID` AND `IsExist` = 1 LIMIT 1;
  IF v_Count IS NULL OR v_Count + 1 > v_MaxCount THEN
    SET p_ReturnValue = 6;
    LEAVE proc;
  END IF;
  SELECT `ID` INTO p_ID FROM `Consortia_Invite_Users` WHERE `UserID` = p_UserID AND `ConsortiaID` = p_ConsortiaID LIMIT 1;
  IF p_ID = 0 OR p_ID IS NULL THEN
    INSERT INTO `Consortia_Invite_Users` (`ConsortiaID`, `ConsortiaName`, `InviteDate`, `InviteID`, `InviteName`, `IsExist`, `Remark`, `UserID`, `UserName`) VALUES (p_ConsortiaID, p_ConsortiaName, p_InviteDate, p_InviteID, p_InviteName, p_IsExist, p_Remark, p_UserID, p_UserName);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ID = LAST_INSERT_ID();
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  ELSE
    UPDATE `Consortia_Invite_Users` SET `InviteDate` = p_InviteDate, `InviteID` = p_InviteID, `InviteName` = p_InviteName, `Remark` = p_Remark, `IsExist` = 1 WHERE `ID` = p_ID;
    IF 0 <> 0 THEN
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

