DROP PROCEDURE IF EXISTS `SP_ConsortiaInviteUser_Pass`$$
CREATE PROCEDURE `SP_ConsortiaInviteUser_Pass`(IN p_ID INT, IN p_UserID INT, IN p_UserName VARCHAR(100), INOUT p_ConsortiaID INT, INOUT p_ConsortiaName VARCHAR(100), INOUT p_tempName VARCHAR(100), INOUT p_tempDutyID INT, INOUT p_tempDutyName VARCHAR(100), INOUT p_tempOffer INT, INOUT p_tempRichesOffer INT, INOUT p_tempRichesRob INT, INOUT p_tempLastDate DATETIME(3), INOUT p_tempWin INT, INOUT p_tempTotal INT, INOUT p_tempEscape INT, INOUT p_tempID INT, INOUT p_tempGrade INT, INOUT p_tempLevel INT, INOUT p_tempCUID INT, INOUT p_tempState INT, INOUT p_tempSex INT, INOUT p_tempRight INT, INOUT p_tempConsortiaRepute INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_DutyID INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_MaxCount INT DEFAULT NULL;
  DECLARE v_orderID INT DEFAULT NULL;
  DECLARE v_temp TINYINT(1) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `InviteID`, `InviteName`, `ConsortiaID`, `ConsortiaName` INTO p_tempID, p_tempName, p_ConsortiaID, p_ConsortiaName FROM `Consortia_Invite_Users` WHERE `ID` = p_ID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF p_tempID IS NULL OR p_tempID = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT `Count`, `MaxCount`, `Repute` INTO v_Count, v_MaxCount, p_tempConsortiaRepute FROM `Consortia` WHERE p_ConsortiaID = `ConsortiaID` AND `IsExist` = 1 LIMIT 1;
  IF v_Count IS NULL OR v_Count + 1 > v_MaxCount THEN
    SET p_ReturnValue = 6;
    LEAVE proc;
  END IF;
  SELECT `DutyID`, `DutyID`, `DutyName`, `Level`, `Right` INTO v_DutyID, p_tempDutyID, p_tempDutyName, p_tempLevel, p_tempRight FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 AND `Level` IN (SELECT MAX(`Level`) FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1) LIMIT 1;
  IF v_DutyID IS NULL OR v_DutyID = 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT `ID`, `IsExist` INTO v_orderID, v_temp FROM `Consortia_Users` WHERE `UserID` = p_UserID LIMIT 1;
  IF v_temp = 1 THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Apply_Users` SET `IsExist` = 0 WHERE `UserID` = p_UserID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Invite_Users` SET `IsExist` = 0 WHERE `UserID` = p_UserID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia` SET `Count` = `Count` + 1 WHERE `ConsortiaID` = p_ConsortiaID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF v_orderID IS NULL OR v_orderID = 0 THEN
    INSERT INTO `Consortia_Users` (`ConsortiaID`, `UserID`, `UserName`, `RatifierID`, `RatifierName`, `DutyID`, `Remark`, `IsExist`, `IsBanChat`) VALUES (p_ConsortiaID, p_UserID, p_UserName, p_tempID, p_tempName, v_DutyID, '', 1, 0);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_tempCUID = LAST_INSERT_ID();
  ELSE
    UPDATE `Consortia_Users` SET `ConsortiaID` = p_ConsortiaID, `RatifierID` = p_tempID, `RatifierName` = p_tempName, `DutyID` = v_DutyID, `Remark` = '', `IsExist` = 1, `IsBanChat` = 0 WHERE `ID` = v_orderID;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
    SET p_tempCUID = v_orderID;
  END IF;
  SELECT `Offer`, `RichesOffer`, `RichesRob`, `LastDate`, `Win`, `Total`, `Escape`, `Grade`, `State`, `Sex` INTO p_tempOffer, p_tempRichesOffer, p_tempRichesRob, p_tempLastDate, p_tempWin, p_tempTotal, p_tempEscape, p_tempGrade, p_tempState, p_tempSex FROM `Sys_Users_Detail` WHERE `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
UPDATE `Sys_Users_Detail` SET `ConsortiaID` = p_ConsortiaID, `IsConsortia` = 1 WHERE `UserID` = p_UserID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_ConsortiaIsBanChat_Update`$$
CREATE PROCEDURE `SP_ConsortiaIsBanChat_Update`(IN p_ID INT, IN p_ConsortiaID INT, IN p_UserID INT, IN p_IsBanChat INT, INOUT p_tempID INT, INOUT p_tempName VARCHAR(100), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL OR (v_tempRight & 4) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `UserID`, `UserName` INTO p_tempID, p_tempName FROM `Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_ID AND `IsExist` = 1 LIMIT 1;
  IF p_tempID IS NULL OR p_tempID = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `IsBanChat` = p_IsBanChat WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_ID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

