DROP PROCEDURE IF EXISTS `SP_ConsortiaUserGrade_Update`$$
CREATE PROCEDURE `SP_ConsortiaUserGrade_Update`(IN p_ID INT, IN p_ConsortiaID INT, IN p_UserID INT, IN p_UpGrade TINYINT(1), INOUT p_tempUserName VARCHAR(100), INOUT p_tempDutyLevel INT, INOUT p_tempDutyName VARCHAR(100), INOUT p_tempRight INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_tempRight1 INT DEFAULT NULL;
  DECLARE v_CurrentLevel INT DEFAULT NULL;
  DECLARE v_MaxLevel INT DEFAULT NULL;
  DECLARE v_Duty INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Right` INTO v_tempRight1 FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight1 IS NULL OR (v_tempRight1 & 2048) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `Level`, `UserName` INTO v_CurrentLevel, p_tempUserName FROM `V_Consortia_Users` WHERE `UserID` = p_ID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_CurrentLevel IS NULL OR v_CurrentLevel = 1 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  IF p_UpGrade = 1 THEN
    IF v_CurrentLevel = 2 THEN
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
    SET v_CurrentLevel = v_CurrentLevel - 1;
  ELSE
    SELECT `Level` INTO v_MaxLevel FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 AND `Level` IN (SELECT MAX(`Level`) FROM `Consortia_Duty` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1) LIMIT 1;
    IF v_MaxLevel IS NULL OR v_MaxLevel = v_CurrentLevel OR v_MaxLevel < v_CurrentLevel THEN
      SET p_ReturnValue = 5;
      LEAVE proc;
    END IF;
    SET v_CurrentLevel = v_CurrentLevel + 1;
  END IF;
  SELECT `DutyID`, `Level`, `DutyName`, `Right` INTO v_Duty, p_tempDutyLevel, p_tempDutyName, p_tempRight FROM `Consortia_Duty` WHERE `Level` = v_CurrentLevel AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_Duty IS NULL THEN
    SET p_ReturnValue = 6;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `DutyID` = v_Duty WHERE `UserID` = p_ID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

