DROP PROCEDURE IF EXISTS `SP_ConsortiaUser_Delete`$$
CREATE PROCEDURE `SP_ConsortiaUser_Delete`(IN p_UserID INT, IN p_KickUserID INT, IN p_ConsortiaID INT, INOUT p_NickName VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Level INT DEFAULT NULL;
  DECLARE v_tempRight INT DEFAULT NULL;
  DECLARE v_KickDate DATETIME(3) DEFAULT NULL;
  DECLARE v_KickCount INT DEFAULT NULL;
  DECLARE v_KickMax INT DEFAULT NULL;
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET p_NickName = '';
  SELECT `Right`, `Level` INTO v_tempRight, v_Level FROM `V_Consortia_Users` WHERE `ConsortiaID` = p_ConsortiaID AND `UserID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_tempRight IS NULL THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_UserID <> p_KickUserID AND (v_tempRight & 32) = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_UserID = p_KickUserID AND v_Level = 1 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_count FROM `Consortia` WHERE `ChairmanID` = p_KickUserID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_count > 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT `KickDate`, `KickMax`, `KickCount` INTO v_KickDate, v_KickMax, v_KickCount FROM `Consortia` AS `A` LEFT JOIN `Consortia_Level` AS `B` ON `A`.`Level` = `b`.`Level` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF (p_UserID <> p_KickUserID) THEN
    IF (v_KickDate = LEFT(DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s'), 10) AND v_KickCount > 0) OR (v_KickDate <> LEFT(DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s'), 10)) THEN
      IF (v_KickDate <> LEFT(DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s'), 10)) THEN
        SET v_KickCount = v_KickMax;
      END IF;
      SET v_KickDate = LEFT(DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s'), 10);
      SET v_KickCount = v_KickCount - 1;
    ELSE
      SET p_ReturnValue = 5;
      LEAVE proc;
    END IF;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia` SET `Count` = `Count` - 1, `KickDate` = v_KickDate, `KickCount` = v_KickCount WHERE `ConsortiaID` = p_ConsortiaID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `IsExist` = 0 WHERE `UserID` = p_KickUserID AND `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 OR ROW_COUNT() = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SELECT `NickName` INTO p_NickName FROM `Sys_Users_Detail` WHERE `UserID` = p_KickUserID AND `ConsortiaID` = p_ConsortiaID LIMIT 1;
UPDATE `Sys_Users_Detail` SET `ConsortiaID` = 0, `RichesOffer` = 0, `RichesRob` = 0 WHERE `UserID` = p_KickUserID AND `ConsortiaID` = p_ConsortiaID;
  IF (p_UserID = p_KickUserID) THEN
    INSERT INTO `Consortia_Event` (`ConsortiaID`, `Date`, `Type`, `NickName`, `EventValue`, `ManagerName`, `IsExist`, `Remark`) VALUES (p_ConsortiaID, NOW(3), 8, (SELECT `NickName` FROM `Sys_Users_Detail` WHERE `UserID` = p_KickUserID), 0, NULL, 1, '');
  END IF;
  IF (p_UserID <> p_KickUserID) THEN
    INSERT INTO `Consortia_Event` (`ConsortiaID`, `Date`, `Type`, `NickName`, `EventValue`, `ManagerName`, `IsExist`, `Remark`) VALUES (p_ConsortiaID, NOW(3), 7, (SELECT `NickName` FROM `Sys_Users_Detail` WHERE `UserID` = p_KickUserID), 0, (SELECT `NickName` FROM `Sys_Users_Detail` WHERE `UserID` = p_UserID), 1, '');
  END IF;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Consortia_Add`$$
CREATE PROCEDURE `SP_Consortia_Add`(INOUT p_ConsortiaID INT, IN p_BuildDate DATETIME(3), IN p_CelebCount INT, IN p_ChairmanID INT, IN p_ChairmanName VARCHAR(100), IN p_ConsortiaName VARCHAR(100), IN p_CreatorID INT, IN p_CreatorName VARCHAR(100), IN p_Description VARCHAR(1000), IN p_Honor INT, IN p_IP VARCHAR(100), IN p_IsExist TINYINT(1), IN p_Level INT, IN p_MaxCount INT, IN p_Placard VARCHAR(1000), IN p_Port INT, IN p_Repute INT, IN p_Count INT, IN p_Riches INT, INOUT p_tempDutyLevel INT, INOUT p_tempDutyName VARCHAR(200), INOUT p_tempRight INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Same INT DEFAULT NULL;
  DECLARE v_ID INT DEFAULT NULL;
  DECLARE v_temp TINYINT(1) DEFAULT NULL;
  DECLARE v_DutyID INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_Same FROM `Consortia` WHERE `ConsortiaName` = p_ConsortiaName AND `IsExist` = 1 LIMIT 1;
  IF v_Same <> 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT `ID`, `IsExist` INTO v_ID, v_temp FROM `Consortia_Users` WHERE `UserID` = p_CreatorID LIMIT 1;
  IF v_temp = 1 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SET p_tempDutyLevel = 1;
  SET p_tempDutyName = `GetTranslation`('SP_Consortia_Add.Duty1');
  SET p_tempRight = 4095;
  START TRANSACTION;
  INSERT INTO `Consortia` (`BuildDate`, `CelebCount`, `ChairmanID`, `ChairmanName`, `ConsortiaName`, `CreatorID`, `CreatorName`, `Description`, `Honor`, `IP`, `IsExist`, `Level`, `MaxCount`, `Placard`, `Port`, `Repute`, `Count`, `Riches`) VALUES (p_BuildDate, p_CelebCount, p_ChairmanID, p_ChairmanName, p_ConsortiaName, p_CreatorID, p_CreatorName, p_Description, p_Honor, p_IP, p_IsExist, p_Level, p_MaxCount, p_Placard, p_Port, p_Repute, p_Count, p_Riches);
  SELECT LAST_INSERT_ID() AS `identity`;
  SET p_ConsortiaID = LAST_INSERT_ID();
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  INSERT INTO `Consortia_Duty` (`ConsortiaID`, `Level`, `DutyName`, `Right`, `IsExist`) VALUES (p_ConsortiaID, 1, `GetTranslation`('SP_Consortia_Add.Duty1'), 4095, 1);
  SELECT LAST_INSERT_ID() AS `identity`;
  SET v_DutyID = LAST_INSERT_ID();
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  INSERT INTO `Consortia_Duty` (`ConsortiaID`, `Level`, `DutyName`, `Right`, `IsExist`) VALUES (p_ConsortiaID, 2, `GetTranslation`('SP_Consortia_Add.Duty2'), 6191, 1);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  INSERT INTO `Consortia_Duty` (`ConsortiaID`, `Level`, `DutyName`, `Right`, `IsExist`) VALUES (p_ConsortiaID, 3, `GetTranslation`('SP_Consortia_Add.Duty3'), 4103, 1);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  INSERT INTO `Consortia_Duty` (`ConsortiaID`, `Level`, `DutyName`, `Right`, `IsExist`) VALUES (p_ConsortiaID, 4, `GetTranslation`('SP_Consortia_Add.Duty4'), 4096, 1);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  INSERT INTO `Consortia_Duty` (`ConsortiaID`, `Level`, `DutyName`, `Right`, `IsExist`) VALUES (p_ConsortiaID, 5, `GetTranslation`('SP_Consortia_Add.Duty5'), 4096, 1);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  IF v_ID IS NULL OR v_ID = 0 THEN
    INSERT INTO `Consortia_Users` (`ConsortiaID`, `UserID`, `UserName`, `RatifierID`, `RatifierName`, `DutyID`, `Remark`, `IsExist`, `IsBanChat`) VALUES (p_ConsortiaID, p_CreatorID, p_CreatorName, p_CreatorID, p_CreatorName, v_DutyID, '', 1, 0);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
  ELSE
    UPDATE `Consortia_Users` SET `ConsortiaID` = p_ConsortiaID, `RatifierID` = p_CreatorID, `RatifierName` = p_CreatorName, `DutyID` = v_DutyID, `Remark` = '', `IsExist` = 1, `IsBanChat` = 0 WHERE `ID` = v_ID;
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
  END IF;
  UPDATE `Sys_Users_Detail` SET `ConsortiaID` = p_ConsortiaID, `IsConsortia` = 1 WHERE `UserID` = p_CreatorID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

