DROP PROCEDURE IF EXISTS `SP_Consortia_Delete`$$
CREATE PROCEDURE `SP_Consortia_Delete`(IN p_ConsortiaID INT, IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_Count FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `ChairmanID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_Count IS NULL OR v_Count = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT IFNULL(COUNT(*), 0) INTO v_Count FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `Level` >= 4 LIMIT 1;
  IF (v_Count = 1) THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia_Equip_Control` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Apply_Users` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Invite_Users` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE (`Consortia1ID` = p_ConsortiaID OR `Consortia2ID` = p_ConsortiaID) AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Duty` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Users` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Ally` SET `IsExist` = 0 WHERE (`Consortia1ID` = p_ConsortiaID OR `Consortia2ID` = p_ConsortiaID) AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Consortia_Event` SET `IsExist` = 0 WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `ConsortiaID` = 0, `RichesOffer` = 0, `RichesRob` = 0 WHERE `ConsortiaID` = p_ConsortiaID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Consortia_Equip_Control_Add`$$
CREATE PROCEDURE `SP_Consortia_Equip_Control_Add`(IN p_ConsortiaID INT, IN p_Level INT, IN p_Type INT, IN p_Riches INT, IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  DECLARE v_temp INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_count FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `ChairmanID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_count IS NULL OR v_count = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_temp FROM `Consortia_Equip_Control` WHERE `ConsortiaID` = p_ConsortiaID AND `Level` = p_Level AND `Type` = p_Type LIMIT 1;
  IF v_temp = 0 THEN
    INSERT INTO `Consortia_Equip_Control` (`ConsortiaID`, `Level`, `Type`, `Riches`, `IsExist`) VALUES (p_ConsortiaID, p_Level, p_Type, p_Riches, 1);
  ELSE
    UPDATE `Consortia_Equip_Control` SET `Riches` = p_Riches, `IsExist` = 1 WHERE `ConsortiaID` = p_ConsortiaID AND `Level` = p_Level AND `Type` = p_Type;
  END IF;
END$$

