DROP PROCEDURE IF EXISTS `SP_Consortia_Fight`$$
CREATE PROCEDURE `SP_Consortia_Fight`(IN p_ConsortiaWin INT, IN p_ConsortiaLose INT, IN p_PlayerCount INT, INOUT p_Riches INT, IN p_State INT, IN p_TotalKillHealth INT, IN p_RichesRate DECIMAL(6,2), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_WinLevel INT DEFAULT NULL;
  DECLARE v_LoseLevel INT DEFAULT NULL;
  DECLARE v_WinRiches INT DEFAULT NULL;
  DECLARE v_LoseRiches INT DEFAULT NULL;
  DECLARE v_modulus INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  IF p_PlayerCount < 1 THEN
    SET p_ReturnValue = 6;
    LEAVE proc;
  END IF;
  SELECT `Level`, `Riches` INTO v_WinLevel, v_WinRiches FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaWin AND `IsExist` = 1 LIMIT 1;
  IF v_WinLevel IS NULL THEN
    SET p_ReturnValue = 7;
    LEAVE proc;
  END IF;
  IF v_WinLevel < 3 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SELECT `Level`, `Riches` INTO v_LoseLevel, v_LoseRiches FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaLose AND `IsExist` = 1 LIMIT 1;
  IF v_LoseLevel IS NULL THEN
    SET p_ReturnValue = 8;
    LEAVE proc;
  END IF;
  IF v_LoseLevel < 3 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_State = 2 THEN
    SET v_modulus = 2;
  ELSE
    SET v_modulus = 1;
  END IF;
  SET p_Riches = (p_PlayerCount + p_TotalKillHealth DIV 2000) * v_modulus DIV 2 * p_RichesRate;
  START TRANSACTION;
  UPDATE `Consortia` SET `Riches` = `Riches` + p_Riches, `WarnDate` = NOW(3) WHERE `ConsortiaID` = p_ConsortiaWin;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  COMMIT;
  SELECT p_Riches;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

