DROP PROCEDURE IF EXISTS `SP_Consortia_Riches_Add`$$
CREATE PROCEDURE `SP_Consortia_Riches_Add`(IN p_ConsortiaID INT, INOUT p_Riches INT, IN p_Type INT, IN p_UserName VARCHAR(100), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_OrdRiches INT DEFAULT NULL;
  DECLARE v_Remark1 VARCHAR(100) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `Riches` INTO v_OrdRiches FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_OrdRiches IS NULL THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_Riches < 0 AND v_OrdRiches < -p_Riches THEN
    SET p_Riches = -v_OrdRiches;
  END IF;
  START TRANSACTION;
  UPDATE `Consortia` SET `Riches` = `Riches` + p_Riches, `WarnDate` = NOW(3) WHERE `ConsortiaID` = p_ConsortiaID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  IF p_Type = 5 THEN
    SET v_Remark1 = `GetTranslation`('SP_Consortia_Riches_Add.Msg1');
    SET v_Remark1 = REPLACE(v_Remark1, '{0}', p_UserName);
    SET v_Remark1 = REPLACE(v_Remark1, '{1}', p_Riches);
    INSERT INTO `Consortia_Event` (`ConsortiaID`, `Date`, `Type`, `NickName`, `EventValue`, `ManagerName`, `IsExist`, `Remark`) VALUES (p_ConsortiaID, NOW(3), p_Type, p_UserName, p_Riches, p_UserName, 1, v_Remark1);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 4;
      LEAVE proc;
    END IF;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Consortia_Riches_Remove`$$
CREATE PROCEDURE `SP_Consortia_Riches_Remove`(IN p_ConsortiaID INT, INOUT p_Riches INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_OrdRiches INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Riches` INTO v_OrdRiches FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF v_OrdRiches IS NULL THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF v_OrdRiches >= p_Riches THEN
    SET v_OrdRiches = v_OrdRiches - p_Riches;
  END IF;
  UPDATE `Consortia` SET `Riches` = v_OrdRiches WHERE `ConsortiaID` = p_ConsortiaID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SELECT `Riches` INTO p_Riches FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Consortia_Scan`$$
CREATE PROCEDURE `SP_Consortia_Scan`(INOUT p_NoticeID VARCHAR(4000), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET p_NoticeID = '';
  START TRANSACTION;
  CREATE TEMPORARY TABLE `tmp_Disband` (`ConsortiaID` INT NULL);
  INSERT INTO `tmp_Disband` SELECT `ConsortiaID` FROM `Consortia` WHERE DATEDIFF(NOW(3), `WarnDate`) > 14 AND `IsExist` = 1;
  UPDATE `Consortia` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`);
  SELECT CONCAT(p_NoticeID, IFNULL(GROUP_CONCAT(CONCAT(CAST(`ConsortiaID` AS CHAR(20)), ',') SEPARATOR ''), '')) INTO p_NoticeID FROM `tmp_Disband`;
  IF CHAR_LENGTH(RTRIM(p_NoticeID)) > 0 THEN
    SET p_NoticeID = SUBSTRING(p_NoticeID, 1, CHAR_LENGTH(RTRIM(p_NoticeID)) - 1);
    UPDATE `Consortia_Equip_Control` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Apply_Users` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Invite_Users` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE `Consortia1ID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Apply_Ally` SET `IsExist` = 0 WHERE `Consortia2ID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Duty` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Users` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Ally` SET `IsExist` = 0 WHERE `Consortia1ID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Ally` SET `IsExist` = 0 WHERE `Consortia2ID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Consortia_Event` SET `IsExist` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
    UPDATE `Sys_Users_Detail` SET `ConsortiaID` = 0, `RichesOffer` = 0, `RichesRob` = 0 WHERE `ConsortiaID` IN (SELECT `ConsortiaID` FROM `tmp_Disband`) AND `IsExist` = 1;
  END IF;
  DROP TEMPORARY TABLE IF EXISTS `tmp_Disband`;
  UPDATE `Consortia` AS `a` SET `a`.`DeductDate` = NOW(3), `a`.`WarnDate` = (CASE WHEN `a`.`Riches` > 0 THEN NOW(3) ELSE `a`.`WarnDate` END), `a`.`Riches` = `Riches` - (SELECT (CASE WHEN `a`.`Riches` > `b`.`Deduct` THEN `Deduct` ELSE `a`.`Riches` END) FROM `Consortia_Level` AS `b` WHERE `b`.`Level` = `a`.`Level`) WHERE DATEDIFF(NOW(3), `DeductDate`) > 7 AND `IsExist` = 1;
  COMMIT;
  SELECT p_NoticeID;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Consortia_Shop_UpGrade`$$
CREATE PROCEDURE `SP_Consortia_Shop_UpGrade`(IN p_ConsortiaID INT, IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Level INT DEFAULT NULL;
  DECLARE v_Riches INT DEFAULT NULL;
  DECLARE v_ShopLevel INT DEFAULT NULL;
  DECLARE v_ShopRiches INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Level`, `Riches`, `ShopLevel` INTO v_Level, v_Riches, v_ShopLevel FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `ChairmanID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_Level IS NULL OR v_Level = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF v_Level DIV 2 <= v_ShopLevel THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  SET v_ShopLevel = v_ShopLevel + 1;
  SELECT `ShopRiches` INTO v_ShopRiches FROM `Consortia_Level` WHERE `Level` = v_ShopLevel LIMIT 1;
  IF v_ShopRiches IS NULL OR v_ShopRiches = 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  IF v_Riches < v_ShopRiches THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  UPDATE `Consortia` SET `ShopLevel` = `ShopLevel` + 1, `Riches` = v_Riches - v_ShopRiches WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

