DROP PROCEDURE IF EXISTS `SP_Consortia_Task_Info_Create_Or_Update`$$
CREATE PROCEDURE `SP_Consortia_Task_Info_Create_Or_Update`(IN p_ConsortiaID INT, IN p_BeginTime DATETIME(3), IN p_Contribution INT, IN p_Expirience INT, IN p_Offer INT, IN p_BuffID INT, IN p_Level INT, IN p_Riches INT, IN p_Time INT, IN p_ConditionData LONGTEXT, IN p_RankTable LONGTEXT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Count INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_Count FROM `Consortia_Task_Info` WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1 LIMIT 1;
  IF (v_Count = 0) THEN
    INSERT INTO `Consortia_Task_Info` (`ConsortiaID`, `BeginTime`, `Contribution`, `Expirience`, `Offer`, `BuffID`, `Level`, `Riches`, `Time`, `ConditionData`, `RankTable`, `IsExist`) VALUES (p_ConsortiaID, p_BeginTime, p_Contribution, p_Expirience, p_Offer, p_BuffID, p_Level, p_Riches, p_Time, p_ConditionData, p_RankTable, 1);
  ELSE
    UPDATE `Consortia_Task_Info` SET `BeginTime` = p_BeginTime, `Contribution` = p_Contribution, `Expirience` = p_Expirience, `Offer` = p_Offer, `BuffID` = p_BuffID, `Level` = p_Level, `Riches` = p_Riches, `Time` = p_Time, `ConditionData` = p_ConditionData, `RankTable` = p_RankTable WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

