DROP PROCEDURE IF EXISTS `SP_Consortia_UpGrade`$$
CREATE PROCEDURE `SP_Consortia_UpGrade`(IN p_ConsortiaID INT, IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Level INT DEFAULT NULL;
  DECLARE v_Riches INT DEFAULT NULL;
  DECLARE v_NeedRiches INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_Reward INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `Level`, `Riches` INTO v_Level, v_Riches FROM `Consortia` WHERE `ConsortiaID` = p_ConsortiaID AND `ChairmanID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_Level IS NULL OR v_Level = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SET v_Level = v_Level + 1;
  SELECT `Riches`, `Count`, `Reward` INTO v_NeedRiches, v_Count, v_Reward FROM `Consortia_Level` WHERE `Level` = v_Level LIMIT 1;
  IF v_Count IS NULL OR v_Count = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  IF v_Riches < v_NeedRiches THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SET v_Riches = v_Riches + v_Reward - v_NeedRiches;
  UPDATE `Consortia` SET `Level` = v_Level, `MaxCount` = v_Count, `Riches` = v_Riches WHERE `ConsortiaID` = p_ConsortiaID AND `IsExist` = 1;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

