DROP PROCEDURE IF EXISTS `SP_Consortia_Update_FightPower`$$
CREATE PROCEDURE `SP_Consortia_Update_FightPower`(OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_FightPower INT DEFAULT NULL;
  DECLARE v_ConsortiaID INT DEFAULT NULL;
  DECLARE v__fetch_status INT DEFAULT 0;
  DECLARE `Employee_Cursor` CURSOR FOR SELECT `ConsortiaID` FROM `Consortia` WHERE `Count` > 1;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v__fetch_status = -1;
  SET p_ReturnValue = 0;
  OPEN `Employee_Cursor`;
  SET v__fetch_status = 0;
  FETCH `Employee_Cursor` INTO v_ConsortiaID;
  w1: WHILE v__fetch_status = 0 DO
    BEGIN DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN END; SELECT SUM(`FightPower`) INTO v_FightPower FROM `Sys_Users_Detail` WHERE `ConsortiaID` = v_ConsortiaID LIMIT 1; END;
    IF v_FightPower IS NOT NULL THEN
      UPDATE `Consortia` SET `FightPower` = v_FightPower WHERE `ConsortiaID` = v_ConsortiaID;
    END IF;
    SET v__fetch_status = 0;
    FETCH `Employee_Cursor` INTO v_ConsortiaID;
  END WHILE w1;
  CLOSE `Employee_Cursor`;
  SELECT * FROM `Consortia` ORDER BY `FightPower` DESC, `ConsortiaID` LIMIT 50;
END$$

