proc: BEGIN
  SET p_ReturnValue = 0;
  INSERT INTO `Marry_Apply` (`UserID`, `ApplyUserID`, `ApplyUserName`, `ApplyType`, `ApplyResult`, `LoveProclamation`) VALUES (p_UserID, p_ApplyUserID, p_ApplyUserName, p_ApplyType, p_ApplyResult, p_LoveProclamation);
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Insert_Marry_Notice`$$
CREATE PROCEDURE `SP_Insert_Marry_Notice`(IN p_UserID INT, IN p_ApplyUserID INT, IN p_ApplyUserName VARCHAR(50), IN p_ApplyType INT, IN p_ApplyResult TINYINT(1), IN p_LoveProclamation VARCHAR(300), IN p_AnswerId INT, INOUT p_ouototal INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Counts INT DEFAULT NULL;
  DECLARE v_tempUserName VARCHAR(50) DEFAULT NULL;
  SET p_ReturnValue = 0;
  IF p_ouototal IS NULL THEN SET p_ouototal = 0; END IF;
  SET p_ouototal = 0;
  IF (p_ApplyType = 2) THEN
    UPDATE `Marry_Apply` SET `isDeal` = 1, `isExist` = 0 WHERE `ApplyType` = 1 AND `isDeal` = 0 AND `ApplyUserID` = p_UserID AND `UserID` = p_ApplyUserID AND `Id` = p_AnswerId;
    SELECT COUNT(0) INTO v_Counts FROM `sys_users_detail` WHERE (`UserID` = p_UserID OR `UserID` = p_ApplyUserID) AND `IsMarried` = 0 LIMIT 1;
    IF (v_Counts <> 2) THEN
      IF (p_ApplyResult = 0) THEN
        INSERT INTO `Marry_Apply` (`UserID`, `ApplyUserID`, `ApplyUserName`, `ApplyType`, `ApplyResult`, `LoveProclamation`, `isDeal`, `isExist`) VALUES (p_UserID, p_ApplyUserID, p_ApplyUserName, p_ApplyType, p_ApplyResult, p_LoveProclamation, 0, 1);
        SELECT LAST_INSERT_ID() AS `identity`;
        SET p_ouototal = LAST_INSERT_ID();
      END IF;
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
    IF (p_ApplyResult = 1) THEN
      UPDATE `Sys_Users_Detail` SET `IsMarried` = 1, `SpouseID` = p_ApplyUserID, `SpouseName` = p_ApplyUserName WHERE `UserID` = p_UserID;
      SELECT `NickName` INTO v_tempUserName FROM `Sys_Users_Detail` WHERE `UserID` = p_UserID LIMIT 1;
      UPDATE `Sys_Users_Detail` SET `IsMarried` = 1, `SpouseID` = p_UserID, `SpouseName` = v_tempUserName WHERE `UserID` = p_ApplyUserID;
    END IF;
  END IF;
  IF (p_ApplyType = 3) THEN
    SELECT COUNT(0) INTO v_Counts FROM `sys_users_detail` WHERE (`UserID` = p_UserID OR `UserID` = p_ApplyUserID) AND `IsMarried` = 1 LIMIT 1;
    IF (v_Counts <> 2) THEN
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
    UPDATE `Sys_Users_Detail` SET `IsMarried` = 0, `SpouseID` = 0, `SpouseName` = '', `IsGotRing` = 0, `IsCreatedMarryRoom` = 0, `SelfMarryRoomID` = 0 WHERE `UserID` = p_UserID OR `UserID` = p_ApplyUserID;
  END IF;
  INSERT INTO `Marry_Apply` (`UserID`, `ApplyUserID`, `ApplyUserName`, `ApplyType`, `ApplyResult`, `LoveProclamation`, `isDeal`, `isExist`) VALUES (p_UserID, p_ApplyUserID, p_ApplyUserName, p_ApplyType, p_ApplyResult, p_LoveProclamation, 0, 1);
  SELECT LAST_INSERT_ID() AS `identity`;
  SET p_ouototal = LAST_INSERT_ID();
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Insert_Marry_Room_Info`$$
CREATE PROCEDURE `SP_Insert_Marry_Room_Info`(INOUT p_ID INT, IN p_Name VARCHAR(50), IN p_PlayerID INT, IN p_PlayerName VARCHAR(50), IN p_GroomID INT, IN p_GroomName VARCHAR(50), IN p_BrideID INT, IN p_BrideName VARCHAR(50), IN p_Pwd VARCHAR(15), IN p_AvailTime INT, IN p_MaxCount INT, IN p_GuestInvite TINYINT(1), IN p_MapIndex INT, IN p_BeginTime DATETIME(3), IN p_BreakTime DATETIME(3), IN p_RoomIntroduction VARCHAR(300), IN p_ServerID INT, IN p_IsHymeneal TINYINT(1), IN p_IsGunsaluteUsed TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_count FROM `Marry_Room_Info` WHERE `GroomID` = p_GroomID AND `BrideID` = p_BrideID AND `IsExist` = 1 LIMIT 1;
  IF v_count > 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Marry_Room_Info` (`Name`, `PlayerID`, `PlayerName`, `GroomID`, `GroomName`, `BrideID`, `BrideName`, `Pwd`, `AvailTime`, `MaxCount`, `GuestInvite`, `MapIndex`, `BeginTime`, `BreakTime`, `RoomIntroduction`, `ServerID`, `IsHymeneal`, `IsGunsaluteUsed`, `isExist`) VALUES (p_Name, p_PlayerID, p_PlayerName, p_GroomID, p_GroomName, p_BrideID, p_BrideName, p_Pwd, p_AvailTime, p_MaxCount, p_GuestInvite, p_MapIndex, p_BeginTime, p_BreakTime, p_RoomIntroduction, p_ServerID, p_IsHymeneal, p_IsGunsaluteUsed, 1);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SELECT LAST_INSERT_ID() AS `identity`;
  SET p_ID = LAST_INSERT_ID();
  UPDATE `sys_users_detail` SET `IsCreatedMarryRoom` = 1, `SelfMarryRoomID` = p_ID WHERE `UserID` = p_GroomID OR `UserID` = p_BrideID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Insert_Update_Server_Config`$$
CREATE PROCEDURE `SP_Insert_Update_Server_Config`(IN p_ID INT, IN p_Name VARCHAR(50), IN p_Value VARCHAR(2000), IN p_setUpdate INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count2 INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_count2 FROM `Server_Config` WHERE `ID` = p_ID LIMIT 1;
  IF (v_count2 <> 0 AND p_setUpdate = 0) THEN
    UPDATE `Server_Config` SET `ID` = p_ID, `Name` = p_Name, `Value` = p_Value WHERE `ID` = p_ID;
    SET p_ReturnValue = 1;
    LEAVE proc;
  ELSE
    INSERT INTO `Server_Config` (`ID`, `Name`, `Value`) VALUES (p_ID, p_Name, p_Value);
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
END$$

