DROP PROCEDURE IF EXISTS `SP_Mail_ByUserID`$$
CREATE PROCEDURE `SP_Mail_ByUserID`(IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT * FROM `User_Messages` WHERE `IsExist` = 1 AND `ReceiverID` = p_UserID AND TIMESTAMPDIFF(HOUR, DATE_FORMAT(`SendTime`, '%Y-%m-%d %H:00:00'), DATE_FORMAT(NOW(3), '%Y-%m-%d %H:00:00')) < `ValidDate` ORDER BY `SendDate`, `ID`;
END$$

DROP PROCEDURE IF EXISTS `SP_Mail_Delete`$$
CREATE PROCEDURE `SP_Mail_Delete`(IN p_ID INT, IN p_UserID INT, INOUT p_SenderID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Annex1 INT DEFAULT NULL;
  DECLARE v_Annex2 INT DEFAULT NULL;
  DECLARE v_Type INT DEFAULT NULL;
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(200) DEFAULT NULL;
  DECLARE v_Money INT DEFAULT NULL;
  DECLARE v_Annex3 INT DEFAULT NULL;
  DECLARE v_Annex4 INT DEFAULT NULL;
  DECLARE v_Annex5 INT DEFAULT NULL;
  DECLARE v_NewTitle VARCHAR(200) DEFAULT NULL;
  DECLARE v_NewContent VARCHAR(200) DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET p_SenderID = 0;
  SELECT `SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `money`, IFNULL(`Annex1`, CAST(0 AS CHAR)), IFNULL(`Annex2`, CAST(0 AS CHAR)), `Type`, IFNULL(`Annex3`, CAST(0 AS CHAR)), IFNULL(`Annex4`, CAST(0 AS CHAR)), IFNULL(`Annex5`, CAST(0 AS CHAR)) INTO p_SenderID, v_Sender, v_ReceiverID, v_Receiver, v_Title, v_Money, v_Annex1, v_Annex2, v_Type, v_Annex3, v_Annex4, v_Annex5 FROM `User_Messages` WHERE `ID` = p_ID AND `ReceiverID` = p_UserID AND `IsExist` = 1 LIMIT 1;
  IF v_Type IS NULL OR v_Type = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  IF v_Type < 100 OR v_Money = 0 THEN
    SET p_SenderID = 0;
    DELETE FROM `Sys_Users_Goods` WHERE `ItemID` IN (v_Annex1, v_Annex2, v_Annex3, v_Annex4, v_Annex5);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
  ELSE
    SET v_NewTitle = CONCAT(`GetTranslation`('SP_Mail_Delete.Msg1'), v_Title);
    SET v_NewContent = `GetTranslation`('SP_Mail_Delete.Msg2');
    SET v_NewContent = REPLACE(v_NewContent, '{0}', v_Receiver);
    SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', CAST(v_Annex1 AS CHAR(20)), ',Annex2:', CAST(v_Annex2 AS CHAR(20)), ',Annex3:', CAST(v_Annex3 AS CHAR(20)), ',Annex4:', CAST(v_Annex4 AS CHAR(20)), ',Annex5:', CAST(v_Annex5 AS CHAR(20)));
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_ReceiverID, v_Receiver, p_SenderID, v_Sender, v_NewTitle, v_NewContent, NOW(3), 0, 0, 0, 0, v_Annex1, v_Annex2, 0, 0, 1, 7, v_Remark, v_Annex3, v_Annex4, v_Annex5);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
  END IF;
  UPDATE `User_Messages` SET `IsExist` = 0, `SendTime` = NOW(3) WHERE `ID` = p_ID AND `ReceiverID` = p_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Mail_PaymentCancel`$$
CREATE PROCEDURE `SP_Mail_PaymentCancel`(IN p_userID INT, IN p_mailID INT, INOUT p_SenderID INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(1000) DEFAULT NULL;
  DECLARE v_Annex1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Type INT DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE v_money INT DEFAULT NULL;
  DECLARE v_Annex3 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex4 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex5 VARCHAR(100) DEFAULT NULL;
  DECLARE v_NewTitle VARCHAR(200) DEFAULT NULL;
  DECLARE v_NewContent VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT `SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Annex1`, `Annex2`, `Type`, `money`, `Annex3`, `Annex4`, `Annex5` INTO p_SenderID, v_Sender, v_ReceiverID, v_Receiver, v_Title, v_Annex1, v_Annex2, v_Type, v_money, v_Annex3, v_Annex4, v_Annex5 FROM `User_Messages` WHERE `ID` = p_mailID AND `ReceiverID` = p_userID AND `IsExist` = 1 LIMIT 1;
  IF v_Type IS NULL OR v_Type < 100 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF v_money = 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  SET v_NewTitle = CONCAT(`GetTranslation`('SP_Mail_PaymentCancel.Msg1'), v_Title);
  SET v_NewContent = `GetTranslation`('SP_Mail_PaymentCancel.Msg2');
  SET v_NewContent = REPLACE(v_NewContent, '{0}', v_Receiver);
  SET v_Remark = CONCAT('Gold:0,Money:0,Annex1:', v_Annex1, ',Annex2:', v_Annex2, ',Annex3:', v_Annex3, ',Annex4:', v_Annex4, ',Annex5:', v_Annex5);
  INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) VALUES (v_ReceiverID, v_Receiver, p_SenderID, v_Sender, v_NewTitle, v_NewContent, NOW(3), 0, 0, 0, 0, v_Annex1, v_Annex2, 0, 0, 1, 7, v_Remark, v_Annex3, v_Annex4, v_Annex5);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `User_Messages` SET `Annex1` = '', `Annex2` = '', `Annex3` = '', `Annex4` = '', `Annex5` = '', `IsExist` = 0 WHERE `ID` = p_mailID AND `ReceiverID` = p_userID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Mail_Scan`$$
CREATE PROCEDURE `SP_Mail_Scan`(INOUT p_NoticeUserID VARCHAR(4000), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_AuctionID INT DEFAULT NULL;
  DECLARE v_AuctioneerID INT DEFAULT NULL;
  DECLARE v_AuctioneerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_BuyerID INT DEFAULT NULL;
  DECLARE v_BuyerName VARCHAR(100) DEFAULT NULL;
  DECLARE v_ItemID INT DEFAULT NULL;
  DECLARE v_PayType INT DEFAULT NULL;
  DECLARE v_Price INT DEFAULT NULL;
  DECLARE v_Name VARCHAR(200) DEFAULT NULL;
  DECLARE v_MailID INT DEFAULT NULL;
  DECLARE v_SenderID INT DEFAULT NULL;
  DECLARE v_Sender VARCHAR(100) DEFAULT NULL;
  DECLARE v_ReceiverID INT DEFAULT NULL;
  DECLARE v_Receiver VARCHAR(100) DEFAULT NULL;
  DECLARE v_Title VARCHAR(1000) DEFAULT NULL;
  DECLARE v_Content VARCHAR(4000) DEFAULT NULL;
  DECLARE v_SendTime DATETIME(3) DEFAULT NULL;
  DECLARE v_IsRead TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelR TINYINT(1) DEFAULT NULL;
  DECLARE v_IfDelS TINYINT(1) DEFAULT NULL;
  DECLARE v_IsDelete TINYINT(1) DEFAULT NULL;
  DECLARE v_Annex1 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex2 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Gold INT DEFAULT NULL;
  DECLARE v_Money INT DEFAULT NULL;
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE v_Annex3 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex4 VARCHAR(100) DEFAULT NULL;
  DECLARE v_Annex5 VARCHAR(100) DEFAULT NULL;
  DECLARE v_NewTitle VARCHAR(200) DEFAULT NULL;
  DECLARE v_NewContent VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET p_NoticeUserID = '';
  SET v_SenderID = 0;
  SET v_Sender = `GetTranslation`('SP_Mail_Scan.Sender');
  SET v_ReceiverID = 0;
  SET v_Receiver = '';
  SET v_Title = `GetTranslation`('SP_Mail_Scan.Title');
  SET v_Content = `GetTranslation`('SP_Mail_Scan.Content');
  SET v_SendTime = NOW(3);
  SET v_IsRead = 0;
  SET v_IsDelR = 0;
  SET v_IfDelS = 0;
  SET v_IsDelete = 0;
  SET v_Annex1 = '';
  SET v_Annex2 = '';
  SET v_Gold = 0;
  SET v_Money = 0;
  SET v_Annex3 = '';
  SET v_Annex4 = '';
  SET v_Annex5 = '';
  IF 1 IS NOT NULL THEN
    DROP TEMPORARY TABLE IF EXISTS `tmp_PayMail`;
  END IF;
  CREATE TEMPORARY TABLE `tmp_PayMail` (`id` INT NULL AUTO_INCREMENT PRIMARY KEY, `MailID` INT NOT NULL, `SenderID` INT NOT NULL, `Sender` VARCHAR(200) NOT NULL, `ReceiverID` INT NOT NULL, `Receiver` VARCHAR(200) NOT NULL, `Title` VARCHAR(1000) NOT NULL, `Annex1` VARCHAR(100) NOT NULL, `Annex2` VARCHAR(100) NOT NULL, `Annex3` VARCHAR(100) NOT NULL, `Annex4` VARCHAR(100) NOT NULL, `Annex5` VARCHAR(100) NOT NULL);
  INSERT INTO `tmp_PayMail` (`MailID`, `SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Annex1`, `Annex2`, `Annex3`, `Annex4`, `Annex5`) SELECT `ID`, `SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, IFNULL(`Annex1`, ''), IFNULL(`Annex2`, ''), IFNULL(`Annex3`, ''), IFNULL(`Annex4`, ''), IFNULL(`Annex5`, '') FROM `User_Messages` WHERE `IsExist` = 1 AND `Type` > 100 AND TIMESTAMPDIFF(HOUR, DATE_FORMAT(`SendTime`, '%Y-%m-%d %H:00:00'), DATE_FORMAT(NOW(3), '%Y-%m-%d %H:00:00')) > `ValidDate` AND `Money` > 0;
  SET v_NewTitle = `GetTranslation`('SP_Mail_Scan.Msg1');
  SET v_NewContent = `GetTranslation`('SP_Mail_Scan.Msg2');
  START TRANSACTION;
  INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `Annex3`, `Annex4`, `Annex5`) SELECT `ReceiverID`, `Receiver`, `SenderID`, `Sender`, CONCAT(v_NewTitle, `Title`), REPLACE(v_NewContent, '{0}', `Receiver`), NOW(3), 0, 0, 0, 0, `Annex1`, `Annex2`, 0, 0, 1, 7, CONCAT('Gold:0,Money:0,Annex1:', `Annex1`, ',Annex2:', `Annex2`, ',Annex3:', `Annex3`, ',Annex4:', `Annex4`, ',Annex5:', `Annex5`), `Annex3`, `Annex4`, `Annex5` FROM `tmp_PayMail`;
  IF 0 <> 0 OR ROW_COUNT() = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SELECT CONCAT(p_NoticeUserID, IFNULL(GROUP_CONCAT(CONCAT(CAST(`SenderID` AS CHAR(50)), ',') SEPARATOR ''), '')) INTO p_NoticeUserID FROM `User_Messages` WHERE `ID` IN (SELECT `MailID` FROM `tmp_PayMail`);
UPDATE `User_Messages` SET `User_Messages`.`IsExist` = 0 WHERE `ID` IN (SELECT `MailID` FROM `tmp_PayMail`);
  IF 0 <> 0 OR ROW_COUNT() = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  COMMIT;
  IF CHAR_LENGTH(RTRIM(p_NoticeUserID)) > 0 THEN
    SET p_NoticeUserID = SUBSTRING(p_NoticeUserID, 1, CHAR_LENGTH(RTRIM(p_NoticeUserID)) - 1);
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

