DROP PROCEDURE IF EXISTS `SP_Mail_Send`$$
CREATE PROCEDURE `SP_Mail_Send`(INOUT p_ID INT, IN p_SenderID INT, IN p_Sender VARCHAR(100), IN p_ReceiverID INT, IN p_Receiver VARCHAR(100), IN p_Title VARCHAR(1000), IN p_Content VARCHAR(4000), IN p_SendTime DATETIME(3), IN p_IsRead TINYINT(1), IN p_IsDelR TINYINT(1), IN p_IfDelS TINYINT(1), IN p_IsDelete TINYINT(1), IN p_Annex1 VARCHAR(100), IN p_Annex2 VARCHAR(100), IN p_Gold INT, IN p_Money INT, IN p_IsExist TINYINT(1), IN p_Type INT, IN p_Annex1Name VARCHAR(100), IN p_Annex2Name VARCHAR(100), IN p_Annex3 VARCHAR(100), IN p_Annex4 VARCHAR(100), IN p_Annex5 VARCHAR(100), IN p_Annex3Name VARCHAR(100), IN p_Annex4Name VARCHAR(100), IN p_Annex5Name VARCHAR(100), IN p_ValidDate INT, IN p_AnnexRemark VARCHAR(200), IN p_GiftToken INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Remark VARCHAR(100) DEFAULT NULL;
  SET p_ReturnValue = 0;
  SET v_Remark = CONCAT('Gold:', CAST(p_Gold AS CHAR(20)), ',Money:', CAST(p_Money AS CHAR(20)), ',Annex1:', p_Annex1, ',Annex2:', p_Annex2, ',Annex3:', p_Annex3, ',Annex4:', p_Annex4, ',Annex5:', p_Annex5, ',GiftToken:', CAST(p_GiftToken AS CHAR(20)));
  IF p_Type > 100 THEN
    SET p_ValidDate = p_ValidDate;
  ELSE
    SET p_ValidDate = 10 * 24;
  END IF;
  INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `ValidDate`, `Annex1Name`, `Annex2Name`, `Annex3`, `Annex4`, `Annex5`, `Annex3Name`, `Annex4Name`, `Annex5Name`, `AnnexRemark`, `GiftToken`) VALUES (p_SenderID, p_Sender, p_ReceiverID, p_Receiver, p_Title, p_Content, p_SendTime, p_IsRead, p_IsDelR, p_IfDelS, p_IsDelete, p_Annex1, p_Annex2, p_Gold, p_Money, p_IsExist, p_Type, v_Remark, p_ValidDate, p_Annex1Name, p_Annex2Name, p_Annex3, p_Annex4, p_Annex5, p_Annex3Name, p_Annex4Name, p_Annex5Name, p_AnnexRemark, p_GiftToken);
  SELECT LAST_INSERT_ID() AS `identity`;
  SET p_ID = LAST_INSERT_ID();
END$$

DROP PROCEDURE IF EXISTS `SP_Mail_Single`$$
CREATE PROCEDURE `SP_Mail_Single`(IN p_ID INT, IN p_UserID INT, OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT * FROM `User_Messages` WHERE `ID` = p_ID AND `ReceiverID` = p_UserID AND `IsExist` = 1;
END$$

DROP PROCEDURE IF EXISTS `SP_Mail_Update`$$
CREATE PROCEDURE `SP_Mail_Update`(IN p_ID INT, IN p_SenderID INT, IN p_Sender VARCHAR(100), IN p_ReceiverID INT, IN p_Receiver VARCHAR(100), IN p_Title VARCHAR(1000), IN p_Content VARCHAR(4000), IN p_SendTime DATETIME(3), IN p_IsRead TINYINT(1), IN p_IsDelR TINYINT(1), IN p_IfDelS TINYINT(1), IN p_IsDelete TINYINT(1), IN p_Annex1 VARCHAR(100), IN p_Annex2 VARCHAR(100), IN p_Gold INT, IN p_Money INT, IN p_IsExist TINYINT(1), IN p_Type INT, IN p_OldMoney INT, IN p_ValidDate INT, IN p_Annex1Name VARCHAR(100), IN p_Annex2Name VARCHAR(100), IN p_Annex3 VARCHAR(100), IN p_Annex4 VARCHAR(100), IN p_Annex5 VARCHAR(100), IN p_Annex3Name VARCHAR(100), IN p_Annex4Name VARCHAR(100), IN p_Annex5Name VARCHAR(100), IN p_GiftToken INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Remark VARCHAR(200) DEFAULT NULL;
  DECLARE v_NewTitle VARCHAR(200) DEFAULT NULL;
  DECLARE v_NewContent VARCHAR(200) DEFAULT NULL;
  DECLARE v_AnnexRemark VARCHAR(200) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  START TRANSACTION;
  IF p_Type > 100 AND p_Money <> p_OldMoney THEN
    SET p_ValidDate = 72;
    SET v_NewTitle = CONCAT(`GetTranslation`('SP_Mail_Update.Msg1'), p_Title);
    IF p_Annex2Name IS NOT NULL AND p_Annex2Name <> '' THEN
      IF p_Annex1Name IS NOT NULL AND p_Annex1Name <> '' THEN
        SET p_Annex1Name = CONCAT(p_Annex1Name, ',');
      END IF;
      SET p_Annex1Name = CONCAT(p_Annex1Name, p_Annex2Name);
    END IF;
    IF p_Annex3Name IS NOT NULL AND p_Annex3Name <> '' THEN
      IF p_Annex1Name IS NOT NULL AND p_Annex1Name <> '' THEN
        SET p_Annex1Name = CONCAT(p_Annex1Name, ',');
      END IF;
      SET p_Annex1Name = CONCAT(p_Annex1Name, p_Annex3Name);
    END IF;
    IF p_Annex4Name IS NOT NULL AND p_Annex4Name <> '' THEN
      IF p_Annex1Name IS NOT NULL AND p_Annex1Name <> '' THEN
        SET p_Annex1Name = CONCAT(p_Annex1Name, ',');
      END IF;
      SET p_Annex1Name = CONCAT(p_Annex1Name, p_Annex4Name);
    END IF;
    IF p_Annex5Name IS NOT NULL AND p_Annex5Name <> '' THEN
      IF p_Annex1Name IS NOT NULL AND p_Annex1Name <> '' THEN
        SET p_Annex1Name = CONCAT(p_Annex1Name, ',');
      END IF;
      SET p_Annex1Name = CONCAT(p_Annex1Name, p_Annex5Name);
    END IF;
    SET v_NewContent = `GetTranslation`('SP_Mail_Update.Msg2');
    SET v_NewContent = REPLACE(v_NewContent, '{0}', p_Receiver);
    SET v_NewContent = REPLACE(v_NewContent, '{1}', p_Annex1Name);
    SET v_NewContent = REPLACE(v_NewContent, '{2}', CAST(CAST(ROUND(p_OldMoney * 0.9, 0) AS SIGNED) AS CHAR(20)));
    SET v_Remark = CONCAT('Gold:0,Money:', CAST(CAST(ROUND(p_OldMoney * 0.9, 0) AS SIGNED) AS CHAR(20)), ',Annex1:,Annex2:,Annex3:,Annex4:,Annex5:GiftToken:0');
    SET v_AnnexRemark = `GetTranslation`('SP_Mail_Update.Msg3');
    SET v_AnnexRemark = REPLACE(v_AnnexRemark, '{0}', CAST(p_OldMoney * 0.9 AS CHAR(20)));
    INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `AnnexRemark`) VALUES (p_ReceiverID, p_Receiver, p_SenderID, p_Sender, v_NewTitle, v_NewContent, NOW(3), 0, 0, 0, 0, '', '', 0, p_OldMoney * 0.9, 1, 6, v_Remark, v_AnnexRemark);
    IF 0 <> 0 THEN
      ROLLBACK;
      SET p_ReturnValue = 0;
      LEAVE proc;
    END IF;
  END IF;
  UPDATE `User_Messages` SET `SenderID` = p_SenderID, `Sender` = p_Sender, `ReceiverID` = p_ReceiverID, `Receiver` = p_Receiver, `Title` = p_Title, `Content` = p_Content, `SendTime` = p_SendTime, `IsRead` = p_IsRead, `IsDelR` = p_IsDelR, `IfDelS` = p_IfDelS, `IsDelete` = p_IsDelete, `Annex1` = p_Annex1, `Annex2` = p_Annex2, `Gold` = p_Gold, `Money` = p_Money, `IsExist` = p_IsExist, `ValidDate` = p_ValidDate, `Annex3` = p_Annex3, `Annex4` = p_Annex4, `Annex5` = p_Annex5, `GiftToken` = p_GiftToken WHERE `ID` = p_ID AND `ReceiverID` = p_ReceiverID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

