DROP PROCEDURE IF EXISTS `SP_QuestData_Add`$$
CREATE PROCEDURE `SP_QuestData_Add`(IN p_UserId INT, IN p_QuestID INT, IN p_CompletedDate DATETIME(3), IN p_IsComplete TINYINT(1), IN p_Condition1 INT, IN p_Condition2 INT, IN p_Condition3 INT, IN p_Condition4 INT, IN p_IsExist TINYINT(1), IN p_RepeatFinish INT, IN p_RandDobule INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_temp INT DEFAULT NULL;
  DECLARE v_tempComplete TINYINT(1) DEFAULT NULL;
  DECLARE v_canRepeat TINYINT(1) DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_temp FROM `QuestData` WHERE `UserId` = p_UserId AND `QuestID` = p_QuestID LIMIT 1;
  IF v_temp = 0 THEN
    INSERT INTO `QuestData` (`UserId`, `QuestID`, `CompletedDate`, `IsComplete`, `Condition1`, `Condition2`, `Condition3`, `Condition4`, `IsExist`, `RepeatFinish`, `RandDobule`) VALUES (p_UserId, p_QuestID, p_CompletedDate, p_IsComplete, p_Condition1, p_Condition2, p_Condition3, p_Condition4, p_IsExist, p_RepeatFinish, p_RandDobule);
  ELSE
    SELECT `IsComplete` INTO v_tempComplete FROM `QuestData` WHERE `UserId` = p_UserId AND `QuestID` = p_QuestID LIMIT 1;
    SELECT `CanRepeat` INTO v_canRepeat FROM `Project_Game34`.`Quest` WHERE `ID` = p_QuestID LIMIT 1;
    IF v_tempComplete = 0 OR v_canRepeat = 1 THEN
      UPDATE `QuestData` SET `CompletedDate` = p_CompletedDate, `IsComplete` = p_IsComplete, `Condition1` = p_Condition1, `Condition2` = p_Condition2, `Condition3` = p_Condition3, `Condition4` = p_Condition4, `IsExist` = p_IsExist, `RepeatFinish` = p_RepeatFinish, `RandDobule` = p_RandDobule WHERE `UserId` = p_UserId AND `QuestID` = p_QuestID;
    END IF;
  END IF;
END$$

