DROP PROCEDURE IF EXISTS `SP_ReturnItem`$$
CREATE PROCEDURE `SP_ReturnItem`(OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  START TRANSACTION;
  INSERT INTO `User_Messages` (`SenderID`, `Sender`, `ReceiverID`, `Receiver`, `Title`, `Content`, `SendTime`, `IsRead`, `IsDelR`, `IfDelS`, `IsDelete`, `Annex1`, `Annex2`, `Gold`, `Money`, `IsExist`, `Type`, `Remark`, `ValidDate`, `Annex1Name`, `Annex2Name`, `Annex3`, `Annex4`, `Annex5`, `Annex3Name`, `Annex4Name`, `Annex5Name`, `AnnexRemark`) SELECT 0, '系统管理员', `UserID`, '', '物品返回', '物品返回', NOW(3), 0, 0, 0, 0, `ItemID`, '', 0, 0, 1, 51, CONCAT('Gold:0,Money:0,Annex1:', CAST(`ItemID` AS CHAR(20)), ',Annex2:,Annex3:,Annex4:,Annex5:'), 10, '', '', '', '', '', '', '', '', '' FROM `Sys_users_Goods` WHERE `BagType` = 0 AND `place` >= 80;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_users_Goods` SET `place` = -1 WHERE `BagType` = 0 AND `place` >= 80;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SELECT 'finish';
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

