DROP PROCEDURE IF EXISTS `SP_Sys_Clear_Messages`$$
CREATE PROCEDURE `SP_Sys_Clear_Messages`(OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_date DATETIME(3) DEFAULT NULL;
  SET p_ReturnValue = 0;
  SET v_date = DATE_ADD(NOW(3), INTERVAL -20 DAY);
  SELECT v_date;
  DELETE FROM `Sys_Users_Goods` WHERE `ItemID` IN (SELECT CAST(`Annex1` AS SIGNED) FROM `User_Messages` WHERE `SendTime` < v_date AND (`Type` < 100 OR `Money` = 0));
  DELETE FROM `Sys_Users_Goods` WHERE `ItemID` IN (SELECT CAST(`Annex2` AS SIGNED) FROM `User_Messages` WHERE `SendTime` < v_date AND (`Type` < 100 OR `Money` = 0));
  DELETE FROM `User_Messages` WHERE `SendTime` < v_date;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

