DROP PROCEDURE IF EXISTS `SP_Sys_Update_BestEquip`$$
CREATE PROCEDURE `SP_Sys_Update_BestEquip`(OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  SELECT `Sys_Users_Detail`.`UserName`, `Sys_Users_Detail`.`NickName`, `Sys_Users_Detail`.`Grade`, `Sys_Users_Detail`.`Sex`, `Sys_Users_Detail`.`GP`, `Shop_Goods`.`Name`, `Sys_Users_Goods`.`Strengthenlevel`, `Sys_Users_Goods`.`RemoveDate` FROM `Sys_Users_Goods` LEFT JOIN `Sys_Users_Detail` ON `Sys_Users_Goods`.`UserID` = `Sys_Users_Detail`.`UserID` LEFT JOIN `Project_Game34`.`Shop_Goods` ON `Sys_Users_Goods`.`TemplateID` = `Shop_Goods`.`TemplateID` WHERE `Sys_Users_Goods`.`UserID` > 0 AND `Sys_Users_Goods`.`TemplateID` IN (7015, 7016, 7017, 7018, 7019, 7020, 7021, 7022, 7023) AND LEFT(DATE_FORMAT(DATE_ADD(`RemoveDate`, INTERVAL 1 DAY), '%m/%d/%Y'), 20) = LEFT(DATE_FORMAT(NOW(3), '%m/%d/%Y'), 20);
END$$

