DROP PROCEDURE IF EXISTS `SP_UpdateNewChickenBox`$$
CREATE PROCEDURE `SP_UpdateNewChickenBox`(IN p_ID INT, IN p_UserID INT, IN p_TemplateID INT, IN p_Count INT, IN p_ValidDate INT, IN p_StrengthenLevel INT, IN p_AttackCompose INT, IN p_DefendCompose INT, IN p_AgilityCompose INT, IN p_LuckCompose INT, IN p_Position INT, IN p_IsSelected TINYINT(1), IN p_IsSeeded TINYINT(1), IN p_IsBinds TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  IF p_Position = -1 THEN
    DELETE FROM `New_ChickenBox_Data` WHERE `ID` = p_ID AND `UserID` = p_UserID;
  ELSE
    UPDATE `New_ChickenBox_Data` SET `TemplateID` = p_TemplateID, `Count` = p_Count, `ValidDate` = p_ValidDate, `StrengthenLevel` = p_StrengthenLevel, `AttackCompose` = p_AttackCompose, `DefendCompose` = p_DefendCompose, `AgilityCompose` = p_AgilityCompose, `LuckCompose` = p_LuckCompose, `Position` = p_Position, `IsSelected` = p_IsSelected, `IsSeeded` = p_IsSeeded, `IsBinds` = p_IsBinds WHERE `ID` = p_ID AND `UserID` = p_UserID;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

