DROP PROCEDURE IF EXISTS `SP_UpdateUsersEventProcess`$$
CREATE PROCEDURE `SP_UpdateUsersEventProcess`(IN p_UserID INT, IN p_ActiveType INT, IN p_Conditions INT, IN p_AwardGot INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT COUNT(`UserID`) INTO v_count FROM `Sys_Users_EventProcess` WHERE `UserID` = p_UserID AND `ActiveType` = p_ActiveType LIMIT 1;
  IF v_count <> 0 THEN
    UPDATE `Sys_Users_EventProcess` SET `Conditions` = p_Conditions, `AwardGot` = p_AwardGot WHERE `UserID` = p_UserID AND `ActiveType` = p_ActiveType;
  ELSE
    INSERT INTO `Sys_Users_EventProcess` (`UserID`, `ActiveType`, `Conditions`, `AwardGot`) VALUES (p_UserID, p_ActiveType, p_Conditions, p_AwardGot);
  END IF;
  IF 0 <> 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

