DROP PROCEDURE IF EXISTS `SP_Update_Marry_Room_Info`$$
CREATE PROCEDURE `SP_Update_Marry_Room_Info`(IN p_ID INT, IN p_AvailTime INT, IN p_BreakTime DATETIME(3), IN p_roomIntroduction VARCHAR(300), IN p_isHymeneal TINYINT(1), IN p_Name VARCHAR(50), IN p_Pwd VARCHAR(15), IN p_IsGunsaluteUsed TINYINT(1), OUT p_ReturnValue INT)
