DROP PROCEDURE IF EXISTS `SP_Update_Repute_FightPower`$$
CREATE PROCEDURE `SP_Update_Repute_FightPower`(OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Repute INT DEFAULT NULL;
  DECLARE v_UserID INT DEFAULT NULL;
  DECLARE v__fetch_status INT DEFAULT 0;
  DECLARE `Employee_Cursor` CURSOR FOR SELECT `UserID` FROM `Sys_Users_Detail` WHERE `FightPower` > 0 ORDER BY `FightPower` DESC, `UserID`;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v__fetch_status = -1;
  SET p_ReturnValue = 0;
  OPEN `Employee_Cursor`;
  SET v__fetch_status = 0;
  FETCH `Employee_Cursor` INTO v_UserID;
  SET v_Repute = 1;
  w1: WHILE v__fetch_status = 0 DO
    IF (v_Repute = 1) THEN
      UPDATE `Sys_Users_Detail` SET `Repute` = v_Repute WHERE `UserID` = v_UserID;
    ELSE
      UPDATE `Sys_Users_Detail` SET `Repute` = v_Repute WHERE `UserID` = v_UserID;
    END IF;
    SET v_Repute = v_Repute + 1;
    SET v__fetch_status = 0;
    FETCH `Employee_Cursor` INTO v_UserID;
  END WHILE w1;
  CLOSE `Employee_Cursor`;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

