proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_count FROM `Sys_Users_Texp` WHERE `UserID` = p_UserID LIMIT 1;
  IF v_count > 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Sys_Users_Texp` (`UserID`, `spdTexpExp`, `attTexpExp`, `defTexpExp`, `hpTexpExp`, `lukTexpExp`, `texpTaskCount`, `texpCount`, `texpTaskDate`) VALUES (p_UserID, p_spdTexpExp, p_attTexpExp, p_defTexpExp, p_hpTexpExp, p_lukTexpExp, p_texpTaskCount, p_texpCount, p_texpTaskDate);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

