  WITH `OrderedOrders` AS (SELECT `FightPower`, `UserID`, ROW_NUMBER() OVER (ORDER BY `FightPower` DESC) AS `RowNumber` FROM `Sys_Users_Detail`) SELECT `FightPower`, `RowNumber` FROM `OrderedOrders` WHERE `UserID` = p_UserID;
END$$

