DROP PROCEDURE IF EXISTS `SP_Users_Active`$$
CREATE PROCEDURE `SP_Users_Active`(INOUT p_UserID INT, IN p_Attack INT, IN p_Colors VARCHAR(200), IN p_ConsortiaID INT, IN p_Defence INT, IN p_Gold INT, IN p_GP INT, IN p_Grade INT, IN p_Luck INT, IN p_Money INT, IN p_Style VARCHAR(200), IN p_Agility INT, IN p_State INT, IN p_UserName VARCHAR(200), IN p_PassWord VARCHAR(200), IN p_Sex TINYINT(1), IN p_Hide INT, IN p_ActiveIP VARCHAR(50), IN p_Skin VARCHAR(500), IN p_Site VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET p_GP = 1;
  SET p_Grade = 1;
  SELECT IFNULL(COUNT(*), 0) INTO v_count FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Sys_Users_Detail` (`UserName`, `PassWord`, `NickName`, `Date`, `IsConsortia`, `ConsortiaID`, `Sex`, `Win`, `Total`, `Escape`, `GP`, `Honor`, `Gold`, `Money`, `Style`, `Colors`, `Hide`, `LastDate`, `Grade`, `State`, `IsFirst`, `Repute`, `ActiveIP`, `IsExist`, `Skin`, `Site`) VALUES (p_UserName, p_PassWord, '', NOW(3), 0, 0, p_Sex, 0, 0, 0, p_GP, '', 0, 0, p_Style, p_Colors, p_Hide, NOW(3), p_Grade, p_State, 0, 0, p_ActiveIP, 1, p_Skin, p_Site);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SET p_UserID = IFNULL(LAST_INSERT_ID(), 0);
  IF p_UserID = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_Users_Fight` (`UserID`, `Attack`, `Defence`, `Luck`, `Agility`, `Delay`, `Honor`, `Map`, `Directory`, `IsExist`) VALUES (p_UserID, p_Attack, p_Defence, p_Luck, p_Agility, 0, '', '', '', 1);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_VIP_Info` (`UserID`) VALUES (p_UserID);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_Users_Texp` (`UserID`) VALUES (p_UserID);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `DailyLogList` (`UserID`) VALUES (p_UserID);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

