DROP PROCEDURE IF EXISTS `SP_Users_Farm_Add`$$
CREATE PROCEDURE `SP_Users_Farm_Add`(IN p_FarmID INT, IN p_PayFieldMoney VARCHAR(50), IN p_PayAutoMoney VARCHAR(50), IN p_AutoPayTime DATETIME(3), IN p_AutoValidDate INT, IN p_VipLimitLevel INT, IN p_FarmerName VARCHAR(50), IN p_GainFieldId INT, IN p_MatureId INT, IN p_KillCropId INT, IN p_isAutoId INT, IN p_isFarmHelper TINYINT(1), INOUT p_ID INT, IN p_buyExpRemainNum INT, IN p_isArrange TINYINT(1), IN p_TreeLevel INT, IN p_TreeExp INT, IN p_LoveScore INT, IN p_MonsterExp INT, IN p_PoultryState INT, IN p_CountDownTime DATETIME(3), IN p_TreeCostExp INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_count FROM `Sys_User_Farm` WHERE `FarmID` = p_FarmID LIMIT 1;
  IF (v_count = 0) THEN
    INSERT INTO `Sys_User_Farm` (`FarmID`, `PayFieldMoney`, `PayAutoMoney`, `AutoPayTime`, `AutoValidDate`, `VipLimitLevel`, `FarmerName`, `GainFieldId`, `MatureId`, `KillCropId`, `isAutoId`, `isFarmHelper`, `buyExpRemainNum`, `isArrange`, `TreeLevel`, `TreeExp`, `LoveScore`, `MonsterExp`, `PoultryState`, `CountDownTime`, `TreeCostExp`) VALUES (p_FarmID, p_PayFieldMoney, p_PayAutoMoney, p_AutoPayTime, p_AutoValidDate, p_VipLimitLevel, p_FarmerName, p_GainFieldId, p_MatureId, p_KillCropId, p_isAutoId, p_isFarmHelper, p_buyExpRemainNum, p_isArrange, p_TreeLevel, p_TreeExp, p_LoveScore, p_MonsterExp, p_PoultryState, p_CountDownTime, p_TreeCostExp);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ID = LAST_INSERT_ID();
    IF (0 <> 0) THEN
      SET p_ReturnValue = 1;
      LEAVE proc;
    END IF;
  ELSE
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
END$$

