DROP PROCEDURE IF EXISTS `SP_Users_FriendsBbs`$$
CREATE PROCEDURE `SP_Users_FriendsBbs`(IN p_SearchUserName VARCHAR(4000), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  CREATE TEMPORARY TABLE `tmp_TempUser` (`UserName` VARCHAR(100) NULL);
  INSERT INTO `tmp_TempUser` SELECT `Value` FROM JSON_TABLE(CONCAT('["', REPLACE(REPLACE(REPLACE(p_SearchUserName, '\\', '\\\\'), '"', '\\"'), ',', '","'), '"]'), '$[*]' COLUMNS (`id` FOR ORDINALITY, `value` VARCHAR(50) PATH '$')) AS `split`;
  SELECT `A`.`UserName`, IFNULL(`B`.`UserId`, 0) AS `UserId`, `B`.`NickName` FROM `tmp_TempUser` AS `A` LEFT JOIN `Sys_Users_Detail` AS `B` ON `A`.`UserName` = `B`.`UserName`;
  DROP TEMPORARY TABLE IF EXISTS `tmp_TempUser`;
END$$

DROP PROCEDURE IF EXISTS `SP_Users_Friends_Add`$$
CREATE PROCEDURE `SP_Users_Friends_Add`(INOUT p_ID INT, IN p_UserID INT, IN p_FriendID INT, IN p_AddDate DATETIME(3), IN p_Remark VARCHAR(400), IN p_IsExist TINYINT(1), IN p_Relation INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_temp INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT COUNT(*) INTO v_temp FROM `Sys_Users_Friends` WHERE `UserID` = p_UserID AND `FriendID` = p_FriendID LIMIT 1;
  IF v_temp = 0 THEN
    INSERT INTO `Sys_Users_Friends` (`UserID`, `FriendID`, `AddDate`, `Remark`, `IsExist`, `Relation`) VALUES (p_UserID, p_FriendID, p_AddDate, p_Remark, p_IsExist, p_Relation);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ID = LAST_INSERT_ID();
  ELSE
    UPDATE `Sys_Users_Friends` SET `IsExist` = 1, `Remark` = p_Remark, `AddDate` = p_AddDate, `Relation` = p_Relation WHERE `UserID` = p_UserID AND `FriendID` = p_FriendID;
  END IF;
END$$

