DROP PROCEDURE IF EXISTS `SP_Users_Friends_Good`$$
CREATE PROCEDURE `SP_Users_Friends_Good`(IN p_UserName VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_UserId INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SET v_UserId = 0;
  SELECT IFNULL(`UserID`, 0) INTO v_UserId FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  IF v_UserId > 0 THEN
    SELECT `B`.`UserName` FROM `Sys_Users_Friends` AS `A` LEFT JOIN `Sys_Users_Detail` AS `B` ON `A`.`FriendID` = `B`.`UserID` WHERE `A`.`UserID` = v_UserId AND `A`.`IsExist` = 1 AND `B`.`UserName` <> '';
  END IF;
END$$

