  IF v_temp = 0 THEN
    INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `Skin`, `IsUsed`, `RemoveType`, `Hole1`, `Hole2`, `Hole3`, `Hole4`, `Hole5`, `Hole6`, `StrengthenTimes`, `Hole5Level`, `Hole5Exp`, `Hole6Level`, `Hole6Exp`, `IsGold`, `goldBeginTime`, `goldValidDate`, `StrengthenExp`, `Blood`, `latentEnergyCurStr`, `latentEnergyNewStr`, `latentEnergyEndTime`, `curExp`, `cellLocked`) VALUES (p_UserID, p_BagType, p_TemplateID, p_Place, p_Count, p_IsJudge, p_Color, p_IsExist, p_StrengthenLevel, p_AttackCompose, p_DefendCompose, p_LuckCompose, p_AgilityCompose, p_IsBinds, p_BeginDate, p_ValidDate, p_Skin, p_IsUsed, p_RemoveType, p_Hole1, p_Hole2, p_Hole3, p_Hole4, p_Hole5, p_Hole6, p_StrengthenTimes, p_Hole5Level, p_Hole5Exp, p_Hole6Level, p_Hole6Exp, p_IsGold, p_goldBeginTime, p_goldValidDate, p_StrengthenExp, p_Blood, p_latentEnergyCurStr, p_latentEnergyNewStr, p_latentEnergyEndTime, p_curExp, p_cellLocked);
    SELECT LAST_INSERT_ID() AS `identity`;
    SET p_ItemID = LAST_INSERT_ID();
