DROP PROCEDURE IF EXISTS `SP_Users_Items_Update`$$
CREATE PROCEDURE `SP_Users_Items_Update`(IN p_ItemID INT, IN p_UserID INT, IN p_TemplateID INT, IN p_Place INT, IN p_Count INT, IN p_IsJudge TINYINT(1), IN p_Color VARCHAR(100), IN p_IsExist TINYINT(1), IN p_StrengthenLevel INT, IN p_AttackCompose INT, IN p_DefendCompose INT, IN p_LuckCompose INT, IN p_AgilityCompose INT, IN p_IsBinds TINYINT(1), IN p_BeginDate DATETIME(3), IN p_ValidDate INT, IN p_BagType INT, IN p_Skin VARCHAR(50), IN p_IsUsed TINYINT(1), IN p_RemoveDate DATETIME(3), IN p_RemoveType INT, IN p_Hole1 INT, IN p_Hole2 INT, IN p_Hole3 INT, IN p_Hole4 INT, IN p_Hole5 INT, IN p_Hole6 INT, IN p_StrengthenTimes INT, IN p_Hole5Level INT, IN p_Hole5Exp INT, IN p_Hole6Level INT, IN p_Hole6Exp INT, IN p_IsGold TINYINT(1), IN p_goldBeginTime DATETIME(3), IN p_goldValidDate INT, IN p_StrengthenExp INT, IN p_Blood INT, IN p_latentEnergyCurStr VARCHAR(50), IN p_latentEnergyNewStr VARCHAR(50), IN p_latentEnergyEndTime DATETIME(3), IN p_curExp INT, IN p_cellLocked TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  IF (p_BagType = -1 AND p_Place = -1 AND p_IsExist = 0) THEN
    DELETE FROM `Sys_Users_Goods` WHERE `ItemID` = p_ItemID;
  ELSE
    UPDATE `Sys_Users_Goods` SET `UserID` = p_UserID, `BagType` = p_BagType, `TemplateID` = p_TemplateID, `Place` = p_Place, `Count` = p_Count, `IsJudge` = p_IsJudge, `Color` = p_Color, `IsExist` = p_IsExist, `StrengthenLevel` = p_StrengthenLevel, `AttackCompose` = p_AttackCompose, `DefendCompose` = p_DefendCompose, `LuckCompose` = p_LuckCompose, `AgilityCompose` = p_AgilityCompose, `IsBinds` = p_IsBinds, `BeginDate` = p_BeginDate, `ValidDate` = p_ValidDate, `Skin` = p_Skin, `IsUsed` = p_IsUsed, `RemoveDate` = p_RemoveDate, `RemoveType` = p_RemoveType, `Hole1` = p_Hole1, `Hole2` = p_Hole2, `Hole3` = p_Hole3, `Hole4` = p_Hole4, `Hole5` = p_Hole5, `Hole6` = p_Hole6, `StrengthenTimes` = p_StrengthenTimes, `Hole5Level` = p_Hole5Level, `Hole5Exp` = p_Hole5Exp, `Hole6Level` = p_Hole6Level, `Hole6Exp` = p_Hole6Exp, `IsGold` = p_IsGold, `goldBeginTime` = p_goldBeginTime, `goldValidDate` = p_goldValidDate, `StrengthenExp` = p_StrengthenExp, `Blood` = p_Blood, `latentEnergyCurStr` = p_latentEnergyCurStr, `latentEnergyNewStr` = p_latentEnergyNewStr, `latentEnergyEndTime` = p_latentEnergyEndTime, `curExp` = IFNULL(p_curExp, `curExp`), `cellLocked` = IFNULL(p_cellLocked, `cellLocked`) WHERE `ItemID` = p_ItemID;
  END IF;
END$$

