DROP PROCEDURE IF EXISTS `SP_Users_LoginWeb`$$
CREATE PROCEDURE `SP_Users_LoginWeb`(IN p_UserName VARCHAR(200), IN p_PassWord VARCHAR(200), IN p_FirstValidate TINYINT(1), IN p_NickName VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_forbidDate DATETIME(3) DEFAULT NULL;
  DECLARE v_isExist TINYINT(1) DEFAULT NULL;
  DECLARE v_lastDate DATETIME(3) DEFAULT NULL;
  DECLARE v_lastDateSecond DATETIME(3) DEFAULT NULL;
  DECLARE v_lastDateThird DATETIME(3) DEFAULT NULL;
  DECLARE v_loginCount INT DEFAULT NULL;
  DECLARE v_isFirst INT DEFAULT NULL;
  DECLARE v_DayLoginCount INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `ForbidDate`, `IsExist`, `LastDate`, `LoginCount`, `LastDateSecond`, `LastDateThird`, `IsFirst`, `DayLoginCount` INTO v_forbidDate, v_isExist, v_lastDate, v_loginCount, v_lastDateSecond, v_lastDateThird, v_isFirst, v_DayLoginCount FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName AND `NickName` = p_NickName LIMIT 1;
  IF MONTH(v_lastDate) = MONTH(NOW(3)) THEN
    IF DAY(v_lastDate) <> DAY(NOW(3)) THEN
      SET v_loginCount = v_loginCount + 1;
      SET v_DayLoginCount = 0;
    ELSE
      SET v_lastDate = v_lastDateSecond;
      SET v_lastDateSecond = v_lastDateThird;
    END IF;
  ELSE
    SET v_loginCount = 1;
    SET v_DayLoginCount = 0;
  END IF;
  IF v_isFirst = 1 THEN
    SET v_DayLoginCount = 1;
  END IF;
  IF v_isFirst > 0 THEN
    SET v_isFirst = v_isFirst + 1;
  END IF;
  IF v_isExist = 0 THEN
    IF TIMESTAMPDIFF(SECOND, DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s'), DATE_FORMAT(v_forbidDate, '%Y-%m-%d %H:%i:%s')) < 0 THEN
      UPDATE `Sys_Users_Detail` SET `PassWord` = p_PassWord, `LastDate` = NOW(3), `IsExist` = 1, `LastDateSecond` = v_lastDate, `LastDateThird` = v_lastDateSecond, `LoginCount` = v_loginCount, `IsFirst` = v_isFirst, `DayLoginCount` = v_DayLoginCount WHERE `UserName` = p_UserName AND `NickName` = p_NickName;
    END IF;
  ELSE
    UPDATE `Sys_Users_Detail` SET `PassWord` = p_PassWord, `LastDate` = NOW(3), `LastDateSecond` = v_lastDate, `LastDateThird` = v_lastDateSecond, `LoginCount` = v_loginCount, `IsFirst` = v_isFirst, `DayLoginCount` = v_DayLoginCount WHERE `UserName` = p_UserName AND `NickName` = p_NickName;
  END IF;
  IF 0 <> 0 THEN
    SET p_ReturnValue = NULL;
    LEAVE proc;
  END IF;
  SELECT * FROM `V_Sys_Users_Detail` WHERE `UserName` = p_UserName AND `NickName` = p_NickName;
END$$

