DROP PROCEDURE IF EXISTS `SP_Users_Register`$$
CREATE PROCEDURE `SP_Users_Register`(IN p_UserName VARCHAR(200), IN p_PassWord VARCHAR(200), IN p_NickName VARCHAR(50), IN p_BArmID INT, IN p_BHairID INT, IN p_BFaceID INT, IN p_BClothID INT, IN p_GArmID INT, IN p_GHairID INT, IN p_GFaceID INT, IN p_GClothID INT, IN p_ArmColor VARCHAR(50), IN p_HairColor VARCHAR(50), IN p_FaceColor VARCHAR(50), IN p_ClothColor VARCHAR(50), IN p_Sex INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_ArmID INT DEFAULT NULL;
  DECLARE v_HairID INT DEFAULT NULL;
  DECLARE v_FaceID INT DEFAULT NULL;
  DECLARE v_ClothID INT DEFAULT NULL;
  DECLARE v_isFirst TINYINT(1) DEFAULT NULL;
  DECLARE v_UserID INT DEFAULT NULL;
  DECLARE v_CategoryID INT DEFAULT NULL;
  DECLARE v_Attack INT DEFAULT NULL;
  DECLARE v_Defence INT DEFAULT NULL;
  DECLARE v_Agility INT DEFAULT NULL;
  DECLARE v_Luck INT DEFAULT NULL;
  DECLARE v_style VARCHAR(1000) DEFAULT NULL;
  DECLARE v_color VARCHAR(1000) DEFAULT NULL;
  DECLARE v_count INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_count FROM `Sys_Users_Detail` WHERE `NickName` = p_NickName LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_Sex = -1 THEN
    SELECT `IsFirst`, `UserID`, `Sex` INTO v_isFirst, v_UserID, p_Sex FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName AND `PassWord` = p_PassWord LIMIT 1;
  ELSE
    SELECT `IsFirst`, `UserID` INTO v_isFirst, v_UserID FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName AND `PassWord` = p_PassWord LIMIT 1;
  END IF;
  IF IFNULL(v_isFirst, 0) <> 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  IF p_Sex <> 0 THEN
    SET v_ArmID = p_BArmID;
    SET v_HairID = p_BHairID;
    SET v_FaceID = p_BFaceID;
    SET v_ClothID = p_BClothID;
  ELSE
    SET v_ArmID = p_GArmID;
    SET v_HairID = p_GHairID;
    SET v_FaceID = p_GFaceID;
    SET v_ClothID = p_GClothID;
  END IF;
  SET v_style = CONCAT(',,', CAST(v_HairID AS CHAR(20)), ',,', CAST(v_ClothID AS CHAR(20)), ',', CAST(v_FaceID AS CHAR(20)), ',', CAST(v_ArmID AS CHAR(20)));
  SET v_color = CONCAT(',,', p_HairColor, ',,', p_ClothColor, ',', p_FaceColor, ',', p_ArmColor);
  START TRANSACTION;
  SELECT `Attack`, `Defence`, `Agility`, `Luck`, `CategoryID` INTO v_Attack, v_Defence, v_Agility, v_Luck, v_CategoryID FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_ArmID LIMIT 1;
  IF IFNULL(v_CategoryID, 0) = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) VALUES (v_UserID, 0, v_ArmID, v_CategoryID - 1, 1, 1, p_ArmColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), 0);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SELECT v_Attack + `Attack`, v_Defence + `Defence`, v_Agility + `Agility`, v_Luck + `Luck`, `CategoryID` INTO v_Attack, v_Defence, v_Agility, v_Luck, v_CategoryID FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_HairID LIMIT 1;
  IF IFNULL(v_CategoryID, 0) = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) VALUES (v_UserID, 0, v_HairID, v_CategoryID - 1, 1, 1, p_HairColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), 15);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SELECT v_Attack + `Attack`, v_Defence + `Defence`, v_Agility + `Agility`, v_Luck + `Luck`, `CategoryID` INTO v_Attack, v_Defence, v_Agility, v_Luck, v_CategoryID FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_FaceID LIMIT 1;
  IF IFNULL(v_CategoryID, 0) = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) VALUES (v_UserID, 0, v_FaceID, v_CategoryID - 1, 1, 1, p_FaceColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), 15);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  SELECT v_Attack + `Attack`, v_Defence + `Defence`, v_Agility + `Agility`, v_Luck + `Luck`, `CategoryID` INTO v_Attack, v_Defence, v_Agility, v_Luck, v_CategoryID FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_ClothID LIMIT 1;
  IF IFNULL(v_CategoryID, 0) = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefendCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) VALUES (v_UserID, 0, v_ClothID, v_CategoryID - 1, 1, 1, p_ClothColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), 15);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `NickName` = p_NickName, `IsFirst` = 1, `Style` = v_style, `Colors` = v_color, `Sex` = p_Sex WHERE `UserID` = v_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Fight` SET `Attack` = v_Attack, `Defence` = v_Defence, `Agility` = v_Agility, `Luck` = v_Luck WHERE `UserID` = v_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Users_RegisterNotValidate`$$
CREATE PROCEDURE `SP_Users_RegisterNotValidate`(IN p_UserName VARCHAR(200), IN p_PassWord VARCHAR(200), IN p_NickName VARCHAR(50), IN p_BArmID INT, IN p_BHairID INT, IN p_BFaceID INT, IN p_BClothID INT, IN p_BHatID INT, IN p_GArmID INT, IN p_GHairID INT, IN p_GFaceID INT, IN p_GClothID INT, IN p_GHatID INT, IN p_ArmColor VARCHAR(50), IN p_HairColor VARCHAR(50), IN p_FaceColor VARCHAR(50), IN p_ClothColor VARCHAR(50), IN p_HatColor VARCHAR(50), IN p_Sex INT, IN p_StyleDate INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_ArmID INT DEFAULT NULL;
  DECLARE v_HairID INT DEFAULT NULL;
  DECLARE v_FaceID INT DEFAULT NULL;
  DECLARE v_ClothID INT DEFAULT NULL;
  DECLARE v_HatID INT DEFAULT NULL;
  DECLARE v_isFirst INT DEFAULT NULL;
  DECLARE v_UserID INT DEFAULT NULL;
  DECLARE v_CategoryID INT DEFAULT NULL;
  DECLARE v_Attack INT DEFAULT NULL;
  DECLARE v_Defence INT DEFAULT NULL;
  DECLARE v_Agility INT DEFAULT NULL;
  DECLARE v_Luck INT DEFAULT NULL;
  DECLARE v_tempSex INT DEFAULT NULL;
  DECLARE v_style VARCHAR(1000) DEFAULT NULL;
  DECLARE v_color VARCHAR(1000) DEFAULT NULL;
  DECLARE v_nickIsExist INT DEFAULT NULL;
  DECLARE v_ArmPic VARCHAR(50) DEFAULT NULL;
  DECLARE v_HairPic VARCHAR(50) DEFAULT NULL;
  DECLARE v_FacePic VARCHAR(50) DEFAULT NULL;
  DECLARE v_ClothPic VARCHAR(50) DEFAULT NULL;
  DECLARE v_HatPic VARCHAR(50) DEFAULT NULL;
  DECLARE v_TemplateID INT DEFAULT NULL;
  DECLARE v_Count INT DEFAULT NULL;
  DECLARE v_ValidDate INT DEFAULT NULL;
  DECLARE v_StrengthenLevel INT DEFAULT NULL;
  DECLARE v_AttackCompose INT DEFAULT NULL;
  DECLARE v_DefEndCompose INT DEFAULT NULL;
  DECLARE v_LuckCompose INT DEFAULT NULL;
  DECLARE v_AgilityCompose INT DEFAULT NULL;
  DECLARE v_IsBinds TINYINT(1) DEFAULT NULL;
  DECLARE v_BagType INT DEFAULT NULL;
  DECLARE v_MaxCount INT DEFAULT NULL;
  DECLARE v_Index INT DEFAULT NULL;
  DECLARE v_ItemCount INT DEFAULT NULL;
  DECLARE v_bag0 INT DEFAULT NULL;
  DECLARE v_bag1 INT DEFAULT NULL;
  DECLARE v_bag2 INT DEFAULT NULL;
  DECLARE v_CurrentPlace INT DEFAULT NULL;
  DECLARE v_getCount INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_nickIsExist FROM `Sys_Users_Detail` WHERE `NickName` = p_NickName LIMIT 1;
  IF v_nickIsExist <> 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  IF p_Sex = -1 THEN
    SELECT `IsFirst`, `UserID`, `Sex` INTO v_isFirst, v_UserID, p_Sex FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  ELSE
    SELECT `IsFirst`, `UserID` INTO v_isFirst, v_UserID FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName LIMIT 1;
  END IF;
  IF IFNULL(v_isFirst, 1) > 0 THEN
    SET p_ReturnValue = 3;
    LEAVE proc;
  END IF;
  IF p_Sex <> 0 THEN
    SET v_ArmID = p_BArmID;
    SET v_HairID = p_BHairID;
    SET v_FaceID = p_BFaceID;
    SET v_ClothID = p_BClothID;
    SET v_HatID = p_BHatID;
    SET v_tempSex = 1;
  ELSE
    SET v_ArmID = p_GArmID;
    SET v_HairID = p_GHairID;
    SET v_FaceID = p_GFaceID;
    SET v_ClothID = p_GClothID;
    SET v_HatID = p_GHatID;
    SET v_tempSex = 2;
  END IF;
  SELECT `Pic` INTO v_ArmPic FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_ArmID LIMIT 1;
  SELECT `Pic` INTO v_HairPic FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_HairID LIMIT 1;
  SELECT `Pic` INTO v_FacePic FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_FaceID LIMIT 1;
  SELECT `Pic` INTO v_ClothPic FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_ClothID LIMIT 1;
  SELECT `Pic` INTO v_HatPic FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_HatID LIMIT 1;
  SET v_style = CONCAT(',,', CAST(v_HairID AS CHAR(20)), '|', CAST(v_HairPic AS CHAR(20)), ',,', CAST(v_ClothID AS CHAR(20)), '|', CAST(v_ClothPic AS CHAR(20)), ',', CAST(v_FaceID AS CHAR(20)), '|', CAST(v_FacePic AS CHAR(20)), ',', CAST(v_ArmID AS CHAR(20)), '|', CAST(v_ArmPic AS CHAR(20)), ',,,,');
  SET v_color = CONCAT(',,', p_HairColor, ',,', p_ClothColor, ',', p_FaceColor, ',', p_ArmColor, ',,,,');
  START TRANSACTION;
  IF 1 IS NOT NULL THEN
    DROP TEMPORARY TABLE IF EXISTS `tmp_Bag`;
  END IF;
  CREATE TEMPORARY TABLE `tmp_Bag` (`id` INT NULL AUTO_INCREMENT PRIMARY KEY, `TemplateID` INT NOT NULL, `Count` INT NOT NULL, `ValidDate` INT NOT NULL, `StrengthenLevel` INT NOT NULL, `AttackCompose` INT NOT NULL, `DefEndCompose` INT NOT NULL, `LuckCompose` INT NOT NULL, `AgilityCompose` INT NOT NULL, `IsBinds` TINYINT(1) NOT NULL, `BagType` INT NOT NULL, `MaxCount` INT NOT NULL);
  INSERT INTO `tmp_Bag` (`TemplateID`, `Count`, `ValidDate`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BagType`, `MaxCount`) SELECT `Bag_Init`.`TemplateID`, `Bag_Init`.`Count`, `Bag_Init`.`ValidDate`, `Bag_Init`.`StrengthenLevel`, `Bag_Init`.`AttackCompose`, `Bag_Init`.`DefEndCompose`, `Bag_Init`.`LuckCompose`, `Bag_Init`.`AgilityCompose`, `Bag_Init`.`IsBinds`, CASE `Shop_Goods`.`CategoryID` WHEN 1 THEN 0 WHEN 2 THEN 0 WHEN 3 THEN 0 WHEN 4 THEN 0 WHEN 5 THEN 0 WHEN 6 THEN 0 WHEN 7 THEN 0 WHEN 8 THEN 0 WHEN 9 THEN 0 WHEN 10 THEN 1 WHEN 11 THEN 1 WHEN 12 THEN 2 ELSE -1 END, `Shop_Goods`.`MaxCount` FROM `Bag_Init` LEFT JOIN `Project_Game34`.`Shop_Goods` ON `Bag_Init`.`TemplateID` = `Shop_Goods`.`TemplateID` WHERE `sex` = 0 OR `sex` = v_tempSex AND `Shop_Goods`.`CategoryID` IS NOT NULL;
  SET v_Index = 1;
  SELECT COUNT(*) INTO v_ItemCount FROM `tmp_Bag` LIMIT 1;
  SET v_bag0 = 31;
  SET v_bag1 = 0;
  SET v_bag2 = 0;
  SELECT `Attack`, `Defence`, `Agility`, `Luck`, `CategoryID` INTO v_Attack, v_Defence, v_Agility, v_Luck, v_CategoryID FROM `Project_Game34`.`Shop_Goods` WHERE `TemplateID` = v_ArmID LIMIT 1;
  IF IFNULL(v_CategoryID, 0) = 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF (v_ArmID <> 0) THEN
    INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `IsUsed`) VALUES (v_UserID, 0, v_ArmID, 6, 1, 1, p_ArmColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), p_StyleDate, 1);
  END IF;
  IF (v_HairID <> 0) THEN
    INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `IsUsed`) VALUES (v_UserID, 0, v_HairID, 2, 1, 1, p_HairColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), p_StyleDate, 1);
  END IF;
  IF (v_FaceID <> 0) THEN
    INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `IsUsed`) VALUES (v_UserID, 0, v_FaceID, 5, 1, 1, p_FaceColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), p_StyleDate, 1);
  END IF;
  IF (v_ClothID <> 0) THEN
    INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `IsUsed`) VALUES (v_UserID, 0, v_ClothID, 4, 1, 1, p_ClothColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), p_StyleDate, 1);
  END IF;
  IF (v_HatID <> 0) THEN
    INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`, `IsUsed`) VALUES (v_UserID, 0, v_HatID, 0, 1, 1, p_HatColor, 1, 0, 0, 0, 0, 0, 1, NOW(3), p_StyleDate, 1);
  END IF;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  w1: WHILE v_Index <= v_ItemCount DO
    SELECT `TemplateID`, `Count`, `ValidDate`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BagType`, `MaxCount` INTO v_TemplateID, v_Count, v_ValidDate, v_StrengthenLevel, v_AttackCompose, v_DefEndCompose, v_LuckCompose, v_AgilityCompose, v_IsBinds, v_BagType, v_MaxCount FROM `tmp_Bag` WHERE `id` = v_Index LIMIT 1;
    SET v_Index = v_Index + 1;
    w2: WHILE v_Count > 0 DO
      IF v_Count > v_MaxCount THEN
        SET v_getCount = v_MaxCount;
      ELSE
        SET v_getCount = v_Count;
      END IF;
      SET v_Count = v_Count - v_getCount;
      IF v_BagType = 0 THEN
        SET v_CurrentPlace = v_bag0;
        SET v_bag0 = v_bag0 + 1;
      ELSE
        IF v_BagType = 1 THEN
          SET v_CurrentPlace = v_bag1;
          SET v_bag1 = v_bag1 + 1;
        ELSE
          SET v_CurrentPlace = v_bag2;
          SET v_bag2 = v_bag2 + 1;
        END IF;
      END IF;
      IF v_CurrentPlace > 49 THEN
        ITERATE w2;
      END IF;
      INSERT INTO `Sys_Users_Goods` (`UserID`, `BagType`, `TemplateID`, `Place`, `Count`, `IsJudge`, `Color`, `IsExist`, `StrengthenLevel`, `AttackCompose`, `DefEndCompose`, `LuckCompose`, `AgilityCompose`, `IsBinds`, `BeginDate`, `ValidDate`) VALUES (v_UserID, v_BagType, v_TemplateID, v_CurrentPlace, v_getCount, 1, '', 1, v_StrengthenLevel, v_AttackCompose, v_DefEndCompose, v_LuckCompose, v_AgilityCompose, v_IsBinds, NOW(3), v_ValidDate);
      IF 0 <> 0 THEN
        ROLLBACK;
        SET p_ReturnValue = 0;
        LEAVE proc;
      END IF;
    END WHILE w2;
  END WHILE w1;
  UPDATE `Sys_Users_Detail` SET `NickName` = p_NickName, `IsFirst` = 17, `Style` = v_style, `Colors` = v_color, `Sex` = p_Sex WHERE `UserID` = v_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Fight` SET `Attack` = v_Attack, `Defence` = v_Defence, `Agility` = v_Agility, `Luck` = v_Luck WHERE `UserID` = v_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

