  END IF;
  SELECT COUNT(*) INTO v_count FROM `Sys_Users_Detail` WHERE `NickName` = p_NewNickName LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_count FROM `Rename_Nick` WHERE `NickName` = p_NewNickName LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Rename_Nick` (`UserId`, `UserName`, `NickName`, `Date`, `IsExist`, `OldNickName`) VALUES (v_UserID, p_UserName, p_NewNickName, NOW(3), 1, p_NickName);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `Rename` = 0 WHERE `UserId` = v_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `SP_Users_RenameNick2`$$
CREATE PROCEDURE `SP_Users_RenameNick2`(IN p_UserName VARCHAR(200), IN p_NickName VARCHAR(200), IN p_NewNickName VARCHAR(200), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_UserID INT DEFAULT NULL;
  DECLARE v_count INT DEFAULT NULL;
  DECLARE v_Rename TINYINT(1) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  IF p_NickName IS NULL OR p_NewNickName IS NULL THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
  SELECT IFNULL(`UserID`, 0), `Rename` INTO v_UserID, v_Rename FROM `Sys_Users_Detail` WHERE `UserName` = p_UserName AND `NickName` = p_NickName LIMIT 1;
  IF v_UserID = 0 THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_count FROM `Sys_Users_Detail` WHERE `NickName` = p_NewNickName LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 4;
    LEAVE proc;
  END IF;
  SELECT COUNT(*) INTO v_count FROM `Rename_Nick` WHERE `NickName` = p_NewNickName LIMIT 1;
  IF v_count <> 0 THEN
    SET p_ReturnValue = 5;
    LEAVE proc;
  END IF;
  START TRANSACTION;
  INSERT INTO `Rename_Nick` (`UserId`, `UserName`, `NickName`, `Date`, `IsExist`, `OldNickName`) VALUES (v_UserID, p_UserName, p_NewNickName, NOW(3), 0, p_NickName);
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Detail` SET `Rename` = 0, `NickName` = p_NewNickName WHERE `UserId` = v_UserID;
  UPDATE `Sys_Users_Detail` SET `SpouseName` = p_NewNickName WHERE `SpouseID` = v_UserID;
  UPDATE `Consortia` SET `ChairmanName` = p_NewNickName WHERE `ChairmanID` = v_UserID;
  UPDATE `Consortia_Users` SET `UserName` = p_NewNickName WHERE `UserID` = v_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

