DROP PROCEDURE IF EXISTS `SP_Users_Update`$$
CREATE PROCEDURE `SP_Users_Update`(IN p_UserID INT, IN p_Attack INT, IN p_Defence INT, IN p_Luck INT, IN p_Agility INT, IN p_Gold INT, IN p_Money INT, IN p_Style VARCHAR(200), IN p_Colors VARCHAR(200), IN p_Hide INT, IN p_Grade INT, IN p_GP INT, IN p_State INT, IN p_ConsortiaID INT, IN p_ExpendDate DATETIME(3), IN p_Win INT, IN p_Total INT, IN p_Escape INT, IN p_Skin VARCHAR(50), IN p_Offer INT, INOUT p_AntiAddiction INT, IN p_RichesOffer INT, IN p_RichesRob INT, INOUT p_CheckCount INT, IN p_MarryInfoID INT, IN p_DayLoginCount INT, IN p_Nimbus INT, IN p_LastAward DATETIME(3), IN p_GiftToken INT, IN p_QuestSite VARBINARY(200), IN p_PvePermission VARCHAR(50), IN p_FightPower INT, IN p_AnswerSite INT, IN p_LastAuncherAward DATETIME(3), IN p_hp INT, IN p_ChatCount INT, IN p_SpaPubGoldRoomLimit INT, IN p_LastSpaDate DATETIME(3), IN p_FightLabPermission VARCHAR(50), IN p_SpaPubMoneyRoomLimit INT, IN p_IsInSpaPubGoldToday TINYINT(1), IN p_IsInSpaPubMoneyToday TINYINT(1), IN p_AchievementPoint INT, IN p_LastWeekly DATETIME(3), IN p_LastWeeklyVersion INT, IN p_WeaklessGuildProgressStr VARCHAR(1000), IN p_IsOldPlayer TINYINT(1), IN p_VIPLevel INT, IN p_VIPExp INT, IN p_Score INT, IN p_OptionOnOff INT, IN p_isOldPlayerHasValidEquitAtLogin TINYINT(1), IN p_badLuckNumber INT, IN p_luckyNum INT, IN p_lastLuckyNumDate DATETIME(3), IN p_lastLuckNum INT, IN p_IsShowConsortia TINYINT(1), IN p_NewDay DATETIME(3), IN p_Medal INT, IN p_Honor VARCHAR(50), IN p_VIPNextLevelDaysNeeded INT, IN p_IsRecharged TINYINT(1), IN p_IsGetAward TINYINT(1), IN p_typeVIP INT, IN p_evolutionGrade INT, IN p_evolutionExp INT, IN p_hardCurrency INT, IN p_EliteScore INT, IN p_UseOffer INT, IN p_ShopFinallyGottenTime DATETIME(3), IN p_MoneyLock INT, IN p_LastGetEgg DATETIME(3), IN p_IsFistGetPet TINYINT(1), IN p_LastRefreshPet DATETIME(3), IN p_petScore INT, IN p_accumulativeLoginDays INT, IN p_accumulativeAwardDays INT, IN p_honorId INT, IN p_Repute INT, IN p_damageScores INT, IN p_totemId INT, IN p_myHonor INT, IN p_MaxBuyHonor INT, IN p_necklaceExp INT, IN p_necklaceExpAdd INT, IN p_GhostEquipList LONGTEXT, IN p_fineSuitExp INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_IsExist TINYINT(1) DEFAULT NULL;
  DECLARE v_ForbidDate DATETIME(3) DEFAULT NULL;
  DECLARE v_OrdState INT DEFAULT NULL;
  DECLARE v_AntiDate DATETIME(3) DEFAULT NULL;
  DECLARE v_OnlineTime INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET p_ReturnValue = 0;
  SET v_OnlineTime = 0;
  SELECT `State`, `AntiDate`, `AntiAddiction`, `ForbidDate`, `IsExist` INTO v_OrdState, v_AntiDate, p_AntiAddiction, v_ForbidDate, v_IsExist FROM `Sys_Users_Detail` WHERE `UserID` = p_UserID LIMIT 1;
  IF DAY(v_AntiDate) <> DAY(NOW(3)) THEN
    SET v_AntiDate = NOW(3);
    SET p_AntiAddiction = 0;
    SET p_CheckCount = 0;
  ELSE
    IF v_OrdState <> 0 THEN
      SET v_OnlineTime = IFNULL(TIMESTAMPDIFF(MINUTE, DATE_FORMAT(v_AntiDate, '%Y-%m-%d %H:%i:00'), DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:00')), 0);
      SET p_AntiAddiction = p_AntiAddiction + v_OnlineTime;
    END IF;
    SET v_AntiDate = NOW(3);
  END IF;
  START TRANSACTION;
  IF p_ExpendDate = '' THEN
    UPDATE `Sys_Users_Detail` SET `Gold` = p_Gold, `Money` = p_Money, `Style` = p_Style, `Colors` = p_Colors, `Grade` = p_Grade, `GP` = p_GP, `State` = p_State, `AntiDate` = v_AntiDate, `OnlineTime` = `OnlineTime` + v_OnlineTime, `RichesOffer` = p_RichesOffer, `RichesRob` = p_RichesRob, `ForbidDate` = v_ForbidDate, `IsExist` = v_IsExist, `Hide` = p_Hide, `Win` = p_Win, `Total` = p_Total, `Escape` = p_Escape, `Skin` = p_Skin, `Offer` = p_Offer, `AntiAddiction` = p_AntiAddiction, `CheckCount` = p_CheckCount, `MarryInfoID` = p_MarryInfoID, `DayLoginCount` = p_DayLoginCount, `Nimbus` = p_Nimbus, `LastAward` = p_LastAward, `GiftToken` = p_GiftToken, `QuestSite` = p_QuestSite, `PvePermission` = p_PvePermission, `FightPower` = p_FightPower, `AnswerSite` = p_AnswerSite, `LastAuncherAward` = p_LastAuncherAward, `Medal` = p_Medal, `ChatCount` = p_ChatCount, `SpaPubGoldRoomLimit` = p_SpaPubGoldRoomLimit, `LastSpaDate` = p_LastSpaDate, `FightLabPermission` = p_FightLabPermission, `SpaPubMoneyRoomLimit` = p_SpaPubMoneyRoomLimit, `IsInSpaPubGoldToday` = p_IsInSpaPubGoldToday, `IsInSpaPubMoneyToday` = p_IsInSpaPubMoneyToday, `AchievementPoint` = p_AchievementPoint, `LastWeekly` = p_LastWeekly, `LastWeeklyVersion` = p_LastWeeklyVersion, `WeaklessGuildProgressStr` = p_WeaklessGuildProgressStr, `IsOldPlayer` = p_IsOldPlayer, `Score` = p_Score, `OptionOnOff` = p_OptionOnOff, `isOldPlayerHasValidEquitAtLogin` = p_isOldPlayerHasValidEquitAtLogin, `badLuckNumber` = p_badLuckNumber, `luckyNum` = p_luckyNum, `lastLuckyNumDate` = p_lastLuckyNumDate, `lastLuckNum` = p_lastLuckNum, `IsShowConsortia` = p_IsShowConsortia, `NewDay` = p_NewDay, `Honor` = p_Honor, `IsRecharged` = p_IsRecharged, `IsGetAward` = p_IsGetAward, `evolutionGrade` = p_evolutionGrade, `evolutionExp` = p_evolutionExp, `hardCurrency` = p_hardCurrency, `EliteScore` = p_EliteScore, `UseOffer` = p_UseOffer, `ShopFinallyGottenTime` = p_ShopFinallyGottenTime, `MoneyLock` = p_MoneyLock, `LastGetEgg` = p_LastGetEgg, `IsFistGetPet` = p_IsFistGetPet, `LastRefreshPet` = p_LastRefreshPet, `petScore` = p_petScore, `accumulativeLoginDays` = p_accumulativeLoginDays, `accumulativeAwardDays` = p_accumulativeAwardDays, `honorId` = p_honorId, `Repute` = p_Repute, `damageScores` = p_damageScores, `totemId` = p_totemId, `myHonor` = p_myHonor, `MaxBuyHonor` = p_MaxBuyHonor, `necklaceExp` = p_necklaceExp, `necklaceExpAdd` = p_necklaceExpAdd, `GhostEquipList` = IFNULL(p_GhostEquipList, `GhostEquipList`), `fineSuitExp` = IFNULL(p_fineSuitExp, `fineSuitExp`) WHERE `UserID` = p_UserID;
  ELSE
    UPDATE `Sys_Users_Detail` SET `Gold` = p_Gold, `Money` = p_Money, `Style` = p_Style, `Colors` = p_Colors, `Grade` = p_Grade, `GP` = p_GP, `State` = p_State, `AntiDate` = v_AntiDate, `OnlineTime` = `OnlineTime` + v_OnlineTime, `RichesOffer` = p_RichesOffer, `RichesRob` = p_RichesRob, `ForbidDate` = v_ForbidDate, `IsExist` = v_IsExist, `Hide` = p_Hide, `ExpendDate` = p_ExpendDate, `Win` = p_Win, `Total` = p_Total, `Escape` = p_Escape, `Skin` = p_Skin, `Offer` = p_Offer, `AntiAddiction` = p_AntiAddiction, `CheckCount` = p_CheckCount, `MarryInfoID` = p_MarryInfoID, `DayLoginCount` = p_DayLoginCount, `Nimbus` = p_Nimbus, `LastAward` = p_LastAward, `GiftToken` = p_GiftToken, `QuestSite` = p_QuestSite, `PvePermission` = p_PvePermission, `FightPower` = p_FightPower, `AnswerSite` = p_AnswerSite, `LastAuncherAward` = p_LastAuncherAward, `Medal` = p_Medal, `ChatCount` = p_ChatCount, `SpaPubGoldRoomLimit` = p_SpaPubGoldRoomLimit, `LastSpaDate` = p_LastSpaDate, `FightLabPermission` = p_FightLabPermission, `SpaPubMoneyRoomLimit` = p_SpaPubMoneyRoomLimit, `IsInSpaPubGoldToday` = p_IsInSpaPubGoldToday, `IsInSpaPubMoneyToday` = p_IsInSpaPubMoneyToday, `AchievementPoint` = p_AchievementPoint, `LastWeekly` = p_LastWeekly, `LastWeeklyVersion` = p_LastWeeklyVersion, `WeaklessGuildProgressStr` = p_WeaklessGuildProgressStr, `IsOldPlayer` = p_IsOldPlayer, `Score` = p_Score, `OptionOnOff` = p_OptionOnOff, `isOldPlayerHasValidEquitAtLogin` = p_isOldPlayerHasValidEquitAtLogin, `badLuckNumber` = p_badLuckNumber, `luckyNum` = p_luckyNum, `lastLuckyNumDate` = p_lastLuckyNumDate, `lastLuckNum` = p_lastLuckNum, `IsShowConsortia` = p_IsShowConsortia, `NewDay` = p_NewDay, `Honor` = p_Honor, `IsRecharged` = p_IsRecharged, `IsGetAward` = p_IsGetAward, `evolutionGrade` = p_evolutionGrade, `evolutionExp` = p_evolutionExp, `hardCurrency` = p_hardCurrency, `EliteScore` = p_EliteScore, `UseOffer` = p_UseOffer, `ShopFinallyGottenTime` = p_ShopFinallyGottenTime, `MoneyLock` = p_MoneyLock, `LastGetEgg` = p_LastGetEgg, `IsFistGetPet` = p_IsFistGetPet, `LastRefreshPet` = p_LastRefreshPet, `petScore` = p_petScore, `accumulativeLoginDays` = p_accumulativeLoginDays, `accumulativeAwardDays` = p_accumulativeAwardDays, `honorId` = p_honorId, `Repute` = p_Repute, `damageScores` = p_damageScores, `totemId` = p_totemId, `myHonor` = p_myHonor, `MaxBuyHonor` = p_MaxBuyHonor, `necklaceExp` = p_necklaceExp, `necklaceExpAdd` = p_necklaceExpAdd, `GhostEquipList` = IFNULL(p_GhostEquipList, `GhostEquipList`), `fineSuitExp` = IFNULL(p_fineSuitExp, `fineSuitExp`) WHERE `UserID` = p_UserID;
  END IF;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Fight` SET `Attack` = p_Attack, `Defence` = p_Defence, `Luck` = p_Luck, `Agility` = p_Agility, `hp` = p_hp WHERE `UserID` = p_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_VIP_Info` SET `VIPLevel` = p_VIPLevel, `VIPExp` = p_VIPExp, `VIPNextLevelDaysNeeded` = p_VIPNextLevelDaysNeeded, `typeVIP` = p_typeVIP WHERE `UserID` = p_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  UPDATE `Sys_Users_Extra` SET `TotalCaddyOpen` = p_badLuckNumber WHERE `UserID` = p_UserID;
  IF 0 <> 0 THEN
    ROLLBACK;
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  COMMIT;
  SET p_ReturnValue = 0;
  LEAVE proc;
END$$

