DROP PROCEDURE IF EXISTS `SP_VIPRenewal_Single`$$
CREATE PROCEDURE `SP_VIPRenewal_Single`(IN p_NickName VARCHAR(200), IN p_RenewalDays INT, INOUT p_ExpireDayOut DATETIME(3), IN p_typeVIP INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_UserID INT DEFAULT NULL;
  DECLARE v_ExpireDay DATETIME(3) DEFAULT NULL;
  DECLARE v_Exp INT DEFAULT NULL;
  DECLARE v_Level INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT `UserID`, `VIPExpireDay`, `VIPLevel`, `VIPExp` INTO v_UserID, v_ExpireDay, v_Level, v_Exp FROM `V_Sys_Users_Detail` WHERE `NickName` = p_NickName AND `IsExist` = 1 LIMIT 1;
  IF v_ExpireDay < NOW(3) OR v_ExpireDay = NOW(3) THEN
    SET v_ExpireDay = DATE_ADD(NOW(3), INTERVAL p_RenewalDays DAY);
  ELSE
    SET v_ExpireDay = DATE_ADD(v_ExpireDay, INTERVAL p_RenewalDays DAY);
  END IF;
  SET p_ExpireDayOut = v_ExpireDay;
  UPDATE `Sys_VIP_Info` SET `typeVIP` = p_typeVIP, `VIPLevel` = v_Level, `VIPExp` = v_Exp, `VIPExpireDay` = v_ExpireDay, `LastVIPPackTime` = NOW(3), `CanTakeVipReward` = 1 WHERE `UserID` = v_UserID;
  SET p_ReturnValue = 1;
  LEAVE proc;
END$$

DROP PROCEDURE IF EXISTS `Sp_Renames_Batch`$$
CREATE PROCEDURE `Sp_Renames_Batch`(OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  CREATE TEMPORARY TABLE `tmp_Temp_User` (`UserId` INT NULL, `NickName` VARCHAR(50) NULL);
  INSERT INTO `tmp_Temp_User` SELECT `B`.`UserID`, `B`.`NickName` FROM (SELECT `UserName`, MAX(`ID`) AS `ID` FROM `Rename_Nick` WHERE `IsExist` = 1 GROUP BY `UserName`) AS `A` LEFT JOIN `Rename_Nick` AS `B` ON `A`.`ID` = `B`.`ID`;
  UPDATE `Consortia` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`CreatorName` = `B`.`NickName` WHERE `A`.`CreatorID` = `B`.`UserId`;
  UPDATE `Consortia` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`ChairmanName` = `B`.`NickName` WHERE `A`.`ChairmanID` = `B`.`UserId`;
  UPDATE `Consortia_Apply_Users` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`UserName` = `B`.`NickName` WHERE `A`.`UserID` = `B`.`UserId`;
  UPDATE `Consortia_Invite_Users` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`UserName` = `B`.`NickName` WHERE `A`.`UserID` = `B`.`UserId`;
  UPDATE `Consortia_Invite_Users` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`InviteName` = `B`.`NickName` WHERE `A`.`InviteID` = `B`.`UserId`;
  UPDATE `Consortia_Users` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`UserName` = `B`.`NickName` WHERE `A`.`UserID` = `B`.`UserId`;
  UPDATE `Consortia_Users` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`RatifierName` = `B`.`NickName` WHERE `A`.`RatifierID` = `B`.`UserId`;
  UPDATE `Marry_Apply` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`ApplyUserName` = `B`.`NickName` WHERE `A`.`ApplyUserID` = `B`.`UserId`;
  UPDATE `Marry_Room_Info` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`PlayerName` = `B`.`NickName` WHERE `A`.`PlayerID` = `B`.`UserId`;
  UPDATE `Marry_Room_Info` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`GroomName` = `B`.`NickName` WHERE `A`.`GroomID` = `B`.`UserId`;
  UPDATE `Marry_Room_Info` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`BrideName` = `B`.`NickName` WHERE `A`.`BrideID` = `B`.`UserId`;
  UPDATE `User_Messages` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`Receiver` = `B`.`NickName` WHERE `A`.`ReceiverID` = `B`.`UserId`;
  UPDATE `User_Messages` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`Sender` = `B`.`NickName` WHERE `A`.`SenderID` = `B`.`UserId`;
  UPDATE `Sys_Users_Detail` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`SpouseName` = `B`.`NickName` WHERE `A`.`SpouseID` = `B`.`UserId`;
  UPDATE `Sys_Users_Detail` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`NickName` = `B`.`NickName` WHERE `A`.`UserId` = `B`.`UserId`;
  UPDATE `Auction` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`AuctioneerName` = `B`.`NickName` WHERE `A`.`AuctioneerID` = `B`.`UserId`;
  UPDATE `Auction` AS `A`, `tmp_Temp_User` AS `B` SET `A`.`BuyerName` = `B`.`NickName` WHERE `A`.`BuyerID` = `B`.`UserId`;
  UPDATE `Rename_Nick` SET `IsExist` = 0 WHERE `IsExist` = 1;
  DROP TEMPORARY TABLE IF EXISTS `tmp_Temp_User`;
  CREATE TEMPORARY TABLE `tmp_Temp_Consortia` (`ConsortiaID` INT NULL, `ConsortiaName` VARCHAR(200) NULL);
  INSERT INTO `tmp_Temp_Consortia` SELECT `ConsortiaID`, `ConsortiaName` FROM `Rename_Consortia` WHERE `IsExist` = 1;
  UPDATE `Consortia_Apply_Users` AS `A`, `tmp_Temp_Consortia` AS `B` SET `A`.`ConsortiaName` = `B`.`ConsortiaName` WHERE `A`.`ConsortiaID` = `B`.`ConsortiaID`;
  UPDATE `Consortia_Invite_Users` AS `A`, `tmp_Temp_Consortia` AS `B` SET `A`.`ConsortiaName` = `B`.`ConsortiaName` WHERE `A`.`ConsortiaID` = `B`.`ConsortiaID`;
  UPDATE `Consortia` AS `A`, `tmp_Temp_Consortia` AS `B` SET `A`.`ConsortiaName` = `B`.`ConsortiaName` WHERE `A`.`ConsortiaID` = `B`.`ConsortiaID`;
  UPDATE `Rename_Consortia` SET `IsExist` = 0 WHERE `IsExist` = 1;
  DROP TEMPORARY TABLE IF EXISTS `tmp_Temp_Consortia`;
END$$

