DROP PROCEDURE IF EXISTS `UpdateActiveSystem`$$
CREATE PROCEDURE `UpdateActiveSystem`(IN p_ID INT, IN p_UserID INT, IN p_canOpenCounts INT, IN p_canEagleEyeCounts INT, IN p_lastFlushTime DATETIME(3), IN p_isShowAll TINYINT(1), OUT p_ReturnValue INT)
proc: BEGIN
  SET p_ReturnValue = 0;
  UPDATE `Sys_Active_System_Data` SET `UserID` = p_UserID, `canOpenCounts` = p_canOpenCounts, `canEagleEyeCounts` = p_canEagleEyeCounts, `lastFlushTime` = p_lastFlushTime, `isShowAll` = p_isShowAll WHERE `ID` = p_ID;
  SET p_ReturnValue = 0;
  LEAVE proc;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 1;
    LEAVE proc;
  END IF;
END$$

DELIMITER ;
